const ll MOD = 1000000007;

ll solve(vector<ll>& a, int n, bool posi){
	ll ans = 0, s = 0;
	for(int i=0;i<n;i++){
		s += a[i];
		if(posi){
			ll diff = max(0LL, -s + 1);
			s += diff;
			ans += diff;
			assert(s > 0);
		}else{
			ll diff = max(0LL, s + 1);
			s -= diff;
			ans += diff;
			assert(s < 0);
		}
		posi = !posi;
	}
	return ans;
}

