ll solve(ll p){
  ll res = 0;
  ll sum = 0;
  for(ll i=0;i<N;i++) {
    ll a = A[i];
    sum += a;
    if (i) {
      if ((i+p) & 1) { // -
        if (sum < 0) continue;
        res += abs((-1 - sum));
        sum = -1;
      } else { // +
        if (sum > 0) continue;
        res += abs((1 - sum));
        sum = 1;
      }
    } else {
      if( sum == 0 ) {
        if (!p) sum = -1;
        else sum = 1;
        res = 1;
      }
    }
  }
  return res;
}


