	  offset += 1 - val;
	}
	if(i % 2 == 0 && val >= 0)
	{
	  sum_first_neg += val + 1;
	  offset -= val + 1;
	}
  }
  cout << min(sum_first_neg, sum_first_pos) << endl;  
