int improveSeq(vector<int> &a, bool positive) {
  int res = 0;
  int sum = 0;
  for (int i = 0; i < a.size(); i++) {
    int nextSum = sum + a.at(i);
    if (positive && nextSum >= 0) {
      a.at(i) -= (nextSum + 1);
      res += nextSum + 1;
    }
    if (!positive && nextSum <= 0) {
      a.at(i) += (-nextSum + 1);
      res += -nextSum + 1;
    }
    sum += a.at(i);
    positive = !positive;
  }
  return res;
}

