ll calc(int start, int N) {
	if (start == 0) return 1ll<<55;
	ll sum = start;
	ll ret = 0;
	for (int i = 1; i < N; i++) {
		ll old = sum;
		sum += A[i];
		if (old > 0 && sum >= 0) {
			ret += sum+1;
			sum = -1;
		} else if (old < 0 && sum <= 0) {
			ret += -sum+1;
			sum = 1;
		}
	}
	return ret;
}

