const int MAXN = 5e5 + 5;

int N, Q;
int D, A[MAXN];
int QRY[MAXN];

void input()
{
    read(N); read(D);
    for (int i = 1; i <= N; ++i) {
        read(A[i]);
    }
    read(Q);
    for (int i = 1; i <= Q; ++i) {
        read(QRY[i]);
    }
}

void solve()
{
    static int pos[MAXN], dp[MAXN];

    pos[1] = D;
    for (int i = 1; i <= N; ++i) {
        pos[i + 1] = (A[i] < pos[i] * 2 ? abs(pos[i] - A[i]) : pos[i]);
    }
    dp[N] = 1;
    for (int i = N; i > 1; --i) {
        dp[i - 1] = dp[i] + (A[i] < dp[i] * 2) * A[i];
    }

    for (int i = 1; i <= Q; ++i) {
        puts(pos[QRY[i]] >= dp[QRY[i]] ? "YES" : "NO");
    }
}

