#include <bits/stdc++.h>
using namespace std;
using ll = long long;
using P = pair<int, int>;
const ll MOD = 1000000007;

ll solve(vector<ll>& a, int n){
	ll ans = 0, s = a[0];
	for(int i=1;i<n;i++){
		ll s_next = s + a[i];
		if(s < 0){
			// cout << s_next << " " << a[i] << endl;
			ll diff = 0;
			if(s_next <= 0){
				diff = -s_next + 1;
			}
			s_next += diff;
			ans += diff;
			// cout << s_next << " " << diff << endl;
			assert(s_next > 0);
		}else{
			// cout << s_next << " " << a[i] << endl;
			ll diff = 0;
			if(s_next >= 0){
				diff = s_next + 1;
			}
			s_next -= diff;
			ans += diff;
			// cout << s_next << " " << diff << endl;
			assert(s_next < 0);
		}
		s = s_next;
		// cout << ans << endl;
	}
	return ans;
}

int main(){
	int n;
	cin >> n;

	vector<ll> a(n);
	for(int i=0;i<n;i++){
		cin >> a[i];
	}

	ll ans;
	if(a[0] == 0){
		assert(0);
		a[0] = -1;
		ll ans = 1 + solve(a, n);
		a[0] = 1;
		ans = min(ans, 1 + solve(a, n));
	}else{
		ans = solve(a, n);
	}
	cout << ans << endl;

    return 0;
}

