            } else if (sum + a[i] > 0) {
                ll t = sum + 1 + a[i];
                ans += abs(t);
                a[i] -= t;
            } else {
                ll t = sum + a[i] - 1;
                ans += abs(t);
                a[i] -= t;
            }
        }
        sum += a[i];
        assert(sum != 0);
    }
