using namespace std;

typedef long long ll;

int n;
ll a[100010];

ll calc(bool state) {
  ll cur = 0;
  ll ret = 0;
  rep(i,n) {
    cur += a[i];
    if( state ) { // +
      if( cur == 0 ) {
	++cur;
	++ret;
      } else if( cur < 0LL ) {
	ret += (llabs(cur)+1LL);
	cur += (llabs(cur)+1LL);
      }
    } else { // -
      if( cur == 0 ) {
	--cur;
	++ret;
      } else if( cur > 0LL ) {
	ret += (llabs(cur)+1LL);
	cur -= (llabs(cur)+1LL);
      }
    }
    state = !state;
  }
  return ret;
}

void compute() {
  ll ans = LLONG_MAX;
  rep(i,2) ans = min(ans,calc(i));
  cout << ans << endl;
}

int main() {
  cin >> n;
  rep(i,n) cin >> a[i];
  compute();
  return 0;
}

