// 300, 9min

ll N;
ll A[MAX_N] = {};

int main()
{
    cin >> N;
    REP(i, N) { cin >> A[i]; }
    ll cur = A[0];
    ll ans = 0;
    if(A[0] == 0) {
        // 最初に 0 以外が出るところを見つける
        int first_non_zero = -1;
        for(int i = 1; i < N; ++i) {
            if(A[i] != 0) {
                first_non_zero = i;
                break;
            }
        }
        if(first_non_zero < 0) {
            ans++;
            cur = 1;
        }
        else if(first_non_zero % 2 == 0) {
            if(A[first_non_zero] > 0) {
                ans++;
                cur = 1;
            } else {
                ans++;
                cur = -1;
            }
        }
        else if(first_non_zero % 2 != 0) {
            if(A[first_non_zero] > 0) {
                ans++;
                cur = -1;
            } else {
                ans++;
                cur = 1;
            }
        }
    }
    ll prev = cur;
    for(int i=1; i < N; ++i) {
        cur += A[i];
        if(prev < 0 && cur <= 0) {
            int diff = abs(cur) + 1;
            cur += diff;
            ans += diff;
        }
        else if(prev > 0 && cur >= 0) {
            int diff = abs(cur) + 1;
            cur -= diff;
            ans += diff;
        }
        prev = cur;
    }
    printf("%lld\n", ans);
    return 0;
}

