using namespace std;

int improveSeq(vector<int> &a, bool positive) {
  int res = 0;
  int sum = a.at(0);
  for (int i = 1; i < a.size(); i++) {
    int nextSum = sum + a.at(i);
    if (positive && nextSum >= 0) {
      a.at(i) -= (nextSum + 1);
      res += abs(nextSum + 1);
    }
    if (!positive && nextSum <= 0) {
      a.at(i) += (-nextSum + 1);
      res += abs(-nextSum + 1);
    }
    sum += a.at(i);
    positive = sum > 0;
  }
  return res;
}

