	int n;
	cin >> n;
	ll S[100000];
	ll count = 0;

	for (int i = 0; i < n; i++) {
		ll a;
		cin >> a;
		if (i == 0)
		{
			S[i] = a;
		}
		else {
			S[i] = S[i - 1] + a;
		}
	}

	if (S[0] == 0)
	{
		if (S[1] <= 0) { S[0]++; }
		else { S[0]--; }
		count++;
	}

	ll diff = 0;
	ll diffSum = 0;
	for (int i = 0; i < n - 1; i++)
	{
		S[i + 1] += diffSum;
		if (S[i + 1] == 0)
		{
			if (S[i] < 0) S[i + 1]++;
			else  S[i + 1]--;

			count++;
			continue;
		}

		if ((S[i] > 0 && S[i + 1] > 0) || (S[i] < 0 && S[i + 1] < 0))
		{
			ll diff = abs(S[i + 1]) + 1;

			if (S[i + 1] < 0) {
				S[i + 1] += diff;
				diffSum += diff;
			}
			else {
				S[i + 1] += -diff;
				diffSum += -diff;
			}

			count += diff;
		}
	}
	printf("%d\n", count);
	//cout << count << endl;

	return 0;
}

