const int INF = 1e9;
const ld EPS = 1e-8;

ll solve(const vector<ll>& a, int k) {
  ll acc = 0, res = 0;
  REP(i,a.size()) {
    acc += a[i];
    if((i + k) % 2 == 1 && acc >= 0) {
      res += acc + 1;
      acc = -1;
    }else if((i + k) % 2 == 0 && acc <= 0) {
      res += 1 - acc;
      acc = 1;
    }
  }
  return res;
}

int main(){
  int n;
  cin >> n;
  vector<ll> a(n);
  REP(i,n) cin >> a[i];

  ll res = min(solve(a, 0), solve(a, 1));
  cout << res << endl;
  return 0;
}

