typedef long long ll;

int n;
ll a[100000];

ll solve(int i, bool s, ll p){
    if(i == n){
        return 0;
    }

    ll v = a[i] + p;

    ll q = 0;
    if(s && v <= 0){
        q = 1 - v;
    }
    else if(!s && v >= 0){
        q = -1 - v;
    }

    return abs(q) + solve(i + 1, !s, p + q);
}

int main(){
    cin >> n;
    rep(i, n){
        cin >> a[i];
    }

    rep(i, n - 1){
        a[i + 1] += a[i];
    }

    cout << min(solve(0, true, 0), solve(0, false, 0)) << endl;
    return 0;
}

