	int sign=a[0]>0 ? 1 : -1;
	long long sum=a[0],res=0;
	for(int i=1;i<n;i++) {
		sign=-sign; sum+=a[i];
		if(sum*sign <=0) {
			res+=-sum*sign + 1;
			sum = sign;
		}
	}
	return res;
}
