#define REP(i,n)   for(int i=0; i<(int)(n); i++)
#define FOR(i,b,e) for(int i=(b); i<=(int)(e); i++)

typedef long long ll;

const int N_MAX = 100000;

int n;
int a[N_MAX];

ll f(int sgn) {
  ll sum = 0, mv = 0;
  REP(i, n) {
    sum += a[i];
    if (sgn * sum <= 0) {
      mv += abs(sgn - sum);
      sum = sgn;
    }
    sgn = -sgn;
  }
  return mv;
}

void solve() {
  ll ans = min(f(1), f(-1));
  printf("%lld\n", ans);
}

void input() {
  scanf("%d", &n);
  REP(i, n) scanf("%d", a + i);
}

int main() {
  input();
  solve();
  return 0;
}

