long long cost(int n, int a[], bool flag) {
  long long sum = 0;
  long long res = 0;

  for (int i = 0; i < n; ++i) {
    sum += a[i];
    if (flag and sum <= 0) {
      res += 1 - sum;
      sum = 1;
    } else if (not flag and sum >= 0) {
      res += 1 + sum;
      sum = -1;
    }
    flag = not flag;
  }

  return res;
}

