ll calc(bool state) {
  ll cur = 0;
  ll ret = 0;
  rep(i,n) {
    cur += a[i];
    if( state ) { // +
      if( cur == 0 ) {
	++cur;
	++ret;
      } else if( cur < 0LL ) {
	ret += (llabs(cur)+1LL);
	cur += (llabs(cur)+1LL);
      }
    } else { // -
      if( cur == 0 ) {
	--cur;
	++ret;
      } else if( cur > 0LL ) {
	ret += (llabs(cur)+1LL);
	cur -= (llabs(cur)+1LL);
      }
    }
    state = !state;
  }
  return ret;
}

