    for (auto a : alist) {
        sum += a;
        sumlist.pb(sum);
    }

    // +-+- ...
    ll diff = 0LL;
    ll ans1 = 0LL;
    rep (i, n) {
        ll val = sumlist[i] + diff;
        if (i & 1LL) {
            if (val >= 0LL) {
                diff -= val + 1LL;
                ans1 += (val + 1LL);
            }
        }
        else {
            if (val <= 0LL) {
                diff += (-val + 1LL);
                ans1 += (-val + 1LL);
            }
        }
    }

    // -+-+ ...
    diff = 0LL;
    ll ans2 = 0LL;
    rep (i, n) {
        ll val = sumlist[i] + diff;
        if (i & 1LL) {
            if (val <= 0LL) {
                diff += -val + 1LL;
                ans2 += -val + 1LL;
            }
        }
        else {
            if (val >= 0LL) {
                diff -= val + 1LL;
                ans2 += val + 1LL;
            }
        }
    }

    cout << min(ans1, ans2) << endl;
}

