  ios::sync_with_stdio(false);

  int N;
  cin >> N;
  vector< int > a(N);
  REP(i, N) cin >> a[i];

  bool flag;
  if (a[0] >= 0) flag = true;
  else flag = false;
  int opSum, epSum, nSum, opCnt, epCnt, nCnt;
  opSum = epSum = opCnt = epCnt = 0;
  REP(i, N) {
    opSum += a[i];
    epSum += a[i];
    nSum += a[i];
    if (i % 2 == 0) {
      // opSum < 0 
      if (opSum >= 0) {
	opCnt += abs(opSum) + 1;
	opSum = -1;
      }
      // epSum > 0
      if (epSum <= 0) {
	epCnt += abs(epSum) + 1;
	epSum = 1;
      }
      if (flag) {
	if (nSum <= 0) {
	  nCnt += abs(nSum) + 1;
	  nSum = 1;
	}
      } else {
	if (nSum >= 0) {
	  nCnt += abs(nSum) + 1;
	  nSum = -1;
	}
      }
    } else {
      // opSum > 0 
      if (opSum <= 0) {
	opCnt += abs(opSum) + 1;
	opSum = 1;
      }
      // epSum < 0
      if (epSum >= 0) {
	epCnt += abs(epSum) + 1;
	epSum = -1;
      }
      if (flag) {
	if (nSum >= 0) {
	  nCnt += abs(nSum) + 1;
	  nSum = -1;
	}
      } else {
	if (nSum <= 0) {
	  nCnt += abs(nSum) + 1;
	  nSum = 1;
	}
      }

    }
    //  debug(opSum);
    // debug(opCnt);
    // debug(epSum);
    // debug(epCnt);
  }

  int ans = min(min(opCnt, epCnt), nCnt);

  cout << ans << endl;

  return 0;
}

