	sum[0]=0;
	long long ans1=0,ans2=0;
	for (long long i=1;i<=n;i++) {
		cin>>a[i];
		sum[i]=sum[i-1]+a[i];
		if (i!=1) {
			if (sum[i]*sum[i-1]>=0){
				if (sum[i]>=0) {
					ans1+=sum[i]+1;
					sum[i]=-1;
				}
				else {
					ans1+=1-sum[i];
					sum[i]=1;
				}
			}
		}
