			if (sum1[i]*sum1[i-1]>=0){
				if (sum1[i]>=0){
					ans2+=sum1[i]+1;
					sum1[i]=-1;
				}
				else {
					ans2+=1-sum1[i];
					sum1[i]=1;
				}
			}
		}
		else {
			if (sum[i]>0) sum1[i]=-1;
			else sum1[i]=1;
		}
	}
	cout<<min(ans1,ans2)<<endl;
//	cout<<ans1;
	return 0;
}

