#define MOD (1000000007LL)
#define LEFT(n) (2*(n))
#define RIGHT(n) (2*(n)+1)

using namespace std;
typedef long long ll;
typedef pair<int, int> ii;
typedef pair<int, ii> iii;

ll pwr(ll base, ll p, ll mod = MOD){
ll ans = 1;while(p){if(p&1)ans=(ans*base)%mod;base=(base*base)%mod;p/=2;}return ans;
}


ll gcd(ll a, ll b){
    if(b == 0)  return a;
    return gcd(b, a%b);
}


int n;
ll arr[100005];


int main(){

    ios_base::sync_with_stdio(0);
    cin.tie(0);

    cin>>n;
    for(int i=1;i<=n;i++)
        cin>>arr[i];

    ll ans1 = 0, sum = 0;
    for(int i=1,need=1;i<=n;i++,need*=-1){
        sum += arr[i];
        if(need == 1){
            if(sum > 0) continue;
            ans1 += 1 - sum;
            sum = 1;
        }
        else{
            if(sum < 0) continue;
            ans1 += sum - (-1);
            sum = -1;
        }
    }

    ll ans2 = 0; sum = 0;
    for(int i=1,need=-1;i<=n;i++,need*=-1){
        sum += arr[i];
        if(need == 1){
            if(sum > 0) continue;
            ans2 += 1 - sum;
            sum = 1;
        }
        else{
            if(sum < 0) continue;
            ans2 += sum - (-1);
            sum = -1;
        }
    }

    cout<<min(ans1, ans2);
