int N;
ll A[100100], B[100100];

ll f(){
    ll t1 = 0, t2 = 0;

    for(int i=1;i<N;++i){
        B[i] += t1 - t2;

        if(B[i-1] > 0 && B[i] >= 0){
            t2 += B[i] + 1;
            B[i] = -1;
        }else if(B[i-1] < 0 && B[i] <= 0){
            t1 += -B[i] + 1;
            B[i] = 1;
        }
    }

    return t1 + t2;
}

