        copy(A, A+N, B);
        for(int i=0;i<N;++i){
            B[i] += 1;
        }
        res = f() + 1;

        copy(A, A+N, B);
        for(int i=0;i<N;++i){
            B[i] -= 1;
        }
        res = min(res, f() + 1);
    }else{
        copy(A, A+N, B);
        res = f();
    }

    std::cout << res << std::endl;
}

