int solve(vector<int> &v)
{
    if (v[0] == 0)
        return INF;
    const int n = v.size();
    int cnt = 0;
    vector<int> cv(n + 1);
    cv[1] = v[0];
    for (int i = 1; i < n; i++)
    {
        cv[i + 1] = v[i] + cv[i];
        if (cv[i + 1] != 0 && (cv[i + 1] * cv[i]) < 0)
        {
            ;
        }
        else
        {
            const int new_aa = -1 * sign(cv[i]);
            // now_sign = cv[i+1]+change
            const int shift = new_aa - cv[i + 1];
            v[i] += shift;
            cv[i + 1] = v[i] + cv[i];
            cnt += abs(shift);
        }
    }
    return cnt;
}

