		private class Calc {
			public void Solve() {
				int N = ReadInt();
				var a = ReadInt(' ');
				int cnt = 0;
				int sum = a[0];
				foreach (var item in a.Select((x,i)=>new { X = x, I = i }).Where(x=>x.I>=1).Select(x=>x.X)) {
					var asum = sum + item;
					if (asum * sum < 0) { sum += item;continue; }

					cnt += Abs(asum) + 1;
					sum = -1;
				}
				cnt.WL();
				return;
			}
		}
    }



