const llong inf = llong(1e18)+7;
const llong mod = 1e9+7;

int main(){
	int n;
	vector<vector<llong> > a;

	cin >> n;
	a.resize(n, vector<llong>(2));
	for(int i = 0; i < n; i++){
		cin >> a[i][0];
		a[i][1] = a[i][0];
	}

	int w[2] = {0,1};
	llong ans = inf;
	for(int i = 0; i < 2; i++){
		llong sum = 0;
		llong res = 0;
		for(int j = 0; j < n; j++){
			llong next = sum + a[j][i];
			if(w[i]^(j&1)){
				// 正にしたい
				if(next <= 0){
					a[j][i]++;
					res += -next + 1;
					a[j][i] += -next;
				}
			}else{
				if(next >= 0){
					a[j][i]--;
					res += next + 1;
					a[j][i] += -next;
				}
				// 負にしたい
			}

			sum += a[j][i];
		}

		ans = min(ans, res);
	}

	cout << ans << endl;

	return 0;
}

