typedef long long LL;

const int MaxN = 100000;
int n, a[MaxN + 5];
LL sum[MaxN + 5];

int main()
{
	while (~scanf("%d", &n)) {
		for (int i = 1; i <= n; i++) {
			scanf("%d", &a[i]);
			sum[i] = sum[i - 1] + a[i];
		}
		LL ans1 = 0, t = 0, cnt = 0;
		for (int i = 1; i <= n; i++) {
			LL now = sum[i] + cnt;
			if (t == 0 && now < 0) {t = 1 - t; continue;}
			if (t == 1 && now > 0) {t = 1 - t; continue;}
			if (t == 0 && now >= 0) {
				cnt -= now + 1;
				ans1 += now + 1;
			}
			if (t == 1 && now <= 0) {
				cnt += 1 - now;
				ans1 += 1 - now;
			}
			t = 1 - t;
		}
		LL ans2 = 0; t = 1; cnt = 0;
		for (int i = 1; i <= n; i++) {
			LL now = sum[i] + cnt;
			if (t == 0 && now < 0) {t = 1 - t; continue;}
			if (t == 1 && now > 0) {t = 1 - t; continue;}
			if (t == 0 && now >= 0) {
				cnt -= now + 1;
				ans2 += now + 1;
			}
			if (t == 1 && now <= 0) {
				cnt += 1 - now;
				ans2 += 1 - now;
			}
			t = 1 - t;
		}
		printf("%lld\n", min(ans1, ans2));
	}	
	return 0;
}

