    ll prev=acc;
    for (int i=1; i<n; i++) {
      acc += a[i];
      ll need = prev>0 ? -1 : +1;
      if (acc == 0) {
	ans++;
	acc = need;
      } else {
	if (need * acc < 0) {
	  ans += abs(acc-need);
	  acc = need;
	}
      }
      prev = acc;
    }

    best = min(best, ans);
  }


  cout<<best<<endl;
  return 0;
}
