		dp[1][0] = a[0] + 1;
		sum[0][0] = a[0];
		sum[1][0] = -1;
	}
	else if (a[0] == 0) {
		dp[0][0] = dp[1][0] = 1;
		sum[0][0] = 1;
		sum[1][0] = -1;
	}
	else {
		dp[0][0] = abs(a[0]) + 1;
