			dp[1][i] = dp[0][i - 1] + s + 1;
			sum[1][i] = -1;
		}
		else {
			dp[1][i] = dp[0][i - 1];
			sum[1][i] = s;
		}
		s = sum[1][i - 1] + a[i];
		if (s <= 0) {
			dp[0][i] = dp[1][i - 1] + abs(s) + 1;
			sum[0][i] = 1;
		}
		else {
			dp[0][i] = dp[1][i - 1];
			sum[0][i] = s;
		}
	}
