using namespace std;

#define REP(i, N) for (int (i) = 0; (i) < (N); ++(i))
#define READALL(c) for (auto &e : c) { cin >> e; }
#define PRINTALL(c) for (const auto &e : c) { cout << e << "\t"; } cout << "\n";

template <typename T>
using V = vector<T>;

typedef long double ld;


int N;

int64_t solve(V<int64_t> A) {
	int64_t sum = A[0], ans = 0;
	for (int i = 1; i < N; ++i) {
		int64_t next = sum + A[i];
		// cout << next << endl;
		if (next == 0) {
			++ans;
			if (sum < 0)
				next = 1;
			else
				next = -1;
		} else if (sum < 0) {
			if (next < 0) {
				ans += abs(next)+1;
				next = 1;
			}
		} else {
			if (next > 0) {
				ans += next+1;
				next = -1;
			}
		}
		sum = next;
	}
	return ans;
}


int main() {
	ios::sync_with_stdio(0);
	cin.tie(0);

	cin >> N;

	V<int64_t> A(N);
	READALL(A);

	int64_t ans, tmp = A[0];
	if (A[0] <= 0)
		A[0] = 1;
	ans = abs(A[0]-tmp)+solve(A);
	if (A[0] >= 0)
		A[0] = -1;
	ans = min(ans, abs(A[0]-tmp)+solve(A));

	cout << ans << endl;

}

