inline int getint()
{
       int w=0,q=0; char c=getchar();
       while((c<'0' || c>'9') && c!='-') c=getchar(); if(c=='-') q=1,c=getchar(); 
       while (c>='0' && c<='9') w=w*10+c-'0', c=getchar(); return q ? -w : w;
}

void work(llg sum)
{
	qz[1]=a[1];
	for (llg i=2;i<=n;i++)
	{
		qz[i]=qz[i-1]+a[i];
		if (qz[i-1]>0 && qz[i]>=0)
		{
			sum+=abs(-1-qz[i]); qz[i]=-1;
		}
		if (qz[i-1]<0 && qz[i]<=0)
		{
			sum+=abs(1-qz[i]); qz[i]=1;
		}
	}
	ans=min(ans,sum);
}

int main()
{
//	yyj("A");
	cin>>n;
	for (llg i=1;i<=n;i++) a[i]=getint();
	if (a[1]==0)
	{
		a[1]=1;
		work(1);
		a[1]=-1;
		work(1);
	}
	else
	{
		work(0);
		if (a[1]>0) 
		{
			llg v=a[1];
			a[1]=-1;
			work(v+1);
		}
		else
		{
			llg v=a[1];
			a[1]=1;
			work(1-v);
		}
	}
	cout<<ans;
	return 0;
}

