    auxV[i] = v[i];
  }

  if (v[1] < 0) {
    cost1 = CalcCost(v);
    ResetV();
    if (v[1] <= 0) {
      cost0 = 1 - v[1];
      v[1] = 1;
    }

    cost0 += CalcCost(v);
  }
  else if (v[1] > 0) {
    cost0 = CalcCost(v);
    ResetV();
    if (v[1] >= 0) {
      cost1 = v[1] + 1;
      v[1] = -1;
    }
    cost1 += CalcCost(v);
  }
  else {
    v[1] = 1;
    cost0 = 1 + CalcCost(v);
    ResetV();
    v[1] = -1;
    cost1 = 1 + CalcCost(v);
  }

  cout << min(cost0, cost1) << '\n';
  return 0;
}

