ll f(vll a, ll s) {
    ll t = 0;
    rep(i, sz(a) - 1) {
        t += a[i];
        if (t < 0) {
            if (t + a[i + 1] <= 0) {
                s += (1 - t) - a[i + 1];
                a[i + 1] = 1 - t;
            }
        } else {
            if (t + a[i + 1] >= 0) {
                s += a[i + 1] - (-t - 1);
                a[i + 1] = -t - 1;
            }
        }
    }
    return s;
}

