    rep1(i,N){
        Int S_now = S[i] + changes1;

        if(i%2 == 1 && S_now <= 0){
            changes1 += -S_now + 1;
            ans1 += -S_now + 1;
        } else if(i%2 == 0 && S_now >= 0){
            changes1 -= S_now + 1;
            ans1 += S_now + 1;
        }
    }

    //-+-+
    Int ans2 = 0, changes2 = 0;
    rep1(i,N){
        Int S_now = S[i] + changes2;

        if(i%2 == 0 && S_now <= 0){
            changes2 += -S_now + 1;
            ans2 += -S_now + 1;
        } else if(i%2 == 1 && S_now >= 0){
            changes2 -= S_now + 1;
            ans2 += S_now + 1;
        }
    }

    cout << min(ans1,ans2) << endl;
}

