int N;

int64_t solve(V<int64_t> A) {
	int64_t sum = A[0], ans = 0;
	for (int i = 1; i < N; ++i) {
		int64_t next = sum + A[i];
		// cout << next << endl;
		if (next == 0) {
			++ans;
			if (sum < 0)
				next = 1;
			else
				next = -1;
		} else if (sum < 0) {
			if (next < 0) {
				ans += abs(next)+1;
				next = 1;
			}
		} else {
			if (next > 0) {
				ans += next+1;
				next = -1;
			}
		}
		sum = next;
	}
	return ans;
}


