int solve(vector<ll> v, int n, bool upper) {
	ll result = 0;
	ll goukei = v[0];
	For(i, 1, n) {
		goukei += v[i];
		if (upper) {
			if (goukei <= 0) {
				result += (1 - goukei);
				goukei = 1;
			}
			upper = false;
		}
		else {
			if (goukei >= 0) {
				result += (1 + goukei);
				goukei = -1;
			}
			upper = true;
		}
	}
	return result;
}

