long long add(long long &sum, bool plus) {
    if (plus) {
        if (sum >= 1) return 0;
        else {
            long long res = abs(sum - 1);
            sum = 1;
            return res;
        }
    }
    else {
        if (sum <= -1) return 0;
        else {
            long long res = abs(sum + 1);
            sum = -1;
            return res;
        }
    }
}

int main() {
    while (cin >> n) {
        cin >> a[0];
        long long psum = a[0], msum = a[0];
        long long plus = add(psum, true), minus = add(msum, false);
        for (int i = 1; i < n; ++i) {
            cin >> a[i];
            psum += a[i];
            msum += a[i];
            if (i & 1) {
                plus += add(psum, false);
                minus += add(msum, true);
            }
            else {
                plus += add(psum, true);
                minus += add(msum, false);
            }
        }
        cout << min(plus, minus) << endl;
    }
}

