int N, A[MAX_N], S[MAX_N];

ll calc(int sum, int ans) {
  for (int i = 1; i < N; i++) {
    ll s = sum;
    sum += A[i];
    if (s * sum < 0) continue;
    ans += abs(sum) + 1;
    sum = (s < 0)? 1: -1;
  }
  return ans;
}

void solve() {
  ll ans;
  if (A[0] == 0) {
    ans = min(calc(1, 1), calc(-1, 1));
  } else if (A[0] > 0) {
    ans = min(calc(A[0], 0), calc(-1, abs(A[0]) + 1));
  } else {
    ans = min(calc(A[0], 0), calc(1,  abs(A[0]) + 1));
  }
  printf("%lld\n", ans);
}

int main() {
  cin >> N;
  for (int i = 0; i < N; i++) cin >> A[i];

  solve();

  return 0;
}

