void Solve1(){
    lint res=0,now=0;
    for(int i=1;i<=n;i++) b[i]=a[i];
    for(int i=1;i<=n;i++){
        if((i&1) && b[i]+now<=0){
            b[i]+=now,res+=(1-b[i]),now+=(1-b[i]);
        }
        if(!(i&1) && b[i]+now>=0){
            b[i]+=now,res+=(b[i]+1),now-=(b[i]+1);
        }
    }
    ans=min(ans,res);
