long long solve(long long sum, int poz, int n, int sgn)
{
    long long rez=0;
    sum+=A[poz];

    if(sum*sgn<=0)
    {
        rez=abs(sum-sgn);
        sum=sgn;
    }

    if(poz!=n)
        rez=rez+solve(sum,poz+1,n,-sgn);

    return rez;
}

