  ll sum;

  // 先頭が正
  std::vector< ll > vx (n, 0);
  sign = 1;

  vx[0]     = va[0] >= sign ? va[0] : 1;
  ll count1 = vx[0] >= sign ? 0     : 1 - vx[0];
  sum       = vx[0];

  for (ll i = 1; i < n; i++) {
    ll pre_sum = sum;
    sign *= -1;
    sum += va[i];
    vx[i] = va[i];

    ll pre_sum_sign = pre_sum > 0 ? 1 : -1;
    while (pre_sum_sign * sum >= 0 || sum == 0) {
      vx[i] += sign;
      count1++;
      sum += sign;

      //for (ll j = 0; j <= i; j++) {
      //	std::cout << vx[j] << " ";
      //}
      //std::cout << "SUM: " << sum << " CNT: " << count1 << std::endl;
    }
  }

  // 先頭が負
  sign = -1;

  vx[0]     = va[0] <= sign ? va[0] : -1;
  ll count2 = vx[0] <= sign ? 0     : vx[0] + 1;
  sum       = vx[0];

  for (ll i = 1; i < n; i++) {
    ll pre_sum = sum;
    sign *= -1;
    sum += va[i];
    vx[i] = va[i];

    ll pre_sum_sign = pre_sum > 0 ? 1 : -1;
    while (pre_sum_sign * sum >= 0 || sum == 0) {
      vx[i] += sign;
      count2++;
      sum += sign;

      //for (ll j = 0; j <= i; j++) {
      //	std::cout << vx[j] << " ";
      //}
      //std::cout << "SUM: " << sum << " CNT: " << count2 << std::endl;
    }
  }

  std::cout << std::min(count1, count2) << std::endl;

  return 0;
}

