const ll MOD = 1000000007;

ll solve(vector<ll>& a, int n){
	ll ans = 0, s = a[0];
	for(int i=1;i<n;i++){
		ll s_next = s + a[i];
		if(s < 0){
			// cout << s_next << " " << a[i] << endl;
			ll diff = 0;
			if(s_next <= 0){
				diff = -s_next + 1;
			}
			s_next += diff;
			ans += diff;
			// cout << s_next << " " << diff << endl;
			assert(s_next > 0);
		}else{
			// cout << s_next << " " << a[i] << endl;
			ll diff = 0;
			if(s_next >= 0){
				diff = s_next + 1;
			}
			s_next -= diff;
			ans += diff;
			// cout << s_next << " " << diff << endl;
			assert(s_next < 0);
		}
		s = s_next;
		// cout << ans << endl;
	}
	return ans;
}

int main(){
	int n;
	cin >> n;

	vector<ll> a(n+1);
	for(int i=1;i<=n;i++){
		cin >> a[i];
	}

	ll ans;
	a[0] = -1;
	ll ans = solve(a, n+1);
	a[0] = 1;
	ans = min(ans, solve(a, n+1));

	cout << ans << endl;

    return 0;
}

