			ans += abs(-1 - sum - a[i]);
			sum = -1;
		} else if(sum < 0 && sum + a[i] <= 0){
			ans += abs(1 - sum - a[i]);
			sum = 1;
		} else {
			sum += a[i];
		}
	}
	return ans;
}

