#define rep(i,N) for(LL i=0;i<N;++i)
typedef long long int LL;

LL n, a[112345];
LL sum, ans;

int main()
{
	in >> n;
	rep(i, n) { in >> a[i]; }

	rep(i, n)
	{
		sum += a[i];
		if (i == n - 1) { break; }
		if (sum < 0 && sum + a[i + 1] <= 0)
		{
			auto want = abs(sum) + 1;
			if (a[i + 1] * want < 0)
			{
				ans += abs(want + a[i + 1]);
				a[i + 1] += abs(want + a[i + 1]);
			}
			else
			{
				ans += abs(want - a[i + 1]);
				a[i + 1] += abs(want - a[i + 1]);
			}

		}
		else if (sum > 0 && sum + a[i + 1] >= 0)
		{
			auto want = sum + 1;
			if (a[i + 1] * want > 0)
			{
				ans += a[i + 1] + want;
				a[i + 1] = -want;
			}
			else
			{
				ans += abs(a[i + 1] - want);
				a[i + 1] -= abs(a[i + 1] - want);
			}
		}
	}

	out << ans << std::endl;
	return 0;
}

