typedef long long LL;

int n;
LL a[100004];

LL solve(){
	LL sum = a[0];	
	LL res = 0;
	FOR(i,1,n){	
		if(sum < 0){
			if( sum + a[i] > 0){			
				sum += a[i];
				continue;		
			}		
			res+= 1 - (sum + a[i]);
			sum = 1;
		}else{
			if( sum + a[i] < 0) {			
				sum += a[i];
				continue;		
			}
			res+= (sum + a[i]) + 1;
			sum = -1;
		}
	}
	return res;
}

