using lint = long long int;

int N;
vector<lint> a;

lint solve()
{
    lint sum = 0;
    lint ans = 0;
    for (int i = 0; i < N; i++)
    {
        sum += a[i];
        if (i%2 == 1)
        {
            if (sum <= 0)
            {
                ans += -sum + 1;
                sum = 1;
            }
        }
        else
        {
            if (sum >= 0)
            {
                ans += sum + 1;
                sum = -1;
            }
        }
    }
    return ans;
}
int main()
{
    cin >> N;
    a.resize(N);
    for (auto &v : a) cin >> v;
    lint res = solve();
    for (auto &v : a) v = -v;
    cout << min(res, solve()) << endl;
}

