#include<iostream>
using namespace std;
typedef long long LL;
const int N = 1e5;
LL a[N];
int sgn(LL x)
{
    if(x==0) return 0;
    if(x<0) return -1;
    else return 1;
}
LL solve(int n, LL a0)
{
    LL ans = 0;
    LL sum = a0;
    int prev = sgn(a0);
    for(int i = 1; i < n; i++)
    {
        sum += a[i];
        if(sgn(sum) != -1*sgn(prev))
        {
            LL delta = sum==0 ? -1*sgn(prev) : -1*(sum+sgn(sum));
            sum += delta;
            ans += abs(delta);
            //cout<<" "<<delta<<endl;
        }
        //cout<<sum<<endl;
        prev = sgn(sum);
    }
    return ans;
}
int main()
{
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n; cin >> n;
    for(int i = 0; i < n; i++)
        cin >> a[i];

    LL ans;
    if(a[0] > 0)
        ans = solve(n,a[0]);
    else
        ans = solve(n,1)+(1-a[0]);

    if(a[0] < 0)
        ans = min(ans,solve(n,a[0]));
    else
        ans = min(ans,solve(n,-1)+(a[0]+1));

    cout<<ans<<endl;

    cout<<flush;
    return 0;
}

