                tree.add(i, -1 * tree.sum(i) + 1);
            }
        }
        else {
            if (tree.sum(i) >= 0) {
                count1 += tree.sum(i) + 1; 
                tree.add(i, -1 * tree.sum(i) - 1);
            }
        }
    }
