int solve(vector<int> a,int sign){
    vector<int> sum(a.size()+1);
	ll cnt=0;
	for (int i = 0; i < a.size(); i++) {
		if(sign==-1){
			if(sum[i]+a[i]<0)sum[i+1]=sum[i]+a[i];
			else {
				cnt+=abs(-1-sum[i]-a[i]);
				sum[i+1]=-1;
			}
			sign=1;
		}
		else {
			if(sum[i]+a[i]>0)sum[i+1]=sum[i]+a[i];
			else {
				cnt+=abs(1-sum[i]-a[i]);
				sum[i+1]=1;
			}
			sign=-1;
		}
	}
	return cnt;
}

