    if(a==0){
        sum[0]=1;
        sum[1]=-1;
        cnt[0]=1;
        cnt[1]=1;
    }else{
        sum[0]=a;
        sum[1]=nextval(a);
        cnt[0]=0;
        cnt[1]=std::abs(a-nextval(a));
    }
    for(int i=1;i<n;i++){
        scanf("%lld",&a);
        for(int j=0;j<2;j++){
            if(sum[j]+a==0){
                cnt[j]++;
                sum[j]=nextval(sum[j]);
            }else if(issamesign(sum[j],sum[j]+a)){
                cnt[j]+=std::abs(sum[j]+a-nextval(sum[j]+a));
                sum[j]=nextval(sum[j]+a);
            }else{
                sum[j]+=a;
            }
        }
    }
    printf("%lld",std::min(cnt[0],cnt[1]));
    return 0;
}

