using namespace std;

long long solver(vector<int> A, int flip)
{
	long long ans = 0;
	int sum = 0;
	switch (flip)
	{
	case 0:
		if (A[0] <= 0)
		{
			ans += abs(A[0]) + 1;
			sum = 1;
		}
		else
			sum = A[0];
		break;

	case 1:
		if (A[0] >= 0)
		{
			ans += abs(A[0]) + 1;
			sum = -1;
		}
		else
			sum = A[0];
		break;
	}
	flip = 1 - flip;

	for (int i = 1; i < A.size(); i++)
	{
		sum += A[i];

		switch (flip)
		{
		case 0:
			if (sum <= 0)
			{
				ans += abs(sum) + 1;
				sum = 1;
			}
			break;

		case 1:
			if (sum >= 0)
			{
				ans += sum + 1;
				sum = -1;
			}
			break;
		}

		flip = 1 - flip;
	}

	return ans;
}

int main()
{
	int N;
	cin >> N;

	vector<int>  A(N);

	for (int i = 0; i < N; i++)
		cin >> A[i];

	cout << min(solver(A, 1), solver(A, 0)) << endl;

	return 0;
}

