void addStep(long long int *ans,
             long long int *sum,
             long long int *preb)
{
    //cout << *ans << " " << *sum <<  " " << *preb << endl;
    if(*sum >= 0 && *preb > 0)
    {
        *ans += abs(*sum) + 1;
        *sum = -1;
    }
    else if(*sum <= 0 && *preb < 0)
    {
        *ans += abs(*sum) + 1;
        *sum = 1;
    }
    *preb = *sum;
}

