    long long int sum = 0;
    long long int preb = 0;
    bool spe = false;
    cin >> n;
    for(int i = 0; i < n; ++i)
    {
        cin >> t;
        sum += t;
        if(i == 0 && sum == 0)
        {
            spe = true;
            ans += 1;
            continue;
        }
        else if(spe && sum == 0)
        {
            ans += 2;
            continue;
        }
        else if(spe)
        {
            spe = false;
            if(t > 0)
            {
                sum -= 1;
                preb = -1;
            }
            else
            {
                sum += 1;
                preb = 1;
            }
        }

        addStep(&ans, &sum, &preb);

    }
    cout << ans << endl;
}

