		dp[0][0] = 0;
		dp[1][0] = a[0] + 1;
		sum[0][0] = a[0];
		sum[1][0] = -1;
	}
	else if (a[0] == 0) {
		dp[0][0] = dp[1][0] = 1;
		sum[0][0] = 1;
		sum[1][0] = -1;
	}
	else {
		dp[0][0] = -a[0] + 1;
		dp[0][0] = 0;
		sum[0][0] = 1;
		sum[1][0] = a[0];
	}
	for (int i = 1; i < n; ++i) {
		int s = sum[0][i - 1] + a[i];
		if (s >= 0) {
			dp[1][i] = dp[0][i - 1] + s + 1;
			sum[1][i] = -1;
		}
		else {
			dp[1][i] = dp[0][i - 1];
			sum[1][i] = s;
		}
		s = sum[1][i - 1] + a[i];
		if (s <= 0) {
			dp[0][i] = dp[1][i - 1] - s + 1;
			sum[0][i] = 1;
		}
		else {
			dp[0][i] = dp[1][i - 1];
			sum[0][i] = s;
		}
	}
	cout << min(dp[0][n - 1], dp[1][n - 1]) << endl;
	return 0;
}

