uint64_t count(int initial_sig) {

  int sig = initial_sig;
  int64_t sum = 0;
  uint64_t ret = 0;

  for (const auto a : As) {
    sum += a;

    if (0 < sig && sum <= 0) {
      ret += -1 * sum + 1;
      sum = 1;
    } else if (sig < 0 && 0 <= sum) {
      ret += sum + 1;
      sum = -1;
    }

    sig = -1 * sig;
  }

  return ret;
}

