long long dfs(int now, long long sum) {
	if (now == n) {
		return 0;
	}
	if (now == 0) {
		return min(dfs(now + 1, min(-1LL, a[now])) + abs(min(-1LL, a[now]) - a[now]),
			dfs(now + 1, max(1LL, a[now])) + abs(max(1LL, a[now]) - a[now]));
	}
	if (sum < 0) {
		if (sum + a[now] > 0) {
			return dfs(now + 1, sum + a[now]);
		}
		return dfs(now + 1, 1) + abs(1 - sum - a[now]);
	}
	if (sum + a[now] < 0) {
		return dfs(now + 1, sum + a[now]);
	}
	return dfs(now + 1, -1) + abs(-1 - sum - a[now]);
}

