long long int solve(bool even){
    long long int sum = 0, ans = 0;
    for(int i=0;i<n;++i){
        if(i == 0){
            long long int diff;
            if(even){
                diff = (a[i] > 0 ? 0 : 1 - a[i]);
            }else{
                diff = (a[i] < 0 ? 0 : -1 - a[i]);
            }
            sum += a[i] + diff;
            ans += abs(diff);
            continue;
        }else if(i > 0){
            long long int tmp = sum + a[i];
            if(tmp * sum < 0)sum = tmp;
            else{
                long long int diff = (-sum - (sum > 0 ? 1 : -1)) - a[i];
                sum = tmp + diff;
                ans += abs(diff);
            }
        }else sum += a[i];
    }

    return ans;
}

