void deal(int m, vector<long> s) {
	long res=0;
	long inc;
	for(int i=0; i<s.size(); i++) {
		if( m*s[i] > 0) {
			m*=-1;
			continue;
		}
		else {
			inc=m-s[i];
			for (int j=i+1; j<s.size(); j++)
				s[j]+=inc;
			res+=abs(inc);
		}
		m*=-1;
	}
	cout << res;
}

int main() {
	int n;
