                a[i] = t;
            }
        }
        else
        {
            if (pref + a[i] >= 0)
            {
                ll t = -pref - 1;
                sol += abs(t - a[i]);
                a[i] = t;
            }
        }
        pref += a[i];
    }
    return sol;
}

