ll solve(const vector<ll> &a) {
    ll s = a[0];
    ll ans = 0;
    for (int i = 1; i < a.size(); ++i) {
        ll pr = s;
        s += a[i];
        if (pr > 0 && s >= 0) {
            ans += abs(-1 - s);
            s = -1;
        }
        if (pr < 0 && s <= 0) {
            ans += abs(1 - s);
            s = 1;
        }
    }
    return ans;
}

void solve() {
    int n = nxt();
    vector<ll> a(n);
    forn(i, n) {
        a[i] = nxt();
    }
    ll ans = LLONG_MAX;
    if (a[0] == 0) {
        a[0] = 1;
        ans = min(ans, 1 + solve(a));
        a[0] = -1;
        ans = min(ans, 1 + solve(a));
        a[0] = 0;
    } else {
        ans = min(ans, solve(a));
    }
    if (a[0] >= 0) {
        ll add = abs(-1 - a[0]);
        a[0] = -1;
        ans = min(ans, add + solve(a));
        a[0] += add;
    }
    if (a[0] <= 0) {
        ll add = abs(1 - a[0]);
        a[0] = 1;
        ans = min(ans, add + solve(a));
        a[0] -= add;
    }
    cout << ans << "\n";
}

