int n;
ll s[100010], ss[100010], b, ans, cur;

ll f(){
	ll ans = 0;
	for(int i = 2; i <= n; i++){
		if(b + s[i] == 0){
			if(s[i - 1] < 0) b++;
			else b--;
			ans++;
		}
		else if(b + s[i] > 0 && s[i - 1] > 0){
			ans += abs(s[i] + b + 1);
			b -= s[i] + b + 1;
		}
		else if(b + s[i] < 0 && s[i - 1] < 0){
			ans += abs(s[i] + b - 1);
			b -= s[i] + b - 1;
		}
		s[i] += b;
	}
	return ans;
}

int main(){
	scanf("%d", &n);
	for(int i = 1; i <= n; i++){ scanf("%lld", s + i); s[i] += s[i - 1]; ss[i] = s[i]; }
