	ans = f() + cur;
	cur = 0; b = 0;
	for(int i = 1; i <= n; i++) s[i] = ss[i];
	if(s[1] >= 0){ cur = s[1] + 1; b = -s[1] - 1; s[1] = -1; }
	ans = min(ans, f() + cur);
	printf("%lld\n", ans);
}

