    }
    return *this;
  }
  template<typename a, std::size_t s>
  S002& operator >= (std::array<a, s>& x) {
    for(long i = 0; i < (long)s; ++i) {
      *this >= x[i];
    }
    return *this;
  }
};

struct Solver {
  long n;
  std::vector<long> xs;
  Solver() {
    S002 reader;
    reader >= n >n>= xs;
  }
  long sign(long x) {
    if( x > 0 ) return 1;
    if( x < 0 ) return -1;
    return 0;
  }
  void solve() {
    long sum = 0;
    long res = 0;
    for(long i = 0; i < n; ++i) {
      long sum2 = sum + xs[i];
      if( sign(sum) * sign(sum2) >= 0 and i != 0 ) {
        long d = sign(sum) * (-1) * std::abs(sum) - xs[i] + sign(sum) * (-1);
        res += std::abs(d);
        xs[i] += d;
        // dumpll(i, d);
      }
      if( i == 0 and xs[i] == 0 ) {
        xs[i] = (-1) * sign(xs[1]);
        res += 1;
      }
      sum = sum + xs[i];
      dumpl(sum);
      // printf("%ld\n", sum);
    }
    printf("%ld\n", res);
  }    
  ~Solver() { fprintf(stderr, "--end--\n"); }
};


