ll solve(const vector<int> &a, int start){
  const int n = a.size();
  ll sum = start;

  ll ret = std::abs(start - a[0]);
  for(int i = 1; i < n; i++){
    ll next;
    if(sum > 0){
      next = - sum - 1;
      if(a[i] < next) next = a[i];
    }else{
      next = - sum + 1;
      if(a[i] > next) next = a[i];
    }
    sum += next;
    ret += std::abs(next - a[i]);
  }

  return ret;
}

