ll solve(vector<ll> v, int n, bool upper) {
	ll result = 0;
	ll goukei = v[0];
	For(i, 1, n) {
		goukei += v[i];
		if (upper) {
			if (goukei <= 0) {
				result += (1 - goukei);
				goukei = 1;
			}
			upper = false;
		}
		else {
			if (goukei >= 0) {
				result += (1 + goukei);
				goukei = -1;
			}
			upper = true;
		}
	}
	return result;
}

int main() {
	int n;
	cin >> n;
	vector<ll> v(n);
	rep(i, n)
		cin >> v[i];

	ll result = 0;
	ll goukei = v[0];
	if (v[0] != 0) {
		result = min(solve(v,n,true),solve(v,n,false));
	}
	else {
		ll tmp = v[0];
		v[0] = (1-v[1]);
		ll result1 = abs(tmp - v[0]) + min(solve(v,n,true),solve(v,n,false));
		v[0] = (-1-v[1]);
		ll result2 = abs(tmp-v[0]) + min(solve(v,n,true),solve(v,n,false));
		result = min(result1, result2);
	}
	cout << result << endl;

}

