  }

  sum = 0;
  ll ans2 = 0;
  for(int i = 0; i < N; i++) {
    sum += a[i];
    if( i % 2 != 0 ) { // 正
      if( sum < 0 ) {
        ans2 += abs(sum) + 1;
        sum = 1;
      } else if (sum == 0) {
        sum++;
        ans2++;
      }
    } else { //負
      if( sum > 0 ) {
        ans2 += abs(sum) + 1;
        sum = -1;
      } else if (sum == 0) {
        sum--;
        ans2--;
      }
    }
  }


  cout << min(ans1, ans2) << "\n";

  return 0;
}

