	int n,L;
	scanf("%d%d",&n,&L);

	pair<ll,ll> offset = make_pair(0,0);
	for (int i=1;i<=n;i++)
	{
		ll t,v;
		scanf("%lld%lld",&t,&v);
		if (i==1)
		{
			que.push_back(make_pair(0,0));
			que.push_back(make_pair((double)v,(double)v*(double)t));
			printf("%.8f\n",(double)t);
			continue;
		}

		double slope;
		while (!que.empty() && que[que.size()-1].first + offset.first > (double)(L-v))
		{
			slope = (double)(que[que.size()-1].second - que[que.size()-2].second) / (double)(que[que.size()-1].first - que[que.size()-2].first);
			que.pop_back();
		}
		pair<double,double>  tmp;
		if (que[que.size()-1].first + offset.first != (double)(L-v))
		{
			tmp = make_pair((double)(L-v) - offset.first, ((double)(L-v) - (que[que.size()-1].first+offset.first)) * slope + que[que.size()-1].second);
			que.push_back(tmp);
		}
		else tmp = que[que.size()-1];
		offset.first += (double)v;
		offset.second += (double)(v*t);
		printf("%.8f\n", (tmp.second + offset.second) / (tmp.first + offset.first));

		int lb = 0, ub = que.size()-1, mid;
		while (ub > lb)
		{
			mid = (lb + ub)/2;
			if ((que[mid+1].second + offset.second) / (que[mid+1].first + offset.first) >= (que[mid].second + offset.second) / (que[mid].first + offset.first)) lb = mid+1;
			else ub = mid;
		}
		for (int i=0;i<lb;i++) que.pop_front();
		que.push_front(make_pair(-offset.first,-offset.second));
	}
	return 0;
}

