template <typename T>
using V = vector<T>;

typedef long double ld;


int N;

int64_t solve(V<int64_t> A) {
	int64_t sum = A[0], ans = 0;
	for (int i = 1; i < N; ++i) {
		int64_t next = sum + A[i];
		// cout << next << endl;
		if (next == 0) {
			++ans;
			if (sum < 0)
				next = 1;
			else
				next = -1;
		} else if (sum < 0) {
			if (next < 0) {
				ans += abs(next)+1;
				next = 1;
			}
		} else {
			if (next > 0) {
				ans += next+1;
				next = -1;
			}
		}
		sum = next;
	}
	return ans;
}

int64_t solve_fast(V<int64_t> A) {
	int64_t ans, tmp = A[0];
	if (A[0] <= 0)
		A[0] = 1;
	ans = abs(A[0]-tmp)+solve(A);
	A[0] = tmp;
	if (A[0] >= 0)
		A[0] = -1;
	ans = min(ans, abs(A[0]-tmp)+solve(A));
	return ans;
}

V<int64_t> A;

V<V<int64_t>> DP(50000, V<int64_t>(10, -1));

int64_t f(int psum, int i) {
	if (i == A.size())
		return 0;

	if (DP[psum+10000][i] != -1)
		return DP[psum+10000][i];
	int64_t ans = 1e18, sum = psum + A[i];

	for (int v = -100; v <= 100; ++v) {
		if (psum < 0 && psum + v > 0) {
			ans = min(ans, f(psum+v, i+1)+abs(A[i]-v));
		} else if (psum > 0 && psum + v < 0) {
			ans = min(ans, f(psum+v, i+1)+abs(A[i]-v));
		}
	}
	return DP[psum+10000][i] = ans;
}


