ll solve(VL &as, bool positive) {
  ll ans = 0;
  ll sum = 0;
  FOR(a,as) {
    ll nsum = sum + a;
    if(positive) {
      if(nsum <= 0) {
        ans += 1 - nsum;
        nsum = 1;
      }
    } else {
      if(nsum >= 0) {
        ans += 1 + nsum;
        nsum = -1;
      }
    }
    sum = nsum;
    positive = !positive;
  }
  return ans;
}

