using memo = std::map<std::multiset<std::uint64_t>, bool>;

memo m;

// true == alice
bool solve(std::uint64_t x, std::uint64_t y) {

    // from memo
    auto it = m.find({x, y});
    if (it != m.end()) return it->second;

    // I lose
    if (x < 2 && y < 2) {
        m.insert(memo::value_type({x, y}, false));
        return false;
    }

    bool result = false;
    for (std::uint64_t ix = 2; ix <= x; ix += 2) {
        result = result || !solve(x - ix, y + ix / 2);
    }
    for (std::uint64_t iy = 2; iy <= y; iy += 2) {
        result = result || !solve(x + iy / 2, y - iy);
    }
    m.insert(memo::value_type({x, y}, result));
    return result;
}

