using namespace std;

long greedy(long s, int i, int a[], int n) {
    if (i >= n)
        return 0;
    long ns = s + a[i];
    if (ns * s < 0)
        return greedy(ns, i + 1, a, n);
    if (s > 0)
        return ns + 1 + greedy(-1, i + 1, a, n);
    return - ns + 1 + greedy(1, i + 1, a, n);
}

long solve(int a[], int n) {
    return min(max(1 - a[0], 0) + greedy(max(a[0], 1), 1, a, n), max(a[0] + 1, 0) + greedy(min(a[0], -1), 1, a, n));
}

