using namespace std;

int sumPrefix(vector<int> &a, int end) {
  int sum = 0;
  for (int i = 0; i <= end; i++) {
    sum += a.at(i);
  }
  return sum;
}

int improveSeq(vector<int> &a, bool positive) {
  int res = 0;
  for (int i = 1; i < a.size(); i++) {
    int sum = sumPrefix(a, i);
    if (positive && sum >= 0) {
      a.at(i) -= (sum + 1);
      res += abs(sum + 1);
    }
    if (!positive && sum <= 0) {
      a.at(i) += (-sum + 1);
      res += abs(-sum + 1);
    }
    positive = sumPrefix(a, i) > 0;
  }
  return res;
}

