int Move(int *A,int N,int remain){
    int i,sum = 0,moveCount = 0;
    for (i=0;i<N;i++){
        if (i%2==remain){
            if (sum + A[i] > 0){
                sum += A[i];
            }else{
                moveCount+=  - sum - A[i] + 1;
                sum = 1;
            }
        }else{
            if (sum + A[i] < 0){
                sum += A[i];
            }else{
                moveCount += sum + A[i] + 1;
                sum = - 1;
            }
        }
    }
    return moveCount;
}

