ll solve(bool plus,ll ans){
		if(plus==1){
				if(a[0]<=0){a[0]=1;ans=1;s[0]=1;}
				else s[0]=a[0];
		}else{
				if(a[0]>=0){a[0]=-1;ans=1;s[0]=-1;}
				else s[0]=a[0];
		}
		for(int i=0;i<n-1;i++){
				ll t=s[i]+a[i+1];
				if(s[i]*t>=0){
						if(s[i]<0){
								ll b=a[i+1];
								s[i+1]=1;
								a[i+1]=s[i+1]-s[i];
								ans+=(a[i+1]-b);
						}else if(s[i]>0){
								ll b=a[i+1];
								s[i+1]=-1;
								a[i+1]=s[i+1]-s[i];
								ans+=(b-a[i+1]);
						}
				}else{
						s[i+1]=t;
				}
		}
		//for(int i=0;i<n;i++)cout<<s[i]<<endl;
		//cout<<ans<<endl;
		return ans;
}

