// 300, 9min

ll N;

// [1, N]
ll bit1[MAX_N + 1];
ll bit2[MAX_N + 1];
// [1, i] の合計値を返す O(logn)
ll sum1(int i) {
    ll s = 0;
    while(i > 0) {
        s += bit1[i];
        i -= i & -i;
    }
    return s;
}
ll sum2(int i) {
    ll s = 0;
    while(i > 0) {
        s += bit2[i];
        i -= i & -i;
    }
    return s;
}
// ai に x を足して更新　O(logn)
void add1(int i, ll x) {
    while(i <= N) {
        bit1[i] += x;
        i += i & -i;
    }
}
void add2(int i, ll x) {
    while(i <= N) {
        bit2[i] += x;
        i += i & -i;
    }
}

int main()
{
    cin >> N;
    REP(i, N) {
        ll a;
        cin >> a;
        add1(i+1, a);
        add2(i+1, a);
    }
    ll ans, prev, cand;
    auto Check1 = [&]() {
        for(int i = 2; i <= N; ++i) {
            if(sum1(i) == 0) {
                cand++;
                if(sum1(i-1) > 0) { add1(i, -1); }
                else { add1(i, 1); }
            }
            else if(sum1(i) > 0 && sum1(i-1) > 0) {
                ll diff = sum1(i) + 1;
                cand += diff;
                add1(i, -diff);
                assert(sum1(i) < 0);
            }
            else if(sum1(i) < 0 && sum1(i-1) < 0) {
                ll diff = 1 - sum1(i);
                cand+= diff;
                add1(i, diff);
                assert(sum1(i) > 0);
            }
            DBG("i: %d cand: %lld\n", i, cand);
        }
    };
    auto Check2 = [&]() {
        for(int i = 2; i <= N; ++i) {
            if(sum2(i) == 0) {
                cand++;
                if(sum2(i-1) > 0) { add2(i, -1); }
                else { add2(i, 1); }
            }
            else if(sum2(i) > 0 && sum2(i-1) > 0) {
                ll diff = sum2(i) + 1;
                cand += diff;
                add2(i, -diff);
                assert(sum2(i) < 0);
            }
            else if(sum2(i) < 0 && sum2(i-1) < 0) {
                ll diff = 1 - sum2(i);
                cand+= diff;
                add2(i, diff);
                assert(sum2(i) > 0);
            }
            DBG("i: %d cand: %lld\n", i, cand);
        }
    };
    if(sum1(1) == 0) {
        ans = INF;

        add1(1, 1);
        cand = 1;
        prev = sum1(1);
        Check1();
        ans = min(ans, cand);

        add2(1, -1);
        cand = 1;
        prev = sum2(1);
        Check2();
        ans = min(ans, cand);
    } else {
        ans = INF;

        // そのまま
        cand = 0;
        prev = sum1(1);
        Check1();
        ans = min(ans, cand);

        // 反対の符号
        cand = abs(sum2(1)) + 1;
        if(sum2(1) > 0) {
            add2(1, -cand);
        } else {
            add2(1, cand);
        }
        prev = sum2(1);
        Check2();
        ans = min(ans, cand);
    }
    printf("%lld\n", ans);
    return 0;
}

