class Solution {
public:
  int n;
  vector<int> a;

  long long dfs(int now, long long sum)
  {
    if(now == n) {
      return 0;
    }
    long long score = sum + a[now];
    long long res = 0;
    if(!now && !score) {
      res = min(dfs(now + 1, score + 1), dfs(now + 1, score - 1)) + 1;
    } else if (!now) {
      res = dfs(now + 1, score);
      if(score < 0) {
        res = min(res, 1 - score + dfs(now + 1, 1));
      } else {
        res = min(res, 1 + score + dfs(now + 1, -1));
      }
    } else {
      if(sum < 0) {
        if(score > 0) {
          res = dfs(now + 1, score);
        } else {
          res = 1 - score + dfs(now + 1, 1);
        }
      } else {
        if (score < 0) {
            res = dfs(now + 1, score);
        } else {
            res = score + 1 + dfs(now + 1, -1);
        }
      }
    }
    return res;
  }

  void solve(std::istream& in, std::ostream& out)
  {
    in >> n;
    a.resize(n);
    for (auto&& i : a) {
      in >> i;
    }
    out << dfs(0, 0) << "\n";
  }
};

void solve(std::istream& in, std::ostream& out)
{
  out << std::setprecision(12);
  Solution solution;
  solution.solve(in, out);
}


