int sign(long sum)
{
  if (sum == 0) return sum;
  return sum > 0 ? 1 : -1;
}

long solve(const vector<int>& a)
{
  int first = 0;
  while (a[first++] == 0);
  int _sum = (a[first] > 0 ? 1 : -1) * (first % 2 == 1 ? 1 : -1);
  int _s = sign(_sum);
  long op = 0;
  long sum = 0;
  for(int i = 0; i < a.size(); ++i) {
    sum += a[i];
    int s = sign(sum);
    // cerr << "a[" << i << "]: " << a[i] << " " << _sum << "|" << _s << " " << sum << "|" << s << endl;
    if (_s * s >= 0) {
      if (_s > 0) {
        op += sum + 1;
        sum = -1;
      } else {
        op += (1 - sum);
        sum = 1;
      }
    }
    _s *= -1;
  }
  return op;
}

