ll solve(int n, ll sum, std::vector<int, std::allocator<int>> &a) {
  ll ans = 0;
  bool is = sum > 0;

  rep(i, 1, n) {
    if (is) {
      sum += a[i];
      if (sum >= 0) {
        ans += sum + 1;
        sum = -1;
      }
      is = false;
    }
    else {
      sum += a[i];
      if (sum <= 0) {
        ans += -sum + 1;
        sum = 1;
      }
      is = true;
    }
    err(sum, ans);
  }
  return ans;
}

void Calc() {

  int n = in;
  auto a = in.Array(n);

  ll ans = 0;
  ll sum = a[0];
  if (a[0] == 0) {
    ans = solve(n, -1, a) + 1;
    amin(ans, solve(n, 1, a) + 1);
  }
  else {
    ans = solve(n, sum, a);
  }
  cout << (ans) << endl;

}

