  vector<int> a = vector<int>(n);
  for (int i = 0; i < n; i++) cin >> a.at(i);

  vector<int> aPositive = vector<int>();
  copy(a.begin(), a.end(), back_inserter(aPositive));
  int countPositive = improveSeq(aPositive, true);

  vector<int> aNegative = vector<int>();
  copy(a.begin(), a.end(), back_inserter(aNegative));
  int countNegative = improveSeq(aNegative, false);

  int count = countPositive < countNegative ? countPositive : countNegative;
  cout << count << endl;
  return 0;
}

