void get(int x) {
	tmp=0;
	memset(sum,0,sizeof(sum));
	if(a[0]==0)tmp++,sum[0]=x;
	else{
		if(x*a[0]<0){
			if(x==1){
				sum[0]=1;
				tmp = tmp + x - a[0];
			}else{
				sum[0]=-1;
				tmp = tmp + a[0] - x;
			}
		}else sum[0] = a[0];
	}

	for(int i=1;i<n;i++){
		if(sum[i-1]>0){
			if(sum[i-1]+a[i]<0){
				sum[i]=sum[i-1]+a[i];
				continue;
			}else{
				sum[i]=-1;
				tmp=tmp+sum[i-1]+a[i]+1;
				continue;
			}
		}else{
			if(sum[i-1]+a[i]>0){
				sum[i]=sum[i-1]+a[i];
				continue;
			}else{
				sum[i]=1;
				tmp=tmp+1-sum[i-1]-a[i];
				continue;
			}
		}
	}

