long long CalcCost(long long currV[]) {
  long long ans = 0;
  memset(pSum, 0, sizeof pSum);
  pSum[1] = currV[1];
  for (int i = 2; i <= n; ++i) {
    pSum[i] = pSum[i - 1] + currV[i];

    if (pSum[i - 1] > 0 and pSum[i] >= 0) {
      pSum[i] = -1;
      ans += currV[i] - (- 1 - pSum[i - 1]);
      currV[i] = - 1LL - pSum[i - 1];
//      --currV[i];
//      pSum[i] = pSum[i - 1] + currV[i];
//      ++ans;
    }

    if (pSum[i - 1] < 0 and pSum[i] <= 0) {
      pSum[i] = 1;
      ans += -(currV[i] - (1 - pSum[i - 1]));
      currV[i] = 1LL - pSum[i - 1];
//      ++currV[i];
//      pSum[i] = pSum[i - 1] + currV[i];
//      ++ans;
    }
  }

  return ans;
}

int main() {
