    cin >> v[i];
  }

  if (v[1] < 0) {
    cost1 = CalcCost(v);
    while (v[1] <= 0) {
      ++v[1];
      ++cost0;
    }

    cost0 += CalcCost(v);
  }
  else if (v[1] > 0) {
    cost0 = CalcCost(v);
    while (v[1] >= 0) {
      --v[1];
      ++cost1;
    }
    cost1 += CalcCost(v);
  }
  else {
    v[1] = 1;
    cost0 = 1 + CalcCost(v);
    v[1] = -1;
    cost1 = 1 + CalcCost(v);
  }

  cout << min(cost0, cost1) << '\n';
  return 0;
}

