bool win(int x, int y) {
    if(x>y) swap(x,y);

    if((x==1 && y==1) || (x==0 && y==1)) return false;

    for(int i=1;2*i<=x;i++) {
        if(!win(x-2*i, y+i)) return true;
    }

    for(int i=1;2*i<=y;i++) {
        if(!win(x+i, y-2*i)) return true;
    }

    return false;
}

