ll solve(vector<ll> a){
	const int n = a.size();
	ll acc = 0, answer = 0;
	for(int i = 0; i < n; ++i){
		if(i % 2 == 0){
			const ll t = max(a[i], -acc + 1);
			answer += (t - a[i]);
			acc += t;
		}else{
			const ll t = min(a[i], -acc - 1);
			answer += (a[i] - t);
			acc += t;
		}
	}
	return answer;
}

