using ll = long long;

int main() {
  ll n;
  cin >> n;
  vector<ll> A(n);
  for (ll i = 0; i < n; ++i) {
    cin >> A[i];
  }

  ll last_sum = A[0];
  ll result = 0;
  if (A[0] == 0) {
    if (0 < A[1]) {
      --A[0];
      ++result;
      --last_sum;
    } else {
      ++A[0];
      ++result;
      ++last_sum;
    }
  }

  for (ll i = 1; i < n; ++i) {
    ll sum = last_sum + A[i];
    if (sum == 0) {
      if (last_sum < 0) {
        ++A[i];
        ++result;
        ++sum;
      } else {
        --A[i];
        ++result;
        --sum;
      }
    } else if (last_sum < 0 && sum < 0) {
      A[i] += 1 + abs(sum);
      sum = 1;
      result += 1 + abs(sum);
    } else if (0 < sum && 0 < last_sum) {
      A[i] += sum + 1;
      sum = -1;
      result += sum + 1;
    }
    last_sum = sum;
    cout << result << " ";
  }
  cout << endl;
  cout << result << endl;
}

