int main(){
    int N;
    cin >> N;
    vector<ll> A(N+1);
    ll a;
    ll sum = 0ll;
    ll count1 = 0ll;
    ll count2 = 0ll;
    for(int i=1;i<=N;i++){
        cin >> A[i];
    }

    for(int i=1;i<=N;i++){
        sum += A[i];
        if(i%2==0){ // sum > 0
            if(sum <= 0 ){
                count1 += 1 + abs(sum);
                sum = 1;
            }
        }else{ // sum < 0
            if(sum >= 0){
                count1 += sum + 1;
                sum = -1;
            }
        }
    }
    sum = 0ll;
    for(int i=1;i<=N;i++){
        sum += A[i];
        if(i%2==1){ // sum > 0
            if(sum <= 0 ){
                count2 += 1 + abs(sum);
                sum = 1;
            }
        }else{ // sum < 0
            if(sum >= 0){
                count2 += sum + 1;
                sum = -1;
            }
        }
    }
    cout << min(count1, count2) << endl;
}

