#define MOD 1000000007
#define INF 1000000000
#define MAX_N 100010

// 300, 9min

ll N;
ll A[MAX_N] = {};
ll Con[MAX_N] = {}; // i までの累積和

int main()
{
    cin >> N;
    REP(i, N) { cin >> A[i]; }
    Con[0] = A[0];
    for(int i = 1; i < N; ++i) {
        Con[i] = Con[i-1] + A[i];
    }
    ll ans = INF;
    ll cand = 0;
    ll diff = 0;
    ll prev = Con[0];

    auto Check = [&]() {
        for(int i = 1; i < N; ++i) {
            if(Con[i] + diff == 0) {
                if(prev < 0) {
                    diff++;
                    cand++;
                } else {
                    diff--;
                    cand++;
                }
            }
            else if(Con[i] + diff > 0 && prev > 0) {
                cand += abs(Con[i] + diff) + 1;
                diff -= (abs(Con[i] + diff) + 1);
            }
            else if(Con[i] + diff < 0 && prev < 0) {
                cand += abs(Con[i] + diff) + 1;
                diff += (abs(Con[i] + diff) + 1);
            }
            prev = Con[i] + diff;
            //printf("i: %d cand: %lld diff: %lld\n", i, cand, diff);
        }
    };

    if(Con[0] == 0) {
        // prev が - の場合と + の場合両方やって良い方を採用
        ll pat[2] = {-1, 1};
        for(int p = 0; p < 2; ++p) {
            cand = 1;
            diff = pat[p];
            prev = pat[p];
            Check();
            ans = min(ans, cand);
        }
    } else {
        Check();
        ans = cand;
    }

    printf("%lld\n", ans);
    return 0;
}

