  int64_t out = numeric_limits<int64_t>::max();

  for(size_t k = 0; k < 2; ++ k)
  {
    int64_t acc = 0, val = 0;
    for(size_t i = 0; i < n; ++i)
    {
      acc += a[i];
      int64_t inc;

      if((i & 1) == k)
        inc = acc - min(acc, (int64_t) -1);
      else
        inc = max(acc, (int64_t)1) - acc;

      val += inc;
      acc += (i & 1) == k ? -inc : inc;
    }

    out = min(out, val);
  }
  cout << out << '\n';

  return EXIT_SUCCESS;
}

