const ll INF = 1ll<<60;
const ll MOD = 1000000007;
const double EPS  = 1e-10;

int n;
ll a[112345];

ll solve(ll st) {
	ll res = 0;
	bool bef = st > 0; // true:pos, false:neg

	ll sum = st;

	FOR(i, 1, n) {
		sum += a[i];
		if (sum == 0) {
			if (bef) sum = -1;
			else sum = 1;
			res++;
		}
		else {
			if (bef) {
				if (sum > 0) {
					res += sum + 1;
					sum = -1;
				}
			}
			else {
				if (sum < 0) {
					res += -sum + 1;
					sum = 1;
				}
			}
		}

		bef ^= 1;
	}	


	return res;
}

int main() {
	cin >> n;
	REP(i, n) scanf("%lld", a + i);

	ll ans;

	if (a[0] == 0) {
		ans = solve(1) + 1;

		chmin(ans, solve(-1) + 1);
	}
	else {
		ans = solve(a[0]);
		if (a[0] > 1) chmin(ans, solve(-1) + a[0] + 1);
		else chmin(ans, solve(1) - a[0] + 1);
	}

	cout << ans << endl;
	return 0;
}

