#define mod 1000000007

int n;
int a[100001];

int solve()
{
	long long int sum = a[0];
	long long int ans = 0;
	for(int i = 1; i < n; i++){
		if(sum > 0 && sum + a[i] >= 0){
			ans += abs(-1 - sum - a[i]);
			sum += -1 - sum;
		} else if(sum < 0 && sum + a[i] <= 0){
			ans += abs(1 - sum - a[i]);
			sum += 1 - sum;
		} else {
			sum += a[i];
		}
	}
	return ans;
}

int main()
{
	cin >> n;
	for(int i = 0; i < n; i++){
		cin >> a[i];
	}
	long long int tmp1 = 0, tmp2 = 0;
	int tmp = a[0];
	if(a[0] <= 0){
		a[0] = 1;
		tmp1 += 1 - a[0];
	}
	tmp1 += solve();
	a[0] = tmp;
	if(a[0] >= 0){
		a[0] = -1;
		tmp2 += a[0] + 1;
	}
	tmp2 += solve();
	cout << min(tmp1, tmp2) << endl;
}

