typedef long long ll;
const int MAXN = 100100;

int N;
ll arr[MAXN];

ll res()
{
    ll ctot = 0;
    ll ans = 0;
    for (int i = 0; i < N; i++)
    {
        ctot += arr[i];
        if (i % 2 == 0)
        {
            if (ctot <= 0)
            {
                ans += 1 - ctot;
                ctot = 1;
            }
        }
        else
        {
            if (ctot >= 0)
            {
                ans += ctot + 1;
                ctot = -1;
            }
        }
    }
    return ans;
}

