	vector<ll> A(N);
	rep(i, N) {
		cin >> A[i];
	}

	ll sum = A[0];
	bool zeroHead = (sum == 0 ? true : false);
	ll result = (zeroHead ? 1 : 0); //+1か-1に決まるので

	reps(i, 1, N - 1) {
		//先頭から0続きのチェック
		if (zeroHead == true) {
			if (A[i] == 0) {
				result += 2; //+2か-2に決まるので
				continue;
			}
			else {
				if (A[i] > 0) {
					//i-1までの累積和を-1で確定させる
					sum = -1;
				}
				else {
					//i-1までの累積和を1で確定させる
					sum = 1;
				}
			}
		}

		if (sum > 0) {
			if (sum + A[i] < 0) {
				//符号反転するので、そのまま
				sum += A[i];
			}
			else {
				//符号反転するように変更(-1にする)
				ll change = -1 - sum;
				result += abs(A[i] - change);
				sum = -1;
			}
		}
		else {
			if (sum + A[i] > 0) {
				//符号反転するので、そのまま
				sum += A[i];
			}
			else {
				//符号反転するように変更(+1にする)
				ll change = 1 - sum;
				result += abs(A[i] - change);
				sum = -1;
			}
		}
	}

	cout << result << endl;

	return 0;
}

