int main()
{
	cin.tie(0);
	ios::sync_with_stdio(false);

	int n;
	cin >> n;

	ll a[n];
	rep(i,n) cin >> a[i];

	//plus when even
	ll ans_plus = 0;
	ll sum = 0;
	rep(i,n){
		sum += a[i];
		if(i % 2 == 0){
			if(sum <= 0) {
				ans_plus += 1 - sum;
				sum += 1 - sum;
			}
		}else{
			if(sum >= 0){
				ans_plus += sum + 1;
				sum -= sum + 1;
			}
		}
	}

	//minus when even
	ll ans_minus = 0;
	sum = 0;
	rep(i,n){
		sum += a[i];
		if(i % 2 == 1){
			if(sum <= 0) {
				ans_minus += 1 - sum;
				sum += 1 - sum;
			}
		}else{
			if(sum >= 0){
				ans_minus += sum + 1;
				sum -= sum + 1;
			}
		}
	}

	cout << min(ans_plus,ans_minus) << endl;	
}

