int sign(int n) {
  return (n > 0) - (n < 0);
}

int cost(int n, int a[]) {
  int sum = a[0];
  int res = 0;

  for (int i = 1; i < n; ++i) {
    if (sum + a[i] == 0 or sign(sum) == sign(sum + a[i])) {
      res += abs(sum + a[i]) + 1;
      sum = -1 * sign(sum);
    } else {
      sum += a[i];
    }
  }

  return res;
}

int main(int argc, char *argv[]) {
  int n;
  cin >> n;
  int a[n];
  for (int i = 0; i < n; ++i) {
    cin >> a[i];
  }

  int init = a[0] == 0;
  a[0] += init;
  int res = cost(n, a);
  int a0 = abs(a[0] - init);
  a[0] = -1 * sign(a[0]);
  res = min(res, cost(n, a) + a0 + 1);
  cout << res << endl;

  return 0;
}

