using namespace std;

int min(int a, int b){
  return a < b ? a : b;
}


int calc(const vector<int>& a, int sig,
         int sum = 0, int ope = 0, size_t index = 0){
  if(index == a.size()){ return ope; }

  sum += a[index];

  // プラスに押しあげるフェイズの場合
  if(sig == 1 && sum < 1){
    ope += 1 - sum;
    sum = 1;
  }
  // マイナスに引きさげるフェイズの場合
  else if(sig == -1 && sum > -1){
    ope += sum + 1;
    sum = -1;
  }

  return calc(a, sig * (-1), sum, ope, index + 1);
}

int main(void){
  int n;
  cin >> n;

  vector<int> a(n);
  for(int i = 0; i < n; i++){ cin >> a[i]; }

  cout << min(calc(a, 1), calc(a, -1)) << endl;

  return 0;
}

