int n;
int calc(vi a,int x) {
    int ret=x;
    int sum=a[0];
    REPF(i,1,n) {
        if(sum>0) {
            ret+=abs(a[i]-(-sum-1));
            a[i]=-sum-1;
        }
        else {
            ret+=abs(a[i]-(-sum+1));
            a[i]=-sum+1;
        }
        sum+=a[i];
    }
    return ret;
}
bool check(vi a) {
    int sum=0;
    REP(i,n) {
        sum+=a[i];
        if(sum==0) return false;
        if(sum>0) {
            if(a[i]>=-sum) return false;
        }
        else {
            if(a[i]<=-sum) return false;
        }
    }
    return true;
}
