        a[0]=1;
        chmin(ans,calc(a,1));
        a[0]=-1;
        chmin(ans,calc(a,1));
    }
    else {
        chmin(ans,calc(a,0));
        a[0]=1;
        chmin(ans,calc(a,abs(1-a[0])));
        a[0]=-1;
        chmin(ans,calc(a,abs(-1-a[0])));
    }
    cout<<ans<<endl;
    return 0;
}

