	ll ans;
	if(a[0] == 0){
		a[0] = -1;
		ll ans = 1 + solve(a, n);
		a[0] = 1;
		ans = min(ans, 1 + solve(a, n));
	}else{
		ans = solve(a, n);
	}
	cout << ans << endl;

    return 0;
}

