    int c = 0, s = a[0];
    if (p) {
      if (s <= 0) {
        c += abs(s) + 1;
        s = 1;
      }
    } else {
      if (s >= 0) {
        c += abs(s) + 1;
        s = -1;
      }
    }
    loop(i, 1, n) {
      if (s + a[i] == 0) {
        c++;
        s = -sgn(s);
        continue;
      }
      if (sgn(s) == sgn(s + a[i])) {
        s += a[i];
        c += abs(s) + 1;
        s = -sgn(s);
        continue;
      }
      s += a[i];
    }
    return c;
  };
  cout << min(f(false), f(true)) << endl;
  bye;
}

