ll f(vector<ll> a, ll mode) {
  ll a_size = a.size();

  ll count = 0;
  ll sum = 0;

  for(ll i = 0; i < a_size; i++) {
    if((i + mode) % 2 == 0 && sum + a[i] <= 0) {
      // sum + a[i] を １にする
      count += (1 - sum - a[i]);
      a[i] = 1 - sum;
    }
    if((i + mode) % 2 == 1 && sum + a[i] >= 0) {
      // sum + a[i] を -1にする
      count += (sum + a[i] + 1);
      a[i] = -1 - sum;
    }
    sum += a[i];
  }

  return count;
}


