LL solve(const vector<LL> &a, bool plus){
    LL res = 0;
    LL sum = 0;
    int n = a.size();
    REP(i, n){
        sum += a[i];
        if(plus){
            if(sum <= 0){
                res += 1LL - sum;
                sum = 1LL;
            }
        }else{
            if(sum >= 0){
                res -= -1LL - sum;
                sum = -1LL;
            }
        }
        //cout << sum << endl;
        plus = !plus;
    }
    return res;
}

