    ll co = abs(*itr);
    FOR(i, 1, n){
      _s = s + a[i];
      if(s > 0 && _s >= 0){
        co += _s + 1;
        s = -1;
      }else if(s < 0 && _s <= 0){
        co += 1 - _s;
        s = 1;
      }else{
        s = _s;
      }
    }
    mins(ans, co);
  }
  cout << ans << endl;
  return 0;
}

