int64 solve(const vector<int64>& a, int sign) {
  int n = a.size();
  int64 sum = 0, ret = 0;
  for (int i = 0; i < n; ++i) {
    int64 cur = sum + a[i];
    if (cur >= 0 && sign < 0) {
      sum -= cur + 1;
      ret += cur + 1;
    } else if (cur <= 0 && sign > 0) {
      sum += -cur + 1;
      ret += -cur + 1;
    }
    sign = -sign;
  }
  return ret;
}

