ll dfs(int idx, ll sum, ll ope) {
	if(idx == n) return ope;
	ll t = sum + a[idx];
	if(sum > 0) {
		if(t < 0) return dfs(idx+1, t, ope);
		return dfs(idx+1, -1, ope+t+1);
	}
	else {
		if(t > 0) return dfs(idx+1, t, ope);
		return dfs(idx+1, 1, ope-t+1);
	}
}

