ll helper(ll n, vl a) {
  ll ret = 0;
  if (a[0] == 0) {
    vl a1;
    vl a2;
    rep(i, n) {
      a1.push_back(a[i]);
      a2.push_back(a[i]);
    }
    a1[0] = 1;
    a2[0] = -1;
    ret = min(helper(n, a1), helper(n, a2)) + 1;
  } else {
    ll sum = a[0];
    bool isPos = a[0] > 0;
    for (ll i = 1; i < n; i++) {
      ll sumTmp = sum + a[i];
      if (isPos) {
        if (sumTmp >= 0) {
          ret += sumTmp + 1;
          sum = -1;
        } else {
          sum = sumTmp;
        }
        isPos = false;
      } else {
        if (sumTmp <= 0) {
          ret += 1 - sumTmp;
          sum = 1;
        } else {
          sum = sumTmp;
        }
        isPos = true;
      }
    }
  }
  return ret;
}

void solve(long long n, std::vector<long long> a) {
  ll ret1 = helper(n, a);

  reverse(all(a));
  ll ret2 = helper(n, a);

  ll ans = min(ret1, ret2);

  print(ans);
}

