	ll goukei = v[0];
	For(i, 1, n) {
		goukei += v[i];
		if (upper) {
			if (goukei <= 0) {
				result += (1 - goukei);
				goukei = 1;
			}
			upper = false;
		}
		else {
			if (goukei >= 0) {
				result += (1 + goukei);
				goukei = -1;
			}
			upper = true;
		}
	}
	return result;
}

int main() {
	int n;
	cin >> n;
	vector<ll> v(n);
	rep(i, n)
		cin >> v[i];

	ll result = 0;
	ll goukei = v[0];
	result = min(solve(v, n, true), solve(v, n, true));
	cout << result << endl;

}

