void solve()
{
	int N;
	cin >> N;
	vector<int> a(N);
	for (int i = 0; i < N; ++i)
	{
		cin >> a[i];
	}
	long long int sum = a[0];
	bool isPlus = true;
	if (sum < 0)
	{
		isPlus = false;
	}
	long long int ans = 0;
	for (int i = 1; i < N; ++i)
	{
		sum += a[i];
		if (isPlus)
		{
			if (sum >= 0)
			{
				ans += sum + 1;
				sum = -1;
			}
		}
		else
		{
			if (sum <= 0)
			{
				ans += abs(sum) + 1;
				sum = 1;
			}
		}
		isPlus = !isPlus;
	}
	cout << ans << endl;
}

int main()
{
	solve();
	return(0);
}

