#define f(i, x, n) for(int i = x; i < (int)(n); ++i)

int x[100000], n;

ll c(bool s){
	ll z = 0, an = 0;
	f(i, 0, n){
		z += x[i];
		if (s)an += max(0ll, 1ll - z), z = max(z, 1ll);
		else an += max(0ll, z + 1ll), z = min(z, -1ll);
		s = !s;
	}
	return an;
}

int main(){
	scanf("%d", &n);
	f(i, 0, n)scanf("%d", x + i);
	ll an = min(c(false), c(true));
	printf("%lld\n", an);
}

