int main(){

    long long n; cin >> n;
    vector<long long> a(n, 0);
    for(int i = 0; i < n; i++){
        cin >> a[i];
        if(i != 0) a[i] += a[i - 1];
    }

    /*for(int i = 0; i < n; i++){
        cout << a[i] << " ";
    }*/

    long long ans;


    //+ から始まる
    long long temp = 0;
    long long sa = 0;
    for(int i = 0; i < n; i++){

        //+
        if(i % 2 == 0){
            if(a[i] + sa > 0){}
            else{
                temp += -(a[i] + sa) + 1;
                sa += -(a[i] + sa) + 1;
            }
        }else{  //-
            if(a[i] + sa < 0){}
            else{
                temp += a[i] + sa + 1;
                sa -= a[i] + sa + 1;
            }
        }
    }
    ans = temp;

    //- から始まる
    temp = 0;
    sa = 0;
    for(int i = 0; i < n; i++){

        //+
        if(i % 2 == 1){
            if(a[i] + sa > 0){}
            else{
                temp += -(a[i] + sa) + 1;
                sa += -(a[i] + sa) + 1;
            }
        }else{  //-
            if(a[i] + sa < 0){}
            else{
                temp += a[i] + sa + 1;
                sa -= a[i] + sa + 1;
            }
        }

    }

    ans = (long long)min(ans, temp);
    cout << ans << endl;

    return 0;
}

