const int N = 100000;

struct Input {
	int n;
	int a[N];

	bool read () {
		if (!(cin >> n)) {
			return 0;
		}
		forn (i, n) {
			scanf("%d", &a[i]);
		}
		return 1;
	}

	void init (const Input &input) {
		*this = input;
	}
};

struct Data: Input {
	ll ans;

	void write () {
		cout << ans << endl;
	}
};


namespace Main {

	struct Solution: Data {

		ll calc (int i, ll s, bool b) {
			if (i == n) {
				return 0;
			}
			s += a[i];
			ll pr = s;
			if (b) {
				umx(s, 1);
			} else {
				umn(s, -1);
			}
			return abs(s - pr) + calc(i + 1, s, !b);
		}

		void solve () {
			ans = min(calc(0, 0, 0), calc(0, 0, 1));
		}

		void clear () {
			*this = Solution();
		}
	};
}


