	long long now=a[1];
	int opt=a[1]>0;
	for(int i=2;i<=n;i++)
	{
		if(opt==1)
		{
			if(now+a[i]>=0)
			{
				Ans+=now+a[i]+1;
				now=-1;
			}
			else now+=a[i];
		}
		else
		{
			if(now+a[i]<=0)
			{
				Ans-=now+a[i]-1;
				now=1;
			}
			else now+=a[i];
		}
		opt^=1;
	}
	return Ans;
}

