inline int sgn(ll a,ll b = 0) { return a < b ? -1 : a > b ? 1 : 0; }

void solve(vector<ll> v){
  ll sg = sgn(v[0]);
  ans = 0;
  if(sg == 0){
    ans++;
    v[0] = -1 * sgn(v[1]);
  }
  auto v2 = v;
  s = 0;
  rep(i,n-1){
    s += v[i];
    if(sgn(s) == sgn(s + v[i+1]) || (s + v[i+1] == 0)){
      ans += abs(f(s) - v[i+1]);
      v[i+1] = f(s);
    }
  }
  v = v2;
  ll a = 0;
  if(sg == 0){
    a++;
    v[0] = sgn(v[1]);
  }
  s = 0;
  rep(i,n-1){
    s += v[i];
    if(sgn(s) == sgn(s + v[i+1]) || (s + v[i+1] == 0)){
      a += abs(f(s) - v[i+1]);
      v[i+1] = f(s);
    }
  }
  ans = min(ans,a);
}
