int n;
int calc(bool s, ll sum) {
    ll cnt = 0;
    bool sign = s;
    for(int i=1;i<n;i++) {
        sum += a[i];
        if(sign) {
            if(sum >= 0) {
                cnt += sum + 1;
                sum = -1;
            }
            sign = false;
        } else {
            if(sum <= 0) {
                cnt += abs(sum) + 1;
                sum = 1;
            }
            sign = true;
        }
    }
    return cnt;
}
int main() {
    cin >> n;
    for(int i=0;i<n;i++)
        cin >> a[i];

    ll sum = a[0];
    bool sign;
    if(a[0] > 0) sign = true;
    else sign = false;

    ll ans1 = calc(sign, sum);
    ll ans2 = calc(!sign, -sum) + 2*abs(sum);
    ll ans = min<ll>(ans1, ans2);
    cout << ans << endl;
}

