  cin >> n;
  for(int i = 0; i < n; ++i)
    cin >> a[i];

  if(n == 1) {
    cout << 0 << endl;
    return 0;
  }

  if(a[0] < 0) {
    v[0][0] = 1;
    dp[0][0] = 1 - a[0];

    v[1][0] = a[0];
    dp[1][0] = 0;
  } else if(a[0] > 0) {
    v[0][0] = a[0];
    dp[0][0] = 0;

    v[1][0] = -1;
    dp[1][0] = 1 + a[0];
  } else {
    v[0][0] = 1;
    dp[0][0] = 1;

    v[1][0] = -1;
    dp[1][0] = 1;
  }

  for(int i = 1; i < n; ++i) {
    ll x = a[i];

    v[0][i] = v[1][i-1] + x;
    v[1][i] = v[0][i-1] + x;

    dp[0][i] = dp[1][i-1];
    dp[1][i] = dp[0][i-1];

    if(v[0][i] <= 0) {
      auto d = 1 - v[0][i];
      v[0][i] += d;
      dp[0][i] += d;
    }

    if(v[1][i] >= 0) {
      auto d = 1 + v[1][i];
      v[1][i] -= d;
      dp[1][i] += d;
    }
  }

  cout << min(dp[0][n-1], dp[1][n-1]) << endl;
}

