using namespace std;
typedef long long ll;

int main() {
	int n; scanf("%d", &n);
	vector<int> arr(n, 0);
	for (int i = 0; i < n; ++i) {
		scanf("%d", &arr[i]);
	}
	vector<int> prefix(n, arr[0]);
	for (int i = 1; i < n; ++i) {
		prefix[i] = arr[i] + prefix[i-1];
	}
	ll carry = 0;
	ll total = 0;
	for (int i = 1; i < n; ++i) {
		int realCur = prefix[i] + carry;
		if (realCur > 0 && prefix[i-1] > 0) {
			ll dist = realCur + 1;
			total += dist;
			carry -= dist;
			prefix[i] = -1;
		} else if (realCur < 0 && prefix[i-1] < 0) {
			ll dist = 1 - realCur;
			total += dist;
			carry += dist;
			prefix[i] = 1;
		} else if (realCur == 0) {
			// this is an edge case. fml.
			if (i == n-1) {
				++total; // we're calling it a day soon, screw this
			} else if (prefix[i+1] + carry > 0) { // we're better off shifting down
				--carry;
				++total;
				prefix[i] = -1;
			} else {
				++carry;
				++total;
				prefix[i] = 1;
			}
		} else {
			prefix[i] = realCur;
		}
	}
	printf("%lld\n", total);
	return 0;
}

