			if(sum[i-1]+a[i]>0){
				sum[i]=sum[i-1]+a[i];
				continue;
			}else{
				sum[i]=1;
				tmp=tmp+1-sum[i-1]-a[i];
				continue;
			}
		}
	}

	ans = min(ans,tmp);
}
