void deal(int m, vector<long long> s) {
	long long res=0;
	long long inc;
	for(int i=0; i<s.size(); i++) {
		if( m*s[i] > 0) {
			m*=-1;
			continue;
		}
		else {
			inc=m-s[i];
			for (int j=i+1; j<s.size(); j++)
				s[j]+=inc;
			res+=abs(inc);
		}
		m*=-1;
	}
	cout << res;
}

int main() {
	int n;
	vector<long long> a;
	vector<long long> s;
	cin >> n;
	for (int i=0; i<n; i++) {
		long long x;
		cin >> x;
		a.push_back(x); 
	}

	//find the first non-zero element
	int c = 0;
	for (; c<n; c++) {
		if(a[c] != 0) break;
	}

	long long sum = 0;
	for (int i=0; i<n; i++) {
		sum+=a[i];
		s.push_back(sum);
	}

	if(c == 0) { //a[0] != 0
		if(a[0] > 0) deal(1,s);
		else deal(-1,s);
	} else if(c != n) { //a[0] ~ a[c-1] == 0
		if(c%2 == 0) { // 2n		
			if(a[c] > 0) { //a[0]=1
				deal(1,s);
			} else { //a[0]=-1
				deal(-1,s);
			}
		} else { // 2n+1
			if(a[c] < 0) { //a[0]=1
				deal(1,s);
			} else { //a[0]=-1
				deal(-1,s);
			}
		}
	} else if(c == n) { //all 0
		deal(1,s);
	}

	return 0;
}

