        sum += a[i];
      } else {
        cur += std::abs(sum+a[i]-sgn(-sum));
        sum = sgn(-sum);
      }
      fprintf(stderr, " %jd(%jd)", sum, cur);
    }
    res = std::min(res, cur);
    fprintf(stderr, "\n");
  }

  printf("%jd\n", res);
}

