int dx[] = { 1,0,-1,0 };
int dy[] = { 0,1,0,-1 };

int solve(vector<ll> v, int n) {
	ll result = 0;
	ll goukei = v[0];
	bool upper = false;
	if (v[0] < 0) {
		upper = true;
	}
	For(i, 1, n) {
		goukei += v[i];
		if (upper) {
			if (goukei <= 0) {
				result += (1 - goukei);
				goukei = 1;
			}
			upper = false;
		}
		else {
			if (goukei >= 0) {
				result += (1 + goukei);
				goukei = -1;
			}
			upper = true;
		}
	}
	return result;
}

int main() {
	int n;
	cin >> n;
	vector<ll> v(n);
	rep(i, n)
		cin >> v[i];

	ll result = 0;
	ll goukei = v[0];
	if (v[0] != 0) {
		result = solve(v,n);
	}
	else {
		v[0] = 1;
		ll result1 = solve(v, n);
		v[0] = -1;
		ll result2 = solve(v, n);
		result = min(result1, result2);
	}
	cout << result << endl;

}

