vector<int> sum_arr;

int main(){
    int n;
    cin >> n;
    vector<int> num_arr;
    REP(i,n){
        int tmp;
        cin >> tmp;
        num_arr.push_back(tmp);
    }
    REP(i,n){
        if(i == 0) {
            sum_arr.push_back(num_arr[i]);
        }else{
            sum_arr.push_back(num_arr[i] + sum_arr[i - 1]);
        }
    }

    //戦闘が-の場合
    vector<int> tmp_arr = sum_arr;
    int cnt1 = 0;
    REP(i,n){
        if(i % 2 == 0){
            if(tmp_arr[i] >= 0){
                int add = -1 - tmp_arr[i];
                for(int j = i; j < n; j++){
                    tmp_arr[j] += add;
                    // cnt1++;
                }
                cnt1 += abs(add);
            }
        }else{
            if(tmp_arr[i] <= 0 ){
                int add = 1 - tmp_arr[i];
                for(int j = i; j < n; j++){
                    tmp_arr[j] += add;
                    // cnt1++;
                }
                cnt1 += abs(add);
            }
        }
    }

    //戦闘が+の場合
    tmp_arr = sum_arr;
    int cnt2 = 0;
    REP(i,n){
        if(i % 2 == 1){
            if(tmp_arr[i] >= 0){
                int add = -1 - tmp_arr[i];
                for(int j = i; j < n; j++){
                    tmp_arr[j] += add;
                    // cnt1++;
                }
                cnt2 += abs(add);
            }
        }else{
            if(tmp_arr[i] <= 0 ){
                int add = 1 - tmp_arr[i];
                for(int j = i; j < n; j++){
                    tmp_arr[j] += add;
                    // cnt1++;
                }
                cnt2 += abs(add);
            }
        }
    }

    cout << min(cnt1,cnt2) <<  endl;
    return 0;
}

