int main()
{
    //freopen("input.in", "r", stdin);
    ll N, L;
    while(cin>>N>>L){
        deque<pair<ll, ll>> dp;
        vector<ll> T(N, 0), V(N, 0);
        for(int i=0;i<N;i++){
            cin>>T[i]>>V[i];
        }
        ll tt=0, vv=0;
        for(int i=0;i<N;i++){
            ll t=T[i]*V[i], v=V[i];
            while(vv+v>L){
               ll t1=dp[0].first, v1=dp[0].second;
               ll tmp=min(vv+v-L, v1);
               tt=tt-t1*tmp/v1;
               vv-=tmp;
               if(tmp==v1){
                   dp.pop_front();
               }
               else{
                   dp[0].first=t1-t1*tmp/v1;
                   dp[0].second=v1-tmp;
               }
            }

            tt+=t;
            vv=L;
            printf("%.7lf\n", (double)tt/vv);
            int ans=dp.size();
            ll c1=t;
            ll c2=v;
            while(ans){
                ll t2=dp[ans-1].first, v2=dp[ans-1].second;
                if(t2/v2<c1/c2){
                    break;
                }
                else{
                    c1+=t2;
                    c2+=v2;
                    dp.pop_back();
                }
                ans=dp.size();
            }
            dp.push_back(make_pair(c1, c2));
        }
    }
