class CumulativeSum{
public:
  vector<int> sum;
  CumulativeSum(){}
  CumulativeSum(vector<int> A){
    int n = A.size();
    sum.resize(n+1,0);
    for(int i=1;i<=n;i++) sum[i] += sum[i-1] + A[i-1];
  }
  int get(int l,int r){assert(l>=0 && r<=(int)sum.size());return sum[r] - sum[l];} //[l,r)
};

int calc(vector<int> A){
  if(A[0] == 0) return INF;
  int n = A.size();
  int res = 0;
  int ofset = 0;
  CumulativeSum Sum(A);

  for(int i=0;i<n-1;i++){
    int a = Sum.get(0,i+1) + ofset;
    int b = Sum.get(0,i+2) + ofset;
    if((a < 0 && b < 0) || (a > 0 && b > 0) || (b == 0)){
      res += abs(b) + 1;
      ofset += -b + (a < 0? 1:-1);
    }
  }
  return res;
}

int calc2(vector<int> A){

  int n = A.size();
  int res = 0;
  int ofset = 0;
  CumulativeSum Sum(A);

  for(int i=0;i<n-1;i++){
    int a = Sum.get(0,i+1) + ofset;
    int b = Sum.get(0,i+2) + ofset;
    if((a < 0 && b < 0) || (a > 0 && b > 0) || (a == 0)){
      res += abs(a) + 1;
      ofset += -a + (b < 0? 1:-1);
    }
  }
  if(Sum.get(0,n) + ofset == 0) res++;
  return res;
}

