int N;
int A[MAX_N];

ll solve2() {
	ll res = 0, ans = 0;
	rep(i, 0, N) {
		res += A[i];
		//debug(i, res, ans);
		if(i % 2 == 0) {
			if(res <= 0) {
				ans += 1 - res;
				res = 1;
			}
		}
		else {
			if(res >= 0) {
				ans += res + 1;
				res = -1;
			}
		}
	}
	return ans;
}

void solve() {
	cin >> N;
	rep(i, 0, N) cin >> A[i];
	ll ans = inf;
	ans = min(ans, solve2());
	rep(i, 0, N) A[i] *= -1;
	ans = min(ans, solve2());
	cout << ans << "\n";
}

