	sum += x;
	if(pos){
		if(sum > 0)return 0;
		long long int ret = 1 - sum;
		sum = 1;
		return ret;
	}else{
		if(sum < 0)return 0;
		long long int ret = sum + 1;
		sum = -1;
		return ret;
	}
}
