ll INF = 1LL<<50, ares;
pll mer(pll a, pll b) {return pll(max(a.first,b.first),min(a.second,b.second));}
ll dis(pll a, pll b) {return min(abs(a.first-b.second),abs(a.second-b.first));}
int main() {
    int i;
    scanf("%d",&n);
    ares = INF;
    for (i=1;i<=n;i++) scanf("%d",&arr[i]);
    for (i=1;i<=n;i++) sum[i] = sum[i-1]+arr[i];
    int s = 1;
    for (i=1;i<=n;i++,s=-s) {
        ran[i] = ((s>0)?pll(s-sum[i],s*INF):pll(s*INF,s-sum[i]));
    }
    ran[0] = pll(0,0);
    pll ret = ran[n];
    ll res = 0;
    for (i=n-1;i>=0;i--) {
        pll tmp = mer(ret,ran[i]);
        if (tmp.first>tmp.second) {
            res += dis(ret,ran[i]);
            if (ret.second<ran[i].first) ret = pll(ran[i].first,ran[i].first);
            else ret = pll(ran[i].second,ran[i].second);
        }
        else ret = tmp;
    }
    ares = min(ares,res);
    s = -1;
    for (i=1;i<=n;i++,s=-s) {
        ran[i] = ((s>0)?pll(s-sum[i],s*INF):pll(s*INF,s-sum[i]));
    }
    ret = ran[n];
    res = 0;
    for (i=n-1;i>=0;i--) {
        pll tmp = mer(ret,ran[i]);
