	ll sum = 0;
	ll pans = 0;
	fr(i, 0, n){
		sum += a[i];
		ll add = 0;
		ll s = (i&1 ? -1 : 1);
		if(i&1){
			add = max(0LL, sum - (-1LL) );
		}else{
			add = max(0LL, (1LL) - sum);
		}
		pans += add;
		sum += add * s;
	}
	ans = min(ans, pans);

