		if(!(i&1)){
			add = max(0LL, sum - (-1LL) );
		}else{
			add = max(0LL, (1LL) - sum);
		}
		pans += add;
		sum += add * s;
	}
	ans = min(ans, pans);

	cout << ans << endl;
}

