using namespace std;

const int maxn=1e5+1e2;

#define LL long long

int a[maxn],n;
LL sum[maxn],sumo[maxn];

inline int lowbit(int x)
{
	return x&-x;
}

void add(int p,LL v)
{
	while(p<=n)
	{
		sumo[p]+=v;
		p+=lowbit(p);
	}
}

LL query(int p)
{
	LL re=0;
	while(p>0)
	{
		re+=sumo[p];
		p-=lowbit(p);
	}
	return re;
}

int getint()
{
	char ch;int b=1;
	for(ch=getchar();ch>'9'||ch<'0';ch=getchar())if(ch=='-')b=-1;
	int num=ch-'0';
	for(ch=getchar();ch>='0'&&ch<='9';ch=getchar())num=num*10+ch-'0';
	return num*b; 
}

LL solve()
{
	memset(sumo,0,sizeof(sumo));
	for(int i=1;i<=n;i++){add(i,sum[i]);add(i+1,-sum[i]);}
	LL re=0;
	for(int i=1;i<=n;i++)
	{
		sum[i]=query(i);
		if(sum[i]>=0&&sum[i-1]>0)
		{
			re+=sum[i]+1;
			add(i,-sum[i]-1);
			sum[i]=-1;
		}
		else if(sum[i]<=0&&sum[i-1]<0)
		{
			re+=-sum[i]+1;
			add(i,-sum[i]+1);
			sum[i]=1;
		}
	}
	return re;
}

int main()
{
	n=getint();
	for(int i=1;i<=n;i++)
	{
		a[i]=getint();
		sum[i]=sum[i-1]+a[i];
	}
	LL ans=1e17;
	sum[0]=-1;
	ans=min(ans,solve());
	sum[0]=0;
	for(int i=1;i<=n;i++)sum[i]=sum[i-1]+a[i];
	sum[0]=1;
	ans=min(ans,solve());
	printf("%lld\n",ans);
	return 0;
}

