long long int min(long long int a, long long int b){
  return a < b ? a : b;
}


long long int calc(const vector<int>& a, int sig,
                   long long int sum = 0,
                   long long int ope = 0,
                   size_t index = 0){
  if(index == a.size()){ return ope; }

  sum += a[index];

  // プラスに押しあげるフェイズの場合
  if(sig == 1 && sum < 1){
    ope += 1 - sum;
    sum = 1;
  }
  // マイナスに引きさげるフェイズの場合
  else if(sig == -1 && sum > -1){
    ope += sum + 1;
    sum = -1;
  }

  return calc(a, sig * (-1), sum, ope, index + 1);
}


