long long solve(int n, int *a, int sgn) {
    long long ans = 0;
    long long sum = a[0];
    if(sgn > 0 && sum <= 0) {
        ans += abs(sum) + 1;
        sum = 1;
    } else if(sgn < 0 && sum >= 0) {
        ans += abs(sum) + 1;
        sum = -1;
    }
    for(int i=1; i<n; ++i) {
        if((sum > 0 && sum + a[i] >= 0) || (sum < 0 && sum + a[i] <= 0)) {
            ans += abs(sum + a[i]) + 1;
            if(sum > 0) sum = -1;
            else sum = 1;
        } else {
            sum += a[i];
        }
    }
    return ans;
}

