			if(s[i - 1] < 0) b++;
			else b--;
			ans++;
		}
		else if(b + s[i] > 0 && s[i - 1] > 0){
			ans += abs(s[i] + b + 1);
			b -= s[i] + b + 1;
		}
		else if(b + s[i] < 0 && s[i - 1] < 0){
			ans += abs(s[i] + b - 1);
			b -= s[i] + b - 1;
		}
		s[i] += b;
	}
	return ans;
}

