using namespace std;

long long work(vector<int> &num, bool flag) {

	long long sum = 0, count = 0;
	for (int i = 0; i < num.size(); ++i) {
		sum += num[i];
		if (i % 2 == flag) {
			if (sum <= 0) {
				count += 1 - sum;
				sum = 1;
			}
		} else {
			if (sum >= 0) {
				count += sum + 1;
				sum = -1;
			}
		}
	}
	return count;

}

