ll solve(int n, ll sum, std::vector<int, std::allocator<int>> &a) {
  ll ans = 0;
  bool is = sum > 0;

  rep(i, 1, n) {
    sum += a[i];
    if (is) {
      if (sum >= 0) {
        ans += sum + 1;
        sum = -1;
      }
    }
    else {
      if (sum <= 0) {
        ans += -sum + 1;
        sum = 1;
      }
    }
    is = !is;
    err(sum, ans);
  }
  return ans;
}

void Calc() {
  int n = in;
  auto a = in.Array(n);

  ll ans = 0;
  if (a[0] == 0) {
    ans = solve(n, -1, a) + 1;
    amin(ans, solve(n, 1, a) + 1);
  }
  else {
    ll sum = a[0];

    ans = solve(n, sum, a);
    if (a[0] > 0) {
      amin(ans, solve(n, -1, a) + a[0] + 1);
    }
    else {
      amin(ans, solve(n, 1, a) - a[0] + 1);
    }
  }
  cout << (ans) << endl;

}

