void calcStep(long long int *ans,
                long long int *sum,
                long long int *preb)
{
    if(0 <= *sum && 0 < *preb)
    {
        *ans += abs(*sum) + 1;
        *sum = -1;
    }
    else if(*sum <= 0 && *preb < 0)
    {
        *ans += abs(*sum) + 1;
        *sum = 1;
    }
}

