ll solve(ll a[],ll N){
  bool plus = !(a[0]>0);
  ll s = a[0];
  ll r = 0;
  for(int i=1;i<N;i++){
    s += a[i];
    if( plus && s<=0 ){
      r += abs(s)+1;
      s = 1;
    }else if( (!plus) && s>=0 ){
      r += abs(s)+1;
      s = -1;
    }
    plus = !plus;
  }
  return r;
}

