		sum[i] = sum[i-1]+x;
	}

	int f=0;
	if(sum[1]>0) f=1;
	else if(sum[1]<0) f=-1;
	ll tmp = 0,a1=1,a2=-1;
	unsigned long long tt=0,t2=0,ans=0;
	for(int i=2; i<=n; i++){
		if(f == 1){
			if(i%2 == 0){
				sum[i] += tmp;
				if(sum[i] >= 0) tmp-=(sum[i]+1),tt+=(sum[i]+1);
			}else{
				sum[i] += tmp;
				if(sum[i] <= 0) tmp+=(1-sum[i]),tt+=(1-sum[i]);
			}
		}else if(f == -1){
			if(i%2 == 0){
				sum[i] += tmp;
				if(sum[i] <= 0) tmp+=(1-sum[i]),tt+=(1-sum[i]);
			}else{
				sum[i] += tmp;
				if(sum[i] >= 0) tmp-=(sum[i]+1),tt+=(sum[i]+1);
			}
		}else{
			ll kk = sum[i];
			if(i%2 == 0){
				sum[i] += a1;
				if(sum[i] >= 0) a1-=(sum[i]+1),tt+=(sum[i]+1);
			}else{
				sum[i] += a1;
				if(sum[i] <= 0) a1+=(1-sum[i]),tt+=(1-sum[i]);
			}
			if(i%2 == 0){
				kk += a2;
				if(kk <= 0) a2+=(1-kk),t2+=(1-kk);
			}else{
				kk += a2;
				if(kk >= 0) a2-=(kk+1),t2+=(kk+1);
			}
		}
	}
	if(f == 0) ans = min(tt,t2);
	else ans = tt;
	cout << ans << endl;

    return 0;
}

