ll solve(long long n, vector<long long> a , bool f){
	ll ans = 0;
	ll add = 0;

	REP(i,n){
		add += a[i];

		bool need = f ^ (i % 2 == 0);
		bool p = add > 0;

		if(add == 0){
			if(need)add++;
			else add--;
			ans++;continue;
		}

		if(p != need){
			if(need){
				ans += abs(add)+1;
				add += abs(add)+1;
			}else{
				ans += abs(add)+1;
				add -= abs(add)+1;
			}
		}
	}

	return ans;
}




