LL solve(bool flg) {
    LL a = 0;
    LL res = 0;

    rep(i, n) {
        a += xs[i];

        if (flg) { // expect: positive
            if (a == 0) {
                a = 1;
                res += 1;
            } else if (a < 0) {
                LL b = 1 - a;
                a = 1;
                res += b;
            }
        } else { // expect: negative
            if (a == 0) {
                a = -1;
                res += 1;
            } else if (a > 0) {
                LL b = a + 1;
                a = -1;
                res += b;
            }
        }

        flg = !flg;
    }

    return res;
}

