ll f(vector<ll> a, int d)
{
    ll pref = 0; ll sol = 0;
    for (int i = 0; i < n; ++i)
    {
        if ((d + i) % 2)
        {
            if (pref + a[i] <= 0)
            {
                ll t = -pref + 1;
                sol += abs(t - a[i]);
                a[i] = t;
            }
        }
        else
        {
            if (pref + a[i] >= 0)
            {
                ll t = -pref - 1;
                sol += abs(t - a[i]);
                a[i] = t;
            }
        }
        pref += a[i];
    }
    return sol;
}

