long long calc(vector<long long> a, long long a0) {
	long long op = abs(a[0] - a0);
	a[0] = a0;

	long long sum = a[0];

	for (int i = 1; i < a.size(); i++) {
		auto prev = sum;
		sum += a[i];

		if ((sum > 0 && prev < 0) || (sum < 0 && prev > 0)) {
			continue;
		}

		op += abs(sum) + 1;

		if (sum > 0) {
			sum = -1;
		} else {
			sum = 1;
		}
	}
	return op;
}

