#define FOR(i, a, b) for (int i = (a), _##i = (b); i < _##i; ++i)
#define REP(i, a) for (int i = 0, _##i = (a); i < _##i; ++i)
#define pb push_back
typedef long long LL;

int n;
LL a[100004];

LL solve(LL sum){

	LL res = 0;	
	FOR(i,2,n){	
		if(sum < 0){
			if( sum + a[i] > 0){			
				sum += a[i];
				continue;		
			}		
			res+= 1 - (sum + a[i]);
			sum = 1;
		}else{
			if( sum + a[i] < 0) {			
				sum += a[i];
				continue;		
			}
			res+= (sum + a[i]) + 1;
			sum = -1;
		}
	}	
	return res;
}

int main(){
