	cin>> n;
	REP(i,n){
		cin >> a[i];
	}
	LL sum = a[0] + a[1];
	if(sum){
		cout << solve(sum) << endl;
	}else{
		cout << min( solve(1), solve(-1) ) + 1 << endl;
	}	
	return 0;
}

