using ll = long long;

ll FirstPositive(vector<ll> A) {
  ll result = 0;

  if (A[0] <= 0) {
    result = -A[0] + 1;
    A[0] = 1;
  }

  ll sum = A[0];
  for (int i = 1; i < A.size(); ++i) {
    ll next_sum = sum + A[i];

    if (i % 2 != 0) {
      if (next_sum >= 0) {
        result += (next_sum + 1);
        A[i] -= (next_sum + 1);
      }
    } else {
      if (next_sum <= 0) {
        result += (-next_sum + 1);
        A[i] += (-next_sum + 1);
      }
    }

    sum += A[i];
  }

  return result;
}

ll FirstNegative(vector<ll> A) {
  ll result = 0;

  if (A[0] >= 0) {
    result = A[0] + 1;
    A[0] = -1;
  }

  ll sum = A[0];
  for (int i = 1; i < A.size(); ++i) {
    ll next_sum = sum + A[i];

    if (i % 2 == 0) {
      if (next_sum >= 0) {
        result += (next_sum + 1);
        A[i] -= (next_sum + 1);
      }
    } else {
      if (next_sum <= 0) {
        result += (-next_sum + 1);
        A[i] += (-next_sum + 1);
      }
    }

    sum += A[i];
  }

  return result;
}

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);

  int N;
  cin >> N;

  vector<ll> A(N);
  for (ll& a : A) {
    cin >> a;
  }

  cout << min(FirstPositive(A), FirstNegative(A)) << '\n';

  return 0;
}

