ll solve(vector<ll> A, int sig)
{
    int N = A.size();
    ll sum = 0;
    ll res = 0;

#ifdef DEBUG
    DUMP(sig);
#endif

    rep(i, N) {
        sum += A[i];

#ifdef DEBUG
        DUMP2(sum, sig);
#endif

        if (sum == 0) {
            sum = sig;
            res++;
        } else {
            if (sig == 1 && sum < 0) {
                res += (1 - sum);
                sum = 1;
            } else if (sig == -1 && sum > 0) {
                res += -(-1 - sum);
                sum = -1;
            }
        }

#ifdef DEBUG
        DUMP(res);
#endif
        sig *= -1;
    }

    return res;
}

int main()
{
    ios::sync_with_stdio(false);

    int N; cin >> N;
    vector<ll> A(N);
    rep(i, N) cin >> A[i];

    ll ans = min(solve(A, 1), solve(A, -1));
    cout << ans << endl;
}

