int main() {
	cin >> n;//代入
	REP(i, n) {
		cin >> a[i];
		if (a[i]) { lar += a[i]; }
		else { sma -= a[i]; }
	}
	REP(i, n - 1) {
		a[i + 1] += a[i];//累積和
	}
	if (sma > lar) {
		if (a[0] < 0) {
		zero = 1;
		}
	}
	else if (a[0] < 0) { zero = 1; }
	REP(i, n) {
		if (i % 2 == zero) {//余りがzero(0or1)のとき
			if (a[i] <= kijun) {//もし、基準以下の時（変えなければならない）
				cou += abs(1 - a[i] + kijun);//基準からa[i]を引いた値＋１をカウントに加える
				kijun -= 1 - a[i] + kijun;//基準は、和がそれぞれhoge増えたらhoge減る
			}
		}
		else {
			if (a[i] >= kijun) {//もし基準より低くなってほしいのに基準以上だったら
				cou += a[i] - kijun + 1;//countに足しておく
				kijun += a[i] - kijun + 1;//和がhogeひかれるはずなら、基準はhoge増える
			}
		}
	}
	cout << cou << endl;//出力
}

