const int N = 100005;

int n;
int a[N];

ll solve() {
    ll sum = a[0], ret = 0; 
    FOR (i, 1, n) {
        if (sum < 0) {
            if (sum + a[i] > 0) sum += a[i];
            else {
                ret += abs((1 - sum) - a[i]);
                sum = 1;
            }
        }
        else {
            if (sum + a[i] < 0) sum += a[i];
            else {
                ret += abs((sum + 1) + a[i]);
                sum = -1;
            }
        }
    }
    return ret;
}

