int main()
{
    int64_t N;
    std::cin >> N;

    int64_t sum = 0;

    std::vector<int64_t> A;
    for (int64_t i = 0; i < N; ++i) {
        int64_t a;
        std::cin >> a;
        A.push_back(a);
    }

    int64_t count = 0;
    sum = A[0];
    for (int64_t i = 1; i < N; ++i) {
        bool isPrevPos = (sum > 0);
        sum += A[i];
        if (isPrevPos) {
            if (sum >= 0) {
                // -1までにする
                count += sum + 1;
                sum = -1;
            }
        }
        else {
            if (sum <= 0) {
                // 1までにする
                count += (-1 * sum) + 1;
                sum = 1;
            }
        }
    }

    std::cout << count << std::endl;

    return 0;
}

