		if (i == 0)
		{
			S[i] = a;
		}
		else {
			S[i] = S[i - 1] + a;
		}
	}

	if (S[0] == 0)
	{
		if (S[1] <= 0) { S[0]++; }
		else { S[0]--; }
		count++;
	}

	ll diff = 0;
	ll diffSum = 0;
	for (int i = 0; i < n - 1; i++)
	{
		S[i + 1] += diffSum;
