		{
			ll diff = abs(S[i + 1]) + 1;

			if (S[i + 1] < 0) {
				S[i + 1] += diff;
				diffSum += diff;
			}
			else {
				S[i + 1] += -diff;
				diffSum += -diff;
			}

			count += diff;
		}
	}
