const int MAX_N = 100000, INDEX = 1;

long long sgn(long long x) {
    if (x == 0) {
        return x;
    }

    return x / abs(x);
}

int n, a[MAX_N + INDEX];

long long getAns(int sgni) {
    long long ps = 0, res = 0;
    for (int i = 1; i <= n; i++) {
        ps += a[i];

        if (sgn(ps) != sgni) {
            switch (sgni) {
                case 1:
                    res -= ps - 1;

                    ps = 1;

                    break;

                case -1:
                    res += ps + 1;

                    ps = -1;

                    break;
            }
        }

        sgni *= -1;
    }

    return res;
}

