template <class T> inline void setmin(T & a, T const & b) { a = min(a, b); }
constexpr ll inf = ll(1e18)+9;
ll solve(vector<ll> const & a, ll initial) {
    int n = a.size();
    ll cnt = abs(initial);
    ll acc = a[0] + initial;
    repeat (i,n-1) {
        ll nacc = acc + a[i+1];
        if (acc > 0 and nacc >= 0) {
            cnt += nacc+1;
            nacc = -1;
        }
        if (acc < 0 and nacc <= 0) {
            cnt += -nacc+1;
            nacc = +1;
        }
        acc = nacc;
    }
    return cnt;
}
