    if (a[0] != 0) setmin(result, solve(a, 0));
    if (a[0] >= 0) setmin(result, solve(a, - (a[0]+1)));
    if (a[0] <= 0) setmin(result, solve(a, + (a[0]+1)));
    printf("%lld\n", result);
    return 0;
}

