const int MAXN = 1e5 + 5;

int N;
LL A[MAXN];

void input()
{
    read(N);
    for (int i = 1; i <= N; ++i) {
        read(A[i]);
    }
}

LL calc()
{
    LL ret = 0, add = 0;
    for (int i = 1; i <= N; ++i) {
        LL cur = A[i] + add;
        if (i & 1) {
            if (cur <= 0) {
                add += 1 - cur;
                ret += 1 - cur;
            }
        } else {
            if (cur >= 0) {
                add -= cur + 1;
                ret += cur + 1;
            }
        }
    }
    return ret;
}

void solve()
{
    for (int i = 1; i <= N; ++i) {
        A[i] += A[i - 1];
    }
    LL ans = calc();
    for (int i = 1; i <= N; ++i) {
        A[i] = -A[i];
    }
    chkmin(ans, calc());
    printf("%lld\n", ans);
}

