class CumulativeSum{
public:
  vector<int> sum;
  CumulativeSum(){}
  CumulativeSum(vector<int> A){
    int n = A.size();
    sum.resize(n+1,0);
    for(int i=1;i<=n;i++) sum[i] += sum[i-1] + A[i-1];
  }
  int get(int l,int r){assert(l>=0 && r<=(int)sum.size());return sum[r] - sum[l];} //[l,r)
};

int calc(vector<int> A,int flag){
  int n = A.size();
  int res = 0;
  int ofset = 0;
  CumulativeSum Sum(A);

  for(int i=0;i<n;i++){
    int a = Sum.get(0,i+1) + ofset;
    if(i%2 == flag && a >= 0){
      res += abs(a) + 1;
      ofset += -a - 1;
    }
    if(i%2 == !flag && a <= 0){
      res += abs(a) + 1;
      ofset += -a + 1;
    }
  }
  return res;
}

