long long solve(long long s,int n){
    long long sum = 0, res = 0;
    for(int i = 1; i <= n; i++){
        s *= -1;
        sum += a[i];
        if(sum*s<=0){
            res += abs(s-sum);
            sum = s;
        }
    }
    return res;
}

