int n;
LL ans = 1e18, sum;
LL s[AC];

inline int read()
{
	int x = 0;char c = getchar();bool z = false;
	while(c > '9' || c < '0') 
	{
		if(c == '-') z = true;
		c = getchar();
	}
	while(c >= '0' && c <= '9') x = x * 10 + c - '0', c = getchar();
	if(!z) return x;
	else return -x;
}

void pre()
{
	n = read();
	for(R i = 1; i <= n; i ++) s[i] = read();
}

void cal(LL sum, LL rnt)
{
	LL x;
	for(R i = 2; i <= n; i ++)
	{
		x = s[i];
		if(sum > 0)
		{
			if(x + sum < 0) {sum += x; continue;}	
			rnt += x + sum + 1;
			x = - sum - 1;
			sum += x;
		}
		else 
		{
			if(x + sum > 0) {sum += x; continue;}
			rnt += - sum - x + 1;
			x = - sum + 1;
			sum += x;
		}
	}
	ans = min(ans, rnt);
}

void work()
{
	if(s[1] >= 0) 
	{
		if(s[1] == 0) cal(1, 1), cal(-1, 1);	
		else cal(s[1], 0), cal(-1, s[1] + 1);
	}
	else cal(s[1], 0), cal(1, -s[1] + 1);
	printf("%lld\n", ans);
}

