#include <bits/stdc++.h>

using namespace std;

const int maxn = 100100;

typedef long long ll;

int n, num[maxn];

struct BIT {
	#define lowbit(x) (x & (-x))
	ll tr[maxn << 1];
	void clear() {
		memset(tr, 0, sizeof(tr));
	}
	void add(int x, ll num) {
		for(; x < maxn; x += lowbit(x)) tr[x] += num;
	}
	int query(int x) {
		int ret = 0;
		for(; x; x -= lowbit(x)) ret += tr[x];
		return ret;
	}
}bit;

ll work(int flag) {
	bit.clear(); ll ret = 0;
	for(int i = 1; i <= n; i++) bit.add(i, num[i]);
	for(int i = 1; i <= n; i++) {
		if(flag == 0) {
			int u = bit.query(i);
			if(u <= 0) ret += -u + 1, bit.add(i, -u + 1);
		} else {
			int u = bit.query(i);
			if(u >= 0) ret += u + 1, bit.add(i, -u - 1);
		}

		flag ^= 1;
	}
	return ret;
}

int main() {
	scanf("%d", &n);
	for(int i = 1; i <= n; i++) scanf("%d", &num[i]);
	for(int i = 1; i <= n; i++) bit.add(i, num[i]);

	ll ans = min(work(0), work(1));
	printf("%lld\n", ans);

	return 0;
}

