	cur += (llabs(cur)+1LL);
      }
    } else { // -
      if( cur == 0 ) {
	--cur;
	++ret;
      } else if( cur > 0LL ) {
	ret += (llabs(cur)+1LL);
	cur -= (llabs(cur)+1LL);
      }
    }
    state = !state;
  }
  return ret;
}

