inline int read()
{
	int x = 0;char c = getchar();bool z = false;
	while(c > '9' || c < '0') 
	{
		if(c == '-') z = true;
		c = getchar();
	}
	while(c >= '0' && c <= '9') x = x * 10 + c - '0', c = getchar();
	if(!z) return x;
	else return -x;
}

void pre()
{
	n = read();
	for(R i = 1; i <= n; i ++) s[i] = read();
}

void cal(int sum, int rnt)
{
	int x;
	for(R i = 2; i <= n; i ++)
	{
		x = s[i];
		if(sum > 0)
		{
			if(x + sum < 0) {sum += x; continue;}	
			rnt += x + sum + 1;
			x = - sum - 1;
			sum += x;
		}
		else 
		{
			if(x + sum > 0) {sum += x; continue;}
			rnt += - sum - x + 1;
			x = - sum + 1;
			sum += x;
		}
	}
	ans = min(ans, rnt);
}

void work()
{
	if(s[1] >= 0) 
	{
		if(s[1] == 0) cal(1, 1), cal(-1, 1);	
		else cal(s[1], 0), cal(-1, s[1] + 1);
	}
	else cal(s[1], 0), cal(1, -s[1] + 1);
	printf("%d\n", ans);
}

int main()
{
	//freopen("in.in", "r", stdin);
	pre();
	work();
	//fclose(stdin);
	return 0;
}

#include <bits/stdc++.h>

using namespace std;
typedef long long li;

li sgn(li x) {
    if (x > 0) {
        return 1;
    } else if (x < 0) {
        return -1;
    } else {
        return 0;
    }
}

li solve(vector<li> xs) {
    li acc = 0, ans = 0;
    for (auto x : xs) {
        if (acc == 0) {
            acc += x;
        } else {
            li nacc = acc + x;
            if (sgn(acc) * sgn(nacc) >= 0) {
                const li delta = abs(-sgn(acc) - nacc);
                acc = -sgn(acc);
                ans += delta;
            } else {
                acc = nacc;
            }
        }
    }
    return ans;
}

int main() {
    li n;
    cin >> n;

    vector<li> xs(n);
    for (int i = 0; i < n; ++i) {
        cin >> xs[i];
    }

    li ans = 1e18;
    li head = xs[0];
    if (head != 0) {
        ans = solve(xs);
    }
    if (head <= 0) {
        xs[0] = 1;
        ans = min(ans, solve(xs) + abs(1 - head));
    }
    if (head >= 0){
        xs[0] = -1;
        ans = min(ans, solve(xs) + abs(-1 - head));
    }

    cout << ans << endl;
    return 0;
}

