int main() {
	long long n;
	std::cin >> n;

	long long sum1 = 0, sum2 = 0;
	long long ans1 = 0, ans2 = 0;

	long long first;
	std::cin >> first;
	if (first == 0) {
		sum1 = 1;
		sum2 = -1;
		ans1 = ans2 = 1;
	}
	else if (first > 0) {
		sum1 = first;
		sum2 = -1;
		ans2 = std::abs(first + 1);
	}
	else {
		sum1 = 1;
		sum2 = first;
		ans1 = std::abs(1 - first);
	}

	for (int i = 1; i < n; ++i) {
		long long a;
		std::cin >> a;

		if (sum1 < 0) {
			ans1 += std::max(0ll, 1 - (sum1 + a));
			sum1 = (sum1 + a < 1 ? 1 : sum1 + a);
		}
		else {
			ans1 += std::max(0ll , sum1 + a + 1);
			sum1 = (sum1 + a > -1 ? -1 : sum1 + a);
		}

		if (sum2 < 0) {
			ans2 += std::max(0ll, 1 - (sum2 + a));
			sum2 = (sum2 + a < 1 ? 1 : sum2 + a);
		}
		else {
			ans2 += std::max(0ll, sum2 + a + 1);
			sum2 = (sum2 + a > -1 ? -1 : sum2 + a);
		}
	}

	std::cout << std::min(ans1, ans2) << std::endl;
}

