using ll = long long;

ll calc(const vector<int> &nums, ll x) {
  ll ret = abs
    (x - nums.front());
  ll cur = x;
  bool plus = x < 0;
  rep2(i,1,sz(nums)) {
    cur += nums[i];
    if (plus) {
      if (cur <= 0) {
        ret += 1 - cur;
        cur = 1;
      }
    } else {
      if (cur >= 0) {
        ret += cur + 1;
        cur = -1;
      }
    }
    plus = !plus;
  }
  return ret;
}

ll calc2(ll lp, ll up, const vector<int> &nums) {
  while (up - lp >= 3) {
    ll p1 = lp + (up - lp) / 3;
    ll p2 = lp + (up - lp) / 3 * 2;
    ll p1v = calc(nums, p1);
    ll p2v = calc(nums, p2);
    if (p1v < p2v) {
      up = p2;
    } else {
      lp = p1;
    }
  }
  vector<ll> vs;
  for (ll i = lp; i <= up; i++) {
    vs.pb(calc(nums,i));
  }
  return *min_element(ALL(vs));
}

