int n;
int A[100001];
llong S[100001];

llong solve() {
    llong ret = 0;
    for (int i = 1, sn = 1; i <= n; ++i, sn = -sn) {
        S[i] += S[i - 1];
        if (sn < 0 && 0 <= S[i]) {
            ret += S[i] + 1;
            S[i] = -1;
        }
        else if (sn > 0 && S[i] <= 0) {
            ret -= S[i] - 1;
            S[i] = 1;
        }
    }
    return ret;
}

int main() {
    ios_base::sync_with_stdio(0); cin.tie(0);
    cin >> n;
    for (int i = 1; i <= n; ++i) {
        cin >> A[i];
        S[i] = A[i];
    }
    llong ans = solve();
    for (int i = 1; i <= n; ++i) {
        S[i] = -A[i];
    }
    ans = min(ans, solve());
    printf("%lld\n", ans);
    return 0;
}

