using namespace std;

int x[100100];
int N;

long long dis(long long a, long long b){
	if(a > b) return a - b;
	else return b - a;
}

long long calc(){
	long long cur = x[0];
	long long res = 0;
	for(int i = 1; i < N; ++i){
		long long tmp = x[i];
		if(cur > 0){
			if(tmp >= -cur){
				res += dis(-cur - 1, tmp);
				tmp = -cur - 1;
			}
		}else{
			if(tmp <= -cur){
				res += dis(-cur + 1, tmp);
				tmp = -cur + 1;
			}
		}
		cur += tmp;
	}
	return res;
}

long long solve(){
	if(x[0] != 0){
		long long tmp = calc();
		long long tmp1;
		if(x[0] > 0){
			tmp1 = dis(x[0], -1);
			x[0] = -1;
		}else{
			tmp1 = dis(x[0], 1);
			x[0] = 1;
		}
		long long tmp2 = tmp1 + calc();
		return min(tmp, tmp2);
	}
	x[0] = 1;
	long long tmp = calc();
	x[0] = -1;
	long long tmp2 = calc();
	return min(tmp, tmp2);
}

