constexpr int sign( const int a )
{
	return ( 0 < a ) - ( a < 0 );
}


LL solve( const VT< LL > &A )
{
	const int N = SZ( A );

	LL sum = A[0], res = 0;
	REP( i, 1, N )
	{
		const LL a = A[i];
		LL t = -sum - sign( sum );
		t = sign( a ) == sign( t ) && abs( t ) < abs( a ) ? a : t;
		res += abs( a - t );
		sum += t;
	}

	return res;
}

int main()
{
