// CumulativeSum {{{
class CumulativeSum {
    vector<intmax_t> cum;

public:
    CumulativeSum() : cum(1) {}
    CumulativeSum(const size_t sz) : cum(sz + 1) {}

    inline void build() {
        for (size_t i = 1; i < cum.size(); ++i) {
            cum[i] += cum[i - 1];
        }
    }

    // Sum of closed interval [0, right)
    inline intmax_t sum(size_t right) const {
        return cum[right];
    }

    // Sum of closed interval [left, right)
    inline intmax_t sum(size_t left, size_t right) const {
        return sum(right) - sum(left);
    }

    inline intmax_t operator[](size_t i) const {
        return cum[i + 1];
    }

    inline intmax_t& operator[](size_t i) {
        return cum[i + 1];
    }

    inline void assign(const size_t sz) {
        cum.assign(sz + 1, 0);
    }

    inline size_t size() const noexcept {
        return cum.size() - 1;
    }

    inline const auto& data() const noexcept {
        return cum;
    }
};
