    cin.tie(nullptr);

    var(size_t, N);

    vector<intmax_t> a(N);
    input(a);

    CumulativeSum cum(N);
    rep(i, N) {
        cum[i] = a[i];
    }

    cum.build();

    dump(cum.data());

    intmax_t add = 0, res = 0;
    reps(i, 1, N - 1) {
        cum[i] += add;
        if (cum.sum(i + 1) == 0) {
            if (cum.sum(i) < 0) {
                cum[i] = 1;
                add += 1;
            } else {
                cum[i] = -1;
                add += -1;
            }
            res += 1;
        }
        if (cum.sum(i + 1) < 0 && cum.sum(i) < 0) {
            add += 1_jd - cum[i];
            res += diff(1_jd, cum[i]);
            cum[i] = 1;
        } else if (cum.sum(i + 1) >= 0 && cum.sum(i) >= 0) {
            add += -1_jd - cum[i];
            res += diff(-1_jd, cum[i]);
            cum[i] = -1;
        }
    }

    dump(cum.data());

    print(res);

    return 0;
}

