using namespace std;

int sign(long sum)
{
  if (sum == 0) return sum;
  return sum > 0 ? 1 : -1;
}

long solve(const vector<int>& a, int init)
{
  int _s = init;
  long op = 0;
  long sum = 0;
  for(int i = 0; i < a.size(); ++i) {
    sum += a[i];
    int s = sign(sum);
    // cerr << "a[" << i << "]: " << a[i] << " " << _sum << "|" << _s << " " << sum << "|" << s << endl;
    if (_s * s >= 0) {
      if (_s > 0) {
        op += sum + 1;
        sum = -1;
      } else {
        op += (1 - sum);
        sum = 1;
      }
    }
    _s *= -1;
  }
  return op;
}

int main()
{
  int n;
  cin >> n;
  vector<int> a(n);
  for (int i = 0; i < n; ++i) cin >> a[i];
  cout << min(solve(a, 1), solve(a, -1)) << endl;
  return 0;
}

