  for (int i = 1; i <= n; ++i) {
    b[i] += carry;
    if (!(i & 1) and b[i] >= 0) {
      oddpos += 1 + b[i];
      carry -= 1 + b[i];
    }
    if (i & 1 and b[i] <= 0) {
      oddpos += 1 - b[i];
      carry += 1 - b[i];
    }
  }
  printf("%lld\n", min(oddneg, oddpos));
  return 0;
}

