typedef long long ll;

int N;
ll a[100010];
ll ans;
ll solve(ll prev,ll sum,ll p){
	ll res = p;
	for(int i=1;i<N;i++){
		//cout<<sum<<endl;
		sum += a[i];
		if(sum == 0){
			res ++;
			sum = -prev/abs(prev);
		}
		else if(sum * prev > 0){
			res += abs(sum)+1;
			sum = -prev/abs(prev);
		}
		prev = sum;
	}
	return res;
}
int main(){
	cin >> N;
	for(int i=0;i<N;i++){
		cin >> a[i];
	}
	ll r1,r2;
	if(a[0] == 0){
		r1 = solve(1,1,1);
		r2 = solve(-1,-1,1);
	}
	else{
		r1 = solve(a[0],a[0],0);
		r2 = solve(-a[0]/a[0],-a[0]/a[0],abs(a[0])+1);
	}
	ans = min(r1,r2);
	//cout << r1 << " "<<r2<<endl;
	cout<<ans<<endl;
	return 0;
}

