using namespace std;

int work(vector<int> &num, int count, int sum) {
	for (int i = 1; i < num.size(); ++i) {
		int newSum = sum + num[i];
		if (sum > 0) {
			if (newSum >= 0) {
				count += newSum + 1;
				sum = -1;
			} else {
				sum = newSum;
			}
		} else {
			if (newSum <= 0) {
				count += -newSum + 1;
				sum = 1;
			} else {
				sum = newSum;
			}
		}
	}
	return count;
}

int main(void) {

	int n; cin >> n;
