	}

	for (int i = 0; i < n; ++i) {
		cin >> num[i];
	}

	int result;
	if (num[0] == 0) {
		result = min(work(num, 1, 1), work(num, 1, -1));
	} else {
		result = work(num, 0, num[0]);
	}

	cout << result << endl;;
	return 0;
}

