const int dx[8] = {-1, 1, 0, 0, -1, -1, 1, 1}, dy[8] = {0, 0, -1, 1, -1, 1, -1, 1};

int N;
ll A[100100], B[100100];

ll f(){
    int t1 = 0, t2 = 0;

    for(int i=1;i<N;++i){
        B[i] += t1 - t2;

        if(B[i-1] > 0 && B[i] >= 0){
            t2 += B[i] + 1;
            B[i] = -1;
        }else if(B[i-1] < 0 && B[i] <= 0){
            t1 += -B[i] + 1;
            B[i] = 1;
        }
    }

    return t1 + t2;
}

int main(){
    std::cin.tie(nullptr);
    std::ios::sync_with_stdio(false);

    std::cin >> N;

    for(int i=0;i<N;++i){
        std::cin >> A[i];

        if(i > 0){A[i] += A[i-1];}
    }

    ll res;

    if(A[0] == 0){
        copy(A, A+N, B);
        for(int i=0;i<N;++i){
            B[i] += 1;
        }
        res = f() + 1;

        copy(A, A+N, B);
        for(int i=0;i<N;++i){
            B[i] -= 1;
        }
        res = min(res, f() + 1);
    }else{
        copy(A, A+N, B);
        res = f();
    }

    std::cout << res << std::endl;
}

