int n;
int calc(vi a,int x) {
    int ret=x;
    int sum=a[0];
    REPF(i,1,n) {
        if(sum>0) {
            if(a[i]>=-sum) {
                ret+=abs(a[i]-(-sum-1));
                a[i]=-sum-1;
            }
        }
        else {
            if(a[i]<=-sum) {
                ret+=abs(a[i]-(-sum+1));
                a[i]=-sum+1;
            }
        }
        sum+=a[i];
        if(sum==0) {
            if(a[i]<0) a[i]--;
            else a[i]++;
            ret++;
        }
    }
    return ret;
}
