constexpr int div_ru(int a, int b)
{
    return (a - b + 1) / b;
}
constexpr int sign(int a)
{
    return (a > 0) - (a < 0);
}
int solve(vector<int> &v)
{
    if (v[0] == 0)
        return INF;
    const int n = v.size();
    int cnt = 0;
    vector<int> cv(n + 1);
    cv[1] = v[0];
    for (int i = 1; i < n; i++)
    {
        cv[i + 1] = v[i] + cv[i];
        if (cv[i + 1] != 0 && (cv[i + 1] * cv[i]) < 0)
        {
            ;
        }
        else
        {
            const int new_aa = -1 * sign(cv[i]);
            // now_sign = cv[i+1]+change
            const int shift = new_aa - cv[i + 1];
            v[i] += shift;
            cv[i + 1] = v[i] + cv[i];
            cnt += abs(shift);
        }
    }
    return cnt;
}

int main()
{
    cin.tie(0);
    ios::sync_with_stdio(false);

    int n;
    cin >> n;
    vector<int> a(n);
    for (auto &x : a)
        cin >> x;

    int ans;

    if (a[0] != 0)
    {
        const int one = solve(a);
        const int new_a0 = -1 * sign(a[0]);
        const int shift = new_a0 - a[0];
        a[0] += shift;
        const int the_other = solve(a) + abs(shift);
        ans = min(one, the_other);
    }
    else
    {
        a[0] = 1;
        const int plus_first = solve(a) + 1;
        a[0] = -1;
        const int minus_first = solve(a) + 1;
        ans = min(plus_first, minus_first);
    }
    cout << ans << endl;
    return 0;
}
