ll solve(ll ans, ll sum){
	bool pos;

	if(a[0] > 0){
		pos = true;
	}else{
		pos = false;
	}

	for(int i=1; i<n; i++){
		if(pos && sum + a[i] >= 0){
			ans += sum + a[i] + 1;
			pos = false;
			sum = -1;
		}else if(!pos && sum + a[i] <= 0){
			ans += -(sum + a[i]) + 1;
			pos = true;
			sum = 1;
		}else{
			sum += a[i];
			pos = !pos;
		}
	}

	return ans;
}

