long long cum[N];
long long go(bool positive) {
	long long sum = 0, cost = 0;
	for (int i = 1; i <= n; ++i) {
		if (positive && cum[i] + sum <= 0) {
			cost += abs(cum[i] + sum) + 1;
			sum += abs(cum[i] + sum) + 1;
		} else if (!positive && cum[i] + sum >= 0) {
			cost += cum[i] + sum + 1;
			sum -= cum[i] + sum + 1;
		}
		positive = !positive;
	}
	return cost;
}
