int n, a[100000];

int solve(bool flag, int cnt, int now) {
    FOR(i, 1, n) {
        if(flag) {
            if(a[i] + now >= 0 ) {
                cnt += a[i] + now + 1;
                now -= a[i] + now + 1;
            }
            flag = false;
        }
        else {
            if(a[i] + now <= 0) {
                cnt += abs(a[i] + now) + 1;
                now += abs(a[i] + now) + 1;
            }
            flag = true;
        }
    }
    return cnt;
}

