        else now += -a[0] - 1;
        cnt = abs(a[0]) + 1;
        bool flag = (a[0] < 0) ? true : false;
        res = solve(flag, cnt, now);
        cnt = now = 0;
        flag = (a[0] > 0) ? true : false;
        chmin(res, solve(flag, cnt, now));
    }
    else {
        cnt = now = 1;
        bool flag = true;
        res = solve(flag, cnt, now);
        now = -1;
        flag = false;
        chmin(res, solve(flag, cnt, now));
    }
    cout << res << endl;
    return 0;
}

