        acc += a[i];
        ll acct = acc;
        if (sign) {
            chmax(acct, 1);
        } else {
            chmin(acct, -1);
        }
        ans += abs(acc - acct);
        acc = acct;
        sign = !sign;
    }
    return ans;
}

