					sub_count += t[i] + 1;
					t[i] = -1;
				}
				sub_flag = false;
			}else{
				if(t[i] <= 0){
					sub_count += -t[i] + 1;
					t[i] = 1;
				}
				sub_flag = true;
			}
		}else{ 
			s[i] = a[i];
			t[i] = a[i];
			flag = true;
			sub_flag = true;
			if(flag){
				if(s[i] >= 0){
					count += s[i] + 1;
				}
			}
			if(sub_flag){
				if(t[i] <= 0){
					sub_count += -t[i] + 1;
				}
			}
		}
	}
	cout << min(count, sub_count) << endl;
	//cout << count << " " << sub_count << endl;
	return 0;
}

