namespace task{

const ll inf=1e18;
const int N=1e5+5;
int a[N];
ll s[N];
int n;
ll ans=inf;

ll calc(int val)
{
    fill(s+1,s+1+n,0);
    a[1]=s[1]=val;
    s[0]=(a[1] < 0 ? 1 : -1);
    ll ret=0;
    for(int i=2;i<=n;++i)
    {
        s[i]=s[i-1] + 1ll*a[i];
        if(s[i] * s[i-1] >= 0)
        {
            if(s[i] < 0)ret+=Abs(s[i])+1,s[i]=1;
            else if(s[i] > 0)ret+=s[i] + 1,s[i]=-1;
            else
            {
                ret++;
                if(s[i-1] < 0)s[i]=1;
                else s[i]=-1;
            }
        }
    }
    return ret;
}

void solve()
{
    scanf("%d",&n);
    for(int i=1;i<=n;++i)scanf("%d",a+i);
    if(!a[1])minimize(ans,min(calc(-1) + 1,calc(1)+1));
    else minimize(ans,calc(a[1]));
    printf("%lld\n",ans);
}}

int main(void)
{
    task::solve();
}

