int main(){
    ll n;
    cin >> n;
    vector<ll> a;
    ll sum[n], sum2[n];
    for(ll i = 0; i < n; i++){
        ll b; cin >> b;
        a.push_back(b);
        if(i==0) sum[i] = b;
        else sum[i] = sum[i-1]+b;
    }
    for(ll i = 0; i < n; i++)
        sum2[i] = sum[i];
    ll ans = 0, total = 0, count = 0;
    if(sum[0]>0) total = -sum[0]-1;
    ans = abs(total);
    sum[0]+=total;
    for(ll i = 1; i < n; i++){
        ll now = sum[i]+total;
        if(now*sum[i-1]>0){
           count = abs(now)+1;
            ans+=count;
            if(now<0) total+=count;
            else if(now>0) total-=count;
        }
        else if(now*sum[i-1]==0){
            ans++;
            if(sum[i-1]<0) total++;
            else if(sum[i-1]>0) total--;
        }
        sum[i]+=total;
    }
    ll check = ans;
    total = 0; ans = 0;
    if(sum2[0]<0) total = abs(sum2[0])+1;
    sum2[0]+=total;
    for(ll i = 1; i < n; i++){
        ll now = sum2[i]+total;
        if(now*sum2[i-1]>0){
           count = abs(now)+1;
            ans+=count;
            if(now<0) total+=count;
            else if(now>0) total-=count;
        }
        else if(now*sum2[i-1]==0){
            ans++;
            if(sum2[i-1]<0) total++;
            else if(sum2[i-1]>0) total--;
        }
        sum2[i]+=total;
    }
    check = min(check, ans);
    cout << check << endl;
    return 0;
}


