bool same_sign(intmax_t m, intmax_t n) {
  assert(m != 0 && n != 0);
  return (m < 0) == (n < 0);
}

intmax_t f(const std::vector<int>& a) {
  size_t n = a.size();
  intmax_t res = 0;
  intmax_t sum = a[0];
  for (size_t i = 1; i < n; ++i) {
    if (sum+a[i] == 0) {
      sum /= -abs(sum);
      ++res;
    } else if (!same_sign(sum, sum+a[i])) {
      sum += a[i];
    } else {
      res += abs(sum+a[i])+1;
      sum /= -abs(sum);
    }
  }
  return res;
}

int main() {
  size_t n;
  scanf("%zu", &n);

  std::vector<int> a(n);
  for (auto& ai: a) scanf("%d", &ai);

  intmax_t res = f(a);
  for (auto& ai: a) ai = -ai;
  res = std::min(res, f(a));
  printf("%jd\n", res);
}

