int main(){
    int n; cin >> n;
    ll a[n];
    inarray(a,n);
    ll sum_even = 0, sum_odd = 0, ans_even = 0, ans_odd = 0;
    for(int i = 0; i < n; i++){
        sum_even += a[i]; /* 偶数番目を正にする */
        sum_odd += a[i]; /* 奇数番目を正にする */
        if(i%2 == 0){
            /* 偶数番目 */
            if(sum_even <= 0){
                /* + */
                ans_even += abs(1-sum_even);
                sum_even = 1;
            }
            if(sum_odd >= 0){
                /* - */
                ans_odd += abs(-1-sum_odd);
                sum_odd = -1;
            }
        }else{
            /* 奇数番目 */
            if(sum_even >= 0){
                /* - */
                ans_even += abs(-1-sum_even);
                sum_even = -1;
            }
            if(sum_odd <= 0){
                /* + */
                ans_odd += abs(1-sum_odd);
                sum_odd = 1;
            }
        }
    }
    cout << min(ans_even, ans_odd) << endl;
    return 0;
}

