#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const int N = 1e5 + 10;
ll ans=0x3f3f3f3f,tmp=0;
int a[N],sum[N];
int n;

void get(int x) {
	tmp=0;
	memset(sum,0,sizeof(sum));
	if(a[0]==0)tmp++,sum[0]=x;
	else{
		if(x*a[0]<0){
			if(x==1){
				sum[0]=1;
				tmp = tmp + x - a[0];
			}else{
				sum[0]=-1;
				tmp = tmp + a[0] - x;
			}
		}else sum[0] = a[0];
	}

	for(int i=1;i<n;i++){
		if(sum[i-1]>0){
			if(sum[i-1]+a[i]<0){
				sum[i]=sum[i-1]+a[i];
				continue;
			}else{
				sum[i]=-1;
				tmp=tmp+sum[i-1]+a[i]+1;
				continue;
			}
		}else{
			if(sum[i-1]+a[i]>0){
				sum[i]=sum[i-1]+a[i];
				continue;
			}else{
				sum[i]=1;
				tmp=tmp+1-sum[i-1]-a[i];
				continue;
			}
		}
	}

	ans = min(ans,tmp);
}
int main(int argc, char** argv) {
	cin>>n;
	for(int i=0;i<n;i++)scanf("%d",&a[i]);
	get(1);
	get(-1);
	cout<<ans<<endl;
	return 0;
}

