typedef long long ll;

ll solve(vector<ll> a, bool run) {
    ll cur = 0;
    ll res = 0;

    rep(i, 0, a.size()) {
        a[i] += cur;

        bool plus = (i % 2 == run);
        //cout << i << ": " << a[i] << ", " << plus << endl;
        if (plus && a[i] <= 0) {
            res += llabs(1 - a[i]);
            cur += 1 - a[i];
            a[i] = 1;
        }
        if ((!plus) && (a[i] >= 0)) {
            res += llabs(a[i] + 1);
            cur -= a[i] + 1;
            a[i] = -1;
        }
    }
    return res;
}

