    pref[0] = v[0] ;
    if(v[0] == 0 ){
        v[0] = -1 ;
        ans = ans + 1 ;
    }
    else if(v[0] > 0){
        ans = ans + v[0] + 1 ;
        v[0] = -1 ;
    }
    pref[0] = v[0] ;
    forn(i , 1 , n -1 ){
       ll sum = pref[i-1] + v[i] ;
       if(i % 2 == 1){
          if(sum <= 0){
            ll changes = abs(sum) + 1 ;
            ans = ans + changes ;
            v[i] = v[i] + changes ;
          }
          pref[i] = pref[i-1] + v[i] ;
       }
       else if(i % 2 == 0){
          if(sum >= 0){
            ll changes = sum + 1;
            ans = ans + changes ;
            v[i] = v[i ] - changes ;
          }
          pref[i] = pref[i-1] +  v[i] ;
       }
    }
    return ans ;
}
