int64 Run(const int a[],int n) {
	static int64 pref[MAXN];
	pref[1]=a[1];
	int64 res=0;int sgn=a[1]>0?1:-1;
	for(int i=2;i<=n;++i) {
		pref[i]=pref[i-1]+a[i];
		if(sgn*pref[i]>=0) {
			if(sgn==-1) {
				res+=abs(1-pref[i]);
				pref[i]=1;
			} else {
				res+=abs(pref[i]-(-1));
				pref[i]=-1;
			}
		}
		sgn*=-1;
	}
	return res;
}
