const int MaxN = 100005;

int n, cost0, cost1;
int v[MaxN], pSum[MaxN];

int CalcCost(int currV[]) {
  int ans = 0;
  memset(pSum, 0, sizeof pSum);
  pSum[1] = currV[1];
  for (int i = 2; i <= n; ++i) {
    pSum[i] = pSum[i - 1] + currV[i];

    if (pSum[i - 1] > 0 and pSum[i] >= 0) {
      pSum[i] = -1;
      ans += currV[i] - (- 1 - pSum[i - 1]);
      currV[i] = - 1 - pSum[i - 1];
//      --currV[i];
//      pSum[i] = pSum[i - 1] + currV[i];
//      ++ans;
    }

    if (pSum[i - 1] < 0 and pSum[i] <= 0) {
      pSum[i] = 1;
      ans += -(currV[i] - (1 - pSum[i - 1]));
      currV[i] = 1 - pSum[i - 1];
//      ++currV[i];
//      pSum[i] = pSum[i - 1] + currV[i];
//      ++ans;
    }
  }

  return ans;
}

int main() {
  cin >> n;
  for (int i = 1; i <= n; ++i) {
    cin >> v[i];
  }

  if (v[1] < 0) {
    cost1 = CalcCost(v);
    while (v[1] <= 0) {
      ++v[1];
      ++cost0;
    }

    cost0 += CalcCost(v);
  }
  else if (v[1] > 0) {
    cost0 = CalcCost(v);
    while (v[1] >= 0) {
      --v[1];
      ++cost1;
    }
    cost1 += CalcCost(v);
  }
  else {
    v[1] = 1;
    cost0 = 1 + CalcCost(v);
    v[1] = -1;
    cost1 = 1 + CalcCost(v);
  }

  cout << min(cost0, cost1) << '\n';
  return 0;
}

