using namespace std;
typedef long long li;

li sgn(li x) {
    if (x > 0) {
        return 1;
    } else if (x < 0) {
        return -1;
    } else {
        return 0;
    }
}

li solve(vector<li> xs) {
    li acc = 0, ans = 0;
    for (auto x : xs) {
        if (acc == 0) {
            acc += x;
        } else {
            li nacc = acc + x;
            if (sgn(acc) * sgn(nacc) >= 0) {
                const li delta = abs(-sgn(acc) - nacc);
                acc = -sgn(acc);
                ans += delta;
            } else {
                acc = nacc;
            }
        }
    }
    return ans;
}

int main() {
    li n;
    cin >> n;

    vector<li> xs(n);
    for (int i = 0; i < n; ++i) {
        cin >> xs[i];
    }

    li ans;
    if (xs[0] == 0) {
        xs[0] = 1;
        ans = solve(xs) + 1;
        xs[0] = -1;
        ans = min(ans, solve(xs) + 1);
    } else {
        ans = solve(xs);
    }

    cout << ans << endl;
    return 0;
}

