}

ll calc() {
    ll curr = a[0], res = 0ll;
    int flag = 1;
    if(curr < 0ll) 
       flag = 0;
    for(int i=1; i<n; ++i) {
       ll x = a[i];
       if(curr+x == 0) {
           ++res;
           if(flag) curr = -1;
           else curr = 1;
       }
       else if(flag != sign(curr + x)) { 
           res += abs(curr + x) + 1;
         //  cout << "i: " << i << " curr: " << curr << " abs(curr+x)+1: " << abs(curr + x)+1 << " res: " << res << "\n";
           if(flag) { 
              // res += (x <= 0) ? curr + x + 1: i;
               curr = -1;
           }
            else {
             //   res += (x <= 0) ? : ;
                curr = 1;
            }
       }
       else
           curr += x;
       flag ^= 1;
    }
    return res;
}

int main() {
   ios_base::sync_with_stdio(false);
   cin.tie(NULL);
   cin >> n;
   for(int i=0; i<n; ++i) 
       cin >> a[i];
   ll res;
   if(a[0] != 0) {
       res = calc();
       if(a[0] > 0) {
           ll p = abs(a[0]) + 1;
           a[0] = -1;
           res = min(res, p + calc());
       } else {
           ll p = abs(a[0]) + 1;
           a[0] = 1;
           res = min(res, p + calc());
       }
   } else {
       a[0] = -1;
       res = calc() + 1;
       a[0] = 1;
       res = min(res, calc() + 1);
   }
   cout << res << "\n";
   return 0;
}

