	ios::sync_with_stdio(false);

	int N;
	cin >> N;
	vector<ll> a(N);
	cin >> a;

	ll ans = INT64_MAX;

	ll step, sum;
	// 最初マイナス
	step = 0; sum = 0;
	if (a[0] > 0) {
		step = a[0] + 1;
		sum = -1;
	}
	else {
		sum = a[0];
	}
	for (int i = 1; i < N; i++) {
		ll val = a[i];
		if (i & 1) {
			// 和は正
			if (sum + val <= 0) {
				ll x = 1 - (sum + val);
				val += x;
				step += x;
			}
			sum += val;
		}
		else {
			// 和は負
			if (sum + val >= 0) {
				ll x = 1 + (sum + val);
				val -= x;
				step += x;
			}
			sum += val;
		}
	}
	ans = min(ans, step);

	// 最初プラス
	step = 0; sum = 0;
	if (a[0] < 0) {
		step += 1 - a[0];
		sum = 1;
	}
	else {
		sum = a[0];
	}
	for (int i = 1; i < N; i++) {
		ll val = a[i];
		if (i & 1) {
			if (sum + val >= 0) {
				ll x = 1 + (sum + val);
				val -= x;
				step += x;
			}
			sum += val;
		}
		else {
			if (sum + val <= 0) {
				ll x = 1 - (sum + val);
				val += x;
				step += x;
			}
			sum += val;
		}
	}
	ans = min(ans, step);

	cout << ans << endl;

	return 0;
}

