int solve(vector<int> a){
	int n = a.size();
	int ans = 0, cur = a[0];
	for(int i = 0;i<n-1;i++){
		if(cur*(cur+a[i+1]) >= 0){
			if(cur>0){
				int meta = -(cur+1);
				ans+=abs(meta-a[i+1]);
				a[i+1]=meta;
			}
			else{
				int meta = -(cur-1);
				ans+=abs(meta-a[i+1]);
				a[i+1]=meta;
			}
		}
		cur+=a[i+1];
	}
	return ans;
}

