int solve(long long n, vector<long long> a , bool f){
	ll ans = 0;
	ll add = 0;

	REP(i,n){
		add += a[i];

		if(add == 0){
			if(f & i % 2 == 0){
				add++;
			}else if(f & i % 2 != 0){
				add--;
			}

			if(!f & i % 2 == 0){
				add--;
			}else if(!f & i % 2 != 0){
				add++;
			}

			ans++;continue;
		}

		if(f & i % 2 == 0 & add < 0){
			ans += abs(add)+1;
			add += abs(add)+1;
		}else if(f & i % 2 != 0 & add > 0){
			ans += abs(add)+1;
			add -= abs(add)+1;
		}

		if(!f & i % 2 == 0 & add > 0){
			ans += abs(add)+1;
			add -= abs(add)+1;
		}else if(!f & i % 2 != 0& add < 0){
			ans += abs(add)+1;
			add += abs(add)+1;
		}
	}

	return ans;
}




