#include "bits/stdc++.h"
using namespace std;
const int N = 1e5 + 5;
int n;
int arr[N];
long long solve(int pos , bool positive , long long sum){
	if(pos > n){
		return 0;
	}
	if(positive){
		if(sum + arr[pos] > 0){
			return solve(pos + 1 , !positive , sum + arr[pos]);
		}
		else{
			return solve(pos + 1 , !positive , 1LL) + 1 - sum - arr[pos];
		}
	}
	else{
		if(sum + arr[pos] < 0){
			return solve(pos + 1 , !positive , sum + arr[pos]);
		}
		else{
			return solve(pos + 1 , !positive , -1) + sum + arr[pos] + 1;
		}
	}
}
int main(){
	scanf("%d" , &n);
	for(int i = 1 ; i <= n ; ++i){
		scanf("%d" , arr + i);
	}
	printf("%lld\n" , min(solve(1 , 0 , 0) , solve(1 , 1 , 0)));
}

