	ll sum = 0;
	REP(i,N){
		ll V = S[i]+A[i];
		if(V==0){
			if(S[i]>0){
				V--;
			}
			else V++;
			sum++;
		}
		else if(V>0 && S[i]>0){
			sum += V+1;
			V=-1;
		}
		else if(V<0 && S[i]<0){
			sum += abs(V)+1;
			V=1;
		}
		S[i+1] = V;
	}

	out(sum);
