const ll RANDOM = chrono::high_resolution_clock::now().time_since_epoch().count();
struct chash { ll operator()(ll x) const { return x ^ RANDOM; } };

const int N = 100005;

int n;
ll a[N];

ll solve() {
    ll sum = a[0], ret = 0; 
    FOR (i, 1, n) {
        if (sum < 0) {
            if (sum + a[i] > 0) sum += a[i];
            else {
                ret += abs((1 - sum) - a[i]);
                sum = 1;
            }
        }
        else {
            if (sum + a[i] < 0) sum += a[i];
            else {
                ret += abs((sum + 1) + a[i]);
                sum = -1;
            }
        }
    }
    return ret;
}

