LL numoperations(int delta)
{
    LL ret = 0, sum = 0;
    REP(i, 0, n)
    {
        sum += A[i];

        if(delta < 0 && sum >= 0){
            ret += abs(-1 - sum);
            sum = -1;
        }
        else if(delta > 0 && sum <= 0){
            ret += 1 - sum;
            sum = 1;
        }
        delta *= -1;
    }
    return ret;
}

