bool diffSign(ll a, ll b) {
  if (a < 0 && b > 0) return true;
  if (a > 0 && b < 0) return true;
  return false;
}

ll calc() {
  ll r1 = 0;
  ll psum = v[0];
  for (int i = 1; i < N; ++i) {
    if (diffSign(psum, psum + v[i])) {
      psum += v[i];
    } else {
      if (psum > 0) {
        r1 += (psum + v[i] + 1);
        psum = -1;
      } else {
        r1 += (1 - psum - v[i]);
        psum = 1;
      }
    }
  }

  return r1;
}
