  if (a0 != 0) {
    ret = min(ret, calc());
  }

  v[0] = 1;
  ret = min(ret, abs(a0 - v[0]) + calc());

  v[0] = -1;
  ret = min(ret, abs(a0 - v[0]) + calc());

  cout << ret << endl;
}

