//--------------------------- Solve ---------------------------//

void solve() {
    int n; cin >> n;
    vector<int> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    long long ans0 = 0;
    // +-
    long long sum = 0;
    for (int i = 0; i < n; i++) {
        sum += a[i];
        // -
        if (i&1) {
            if (sum >= 0) {
                ans0 += sum + 1;
                sum = -1;
            }
        }
        // +
        else {
            if (sum <= 0) {
                ans0 += 1 - sum;
                sum = 1;
            }
        }
    }

    // -+
    long long ans1= 0;
    sum = 0;
    for (int i = 0; i < n; i++) {
        sum += a[i];
        // -
        if (~i&1) {
            if (sum >= 0) {
                ans1 += sum + 1;
                sum = -1;
            }
        }
        // +
        else {
            if (sum <= 0) {
                ans1 += 1 - sum;
                sum = 1;
            }
        }
    }

    cout << min(ans0, ans1) << '\n';
}

int main() {
    cin.tie(nullptr);
    ios_base::sync_with_stdio(false);

    solve();

    return 0;
}

