        LL sign[2] = {1, -1};
        LL cumsum = 0;
        REP0(i, N)
        {
            cumsum += a[i];
            if (cumsum * sign[i % 2] <= 0)
            {
                ans_e += abs(cumsum) + 1;
                cumsum = sign[i % 2];
            }
        }
        ans = min(ans_e, ans);
    }

    { // 奇数番目までの累積を正にする
