  }

  auto solve_1_fn = [](const vector<int64>& xs, int n) -> int64 {
    int64 cur = 0;
    int64 cost = 0;
    for (int i = 0; i < n; i++) {
      cur += xs[i];
      if (i % 2 == 0 && cur <= 0) {
        int64 d = 1 - cur;
        cur += d;
        cost += d;
      } else if (i % 2 == 1 && cur >= 0) {
        int64 d = -(cur + 1);
        cur += d;
        cost += abs(d);
      }
    }
    return cost;
  };

  int64 v1 = solve_1_fn(xs, n);

  for (int i = 0; i < n; i++) {
    xs[i] *= -1;
  }
  int64 v2 = solve_1_fn(xs, n);

  cout << min(v1, v2) << endl;
}

