using namespace std;
using ll=long long;

void solve(ll& sum,ll next,ll& ret){
	if(sum*next<=0){
		if(abs(sum)<abs(next)) {
			sum+=next;
			return;
		}
		ll a=abs(sum)+1;
		ll b=abs(a-abs(next));
		if(sum>0){
			next-=b;
			sum+=next;
		}
		else{
			next+=b;
			sum+=next;
		}
		ret+=b;
	}
	else{
		ll a=abs(sum)+1;
		ll b=abs(next)+a;
		if(sum<0){
			next+=b;
		}
		else{
			next-=b;
		}
		ret+=b;
		sum+=next;
	}
}

