using namespace std;

int calc_cost(vector<long>& nums, bool p) {
  long cost = 0;
  long sum = 0;
  for (long i : nums) {
    sum += i;
    if (sum <= 0 && p) {
      cost += 1 - sum;
      sum = 1;
    } 
    if (sum >= 0 && !p) {
      cost += 1 + sum;
      sum = -1;
    }
    p = !p;
  }
  return cost;
}

