template<class T>
T next(istream& in) {
    T ret;
    in >> ret;
    return ret;
}

template<class T>
vector<T> next_vector(istream& in, size_t n) {
    vector<T> ret(n);
    for (size_t i = 0; i < n; ++i) {
        ret[i] = next<T>(in);
    }
    return ret;
}

template<class T>
vector<T> next_vector(istream& in) {
    auto n = next<size_t>(in);
    return next_vector<T>(in, n);
}


int64 tryIt(const vector<int>& v, int cur) {
    int64 res = 0;
    int64 sum = 0;
    for (int x : v) {
        sum += x;
        if (cur == 1) {
            if (sum <= 0) {
                res += (-sum);
                ++res;
                sum = 1;
            }
        } else {
            if (sum >= 0) {
                res += (sum);
                ++res;
                sum = -1;
            }
        }
        cur = 1 - cur;
    }
    return res;
}

void solve(istream& in, ostream& out) {
    vector<int> v = next_vector<int>(in);
    int64 res = 1LL << 60;
    res = min(res, tryIt(v, 1));
    res = min(res, tryIt(v, 0));
    out << res << endl;
}


