        sum1 = 1;
        sum2 = 1;
        ans = 1;
        sum3 = -1;
        sum4 = -1;
        ans2 = 1;
    }
    else if(a0[0] < 0){
        sum1 = 1;
        sum2 = 1;
        ans = 1 - a0[0];
        sum3 = a0[0];
        sum4 = a0[0];
        ans2 = 0;
    }
    else {
        sum1 = a0[0];
        sum2 = a0[0];
        ans = 0;
        sum3 = -1;
        sum4 = -1;
        ans2 = a0[0] + 1;
    }
    for(int i = 1; i < N; ++i){
        a[i] = a0[i];
        sum2 += a0[i];
        if(sum2 == 0){
            ++ans;
            if(sum1 > 0){
                --a[i];
            }
            else {
                ++a[i];
            }
        }
