constexpr int sign( const LL a )
{
	return ( 0 < a ) - ( a < 0 );
}


LL solve( const VT< LL > &A )
{
	const int N = SZ( A );

	LL sum = A[0], res = 0;
	REP( i, 1, N )
	{
		const LL a = A[i];
		LL t = -sum - sign( sum );
		t = sign( a ) == sign( t ) && abs( t ) < abs( a ) ? a : t;
		res += abs( a - t );
		sum += t;
	}

	return res;
}

int main()
{
	cin.tie( 0 );
	ios::sync_with_stdio( false );
	cout << setprecision( 12 ) << fixed;

	int N;
	scanf( "%d", &N );

	VT< LL > A( N );
	getv( A );

	LL res;
	if ( A[0] == 0 )
	{
		A[0] = 1;
		res = solve( A );
		A[0] = -1;
		chmin( res, solve( A ) );
		++res;
	}
	else
	{
		res = solve( A );
	}

	printf( "%lld\n", res );
	fflush( stdout );

	return 0;
}

