ll fn(ll result,ll sum,ll i,bool nextflug){
  if(i==N)
    return result;
  else
    sum+=numbers[i];

  if(sum==0){
    if(nextflug)
      return fn(result+1,1,i+1,!nextflug);
    else
      return fn(result+1,-1,i+1,!nextflug);
  }else if((sum>0)==nextflug){
      return fn(result,sum,i+1,!nextflug);
  }else{
    if(nextflug)
      return fn(result+abs(sum)+1,1,i+1,!nextflug);
    else
      return fn(result+abs(sum)+1,-1,i+1,!nextflug);
  }  
}

