typedef long long int64;

int N, A[100000];

int64 rec(int idx, int delta, int64 sum)
{
  if(idx == N) {
    return (0);
  } else if(delta == 1) {
    if(sum + A[idx] > 0) return (rec(idx + 1, -1, sum + A[idx]));
    return (rec(idx + 1, -1, 1) + 1 - (sum + A[idx]));
  } else {
    if(sum + A[idx] < 0) return (rec(idx + 1, 1, sum + A[idx]));
    return (rec(idx + 1, 1, -1) + (sum + A[idx]) - (-1));
  }
}

int main()
{
  cin >> N;
  for(int i = 0; i < N; i++) {
    cin >> A[i];
  }
  cout << min(rec(0, 1, 0), rec(0, -1, 0)) << endl;
}

