const int N=2e5+10;

int n;
long long a[N];

long long solve()
{
	long long Ans=0;
	long long now=a[1];
	int opt=a[1]>0;
	for(int i=2;i<=n;i++)
	{
		if(opt==1)
		{
			if(now+a[i]>=0)
			{
				Ans+=now+a[i]+1;
				now=-1;
			}
			else now+=a[i];
		}
		else
		{
			if(now+a[i]<=0)
			{
				Ans-=now+a[i]-1;
				now=1;
			}
			else now+=a[i];
		}
		opt^=1;
	}
	return Ans;
}

int main()
{
	scanf("%d",&n);
	for(int i=1;i<=n;i++) scanf("%lld",&a[i]);
	long long Ans;
	Ans=solve();
	if(a[1]>0)
	{
		long long x=a[1]+1;
		a[1]=-1;
		Ans=min(Ans,solve()+x);
	}
	else 
	{
		long long x=1-a[1];
		a[1]=1;
		Ans=min(Ans,solve()+x);
	}	
	cout<<Ans<<endl;
}

