				pm = -1;
			}
			else if (rui[i]+b < 0 && rui[i - 1]+b < 0) {
				cnt -= rui[i] + b - 1;
				b -= rui[i]+b - 1;
				pm = 1;
			}
			else if (rui[i]+b == 0) {
				if (pm == 1) {
					b--;
					cnt++;
					pm = -1;
				}
				else if (pm == -1) {
					b++;
					cnt++;
					pm = 1;
				}
			}
			else if (rui[i]+b > 0)pm = 1;
			else if (rui[i]+b < 0)pm = -1;
		}
		cout << cnt << endl;
	}

    return 0;
}

