	VT< LL > A( N );
	getv( A );

	LL res;
	if ( A[0] == 0 )
	{
		A[0] = 1;
		res = solve( A );
		A[0] = -1;
		chmin( res, solve( A ) );
		++res;
	}
	else
	{
		res = solve( A );
		const LL a = A[0];
		A[0] = -sign( A[0] );
		chmin( res, solve( A ) + abs( a - A[0] ) );
	}

	printf( "%lld\n", res );
	fflush( stdout );

	return 0;
}

