	for(int i=1;i<=n;i++) scanf("%lld",&a[i]);
	long long Ans;
	if(a[1]==0)
	{
		a[1]=1;
		Ans=solve();
		a[1]=-1;
		Ans=min(Ans,solve());
		cout<<Ans+1<<endl;
		return 0;
	}
	else Ans=solve();
	if(a[1]>0)
	{
		long long x=a[1]+1;
		a[1]=-1;
		Ans=min(Ans,solve()+x);
	}
	else 
	{
		long long x=1-a[1];
		a[1]=1;
		Ans=min(Ans,solve()+x);
	}	
	cout<<Ans<<endl;
}

