int solve() {
	int ans = 0, s = 0;
	for(int i = 0; i < N; i++) {
		s += A[i];
		if(i % 2) {
			int d = max(0, 1 - s);
			ans += d;
			s += d;
		}
		else {
			int d = max(0, s + 1);
			ans += d;
			s -= d;
		}
		//printf("i = %d, s = %d, ans = %d\n", i, s, ans);
	}
	return ans;
}

