using namespace std;

int64_t f(int n, int* a) {
	int64_t s = a[0];
	int64_t c = 0;
	for (int i = 1; i < n; i++) {
		int64_t t = s + a[i];
		if (s < 0 && t <= 0) {
			c += 1 - t;
			t = 1;
		} else if (s > 0 && t >= 0) {
			c += 1 + t;
			t = -1;
		}
		s = t;
	}
	return c;
}

int main() {
	int n, a[100000];
	cin >> n;
	for (int i = 0; i < n; i++) {
		cin >> a[i];
	}
	int a0 = a[0];
	int64_t c = INT64_MAX;
	if (a0 < 0) {
		a[0] = a0;
		c = min(c, f(n, a));
	} else {
		a[0] = -1;
		c = min(c, f(n, a) + 1 + a0);
	}
	if (a0 > 0) {
		a[0] = a0;
		c = min(c, f(n, a));
	} else {
		a[0] = 1;
		c = min(c, f(n, a) + 1 - a0);
	}
	cout << c << endl;
	return 0;
}

