void solve(vll A, ll sum, ll &result) {
	ll len = A.size();

	reps(i, 1, len - 1) {
		if (sum > 0) {
			if (sum + A[i] < 0) {
				//符号反転するので、そのまま
				sum += A[i];
			}
			else {
				//符号反転するように変更(-1にする)
				ll change = -1 - sum;
				result += abs(change - A[i]);
				sum = -1;
			}
		}
		else {
			if (sum + A[i] > 0) {
				//符号反転するので、そのまま
				sum += A[i];
			}
			else {
				//符号反転するように変更(+1にする)
				ll change = 1 - sum;
				result += abs(change - A[i]);
				sum = 1;
			}
		}
	}
}

