	}
	else {
		sum = 1;
		resA = 1 - A[0];
	}
	solve(A, sum, resA);

	//最初を-にする場合
	ll resB = 0;
	if (A[0] < 0) {
		sum = A[0];
		resB = 0;
	}
	else {
		sum = -1;
		resB = abs(-1 - A[0]);
	}
	solve(A, sum, resB);

	ll result = min(resA, resB);

