      count2 += sum+1;
      sum = -1;
    }
    if(i % 2 == 0 && sum <= 0){
      count2 += 1-sum;
      sum = 1;
    }
  }
  if(count1 < count2){
    return count1;
  }else{
    return count2;
  }
}

