	int changeCount = 0; //何回変更するのかのカウント
	int oddPositive = (sum[0] > 0)? 0 : 1; //iが奇数のsumが正のときに1
	int evenPositive = (sum[0] > 0)? 1 : 0;//iが偶数のsumが正のときに1

