int changeCount(int a*, boolean oddPositive){
/*sum[i]はa[0]〜a[i]までの和*/
	int *sum;
	sum = (int*)malloc( n * sizeof(int));
	sum[0] = a[0];

	int evenchangeCount = 0; //何回変更するのかのカウント
	boolean evenPositive = (oddPositive)? false: true;//iが偶数のsumが正のときに1

	for(i=1; i<n; i++){
		sum[i] = sum[i-1] + a[i];
		if(i%2 == 1){
			/*iが奇数の時*/
			if(oddPositive){
			//正でなければいけないとき
				if(sum[i] <= 0){ //正でないなら
					evenchangeCount += -sum[i] + 1;
					sum[i] = 1;
				}
			}else{		
			//負でなければいけないとき
				if(sum[i] >= 0){ //負でないなら
					evenchangeCount += sum[i] + 1;
					sum[i] = -1;
				}
			}
		}else{
			/*iが偶数の時*/
			if(evenPositive){
			//正でなければいけないとき
				if(sum[i] <= 0){
				//正でないなら
					evenchangeCount += -sum[i] + 1;
					sum[i] = 1;
				}
			}else{
			//負でなければいけないとき
				if(sum[i] >= 0){
				//負でないなら
					evenchangeCount += sum[i] + 1;
					sum[i] = -1;
				}
			}
		}
	}
}

