        Tp = Tc;
        Tc += b[i];
        if (Tc == 0LL) {
            if (Tp > 0LL) { b[i]--; Tc--; }
            else { b[i]++; Tc++; }
            P2++;
        } else if (Tc > 0LL && Tp > 0LL) {
            b[i] -= Tc + 1LL;
            P2 += Tc + 1LL;
            Tc = -1LL;
        } else if (Tc < 0LL && Tp < 0LL) {
            b[i] += -Tc + 1LL;
            P2 += -Tc + 1LL;            
            Tc = 1LL;
        }
    }
    if (P1<P2) printf("%lld\n", P1);
    else printf("%lld\n", P2);
//    for (i=0;i<N;i++) printf("%lld\t", a[i]);  printf("\n");
    return 0;
}

