int sequence(int n, int* a)
{
  int i,sum,temp,count;
  sum = 0;
  temp = 0;
  count = 0;
  for(i = 0; i < n; i++){
    sum += a[i];
    while(sum == 0 || (sum * temp) > 0){
      if(temp > 0){
        sum--;
      }else{
        sum++;
      }
      count++;
    }
    temp = sum;
  }
  return count;
}

