				if(temp_2 <= 0){//正でないなら
					changeCount += -temp_2 + 1;
					temp_2 = 1;
				}
			}else{//合計が負でなければいけないとき
				if(temp_2 >= 0){//負でないなら
					changeCount += temp_2 + 1;
					temp_2 = -1;
				}
			}

		}else{/*iが偶数の時*/
			if(oddPositive == 0){//合計が正でなければいけないとき
				if(temp_2 <= 0){//正でないなら
					changeCount += -temp_2 + 1;
					temp_2 = 1;
				}
			}else{//負でなければいけないとき
				if(temp_2 >= 0){//負でないなら
					changeCount += temp_2 + 1;
					temp_2 = -1;
				}
			}
		}
		temp_1 = temp_2;
	}
	return changeCount;
}

