		//printf(stderr, "error: ill-formed fraction.\n");
		exit(1);
	}

	int evenchangeCount = changeCount(a, n, 0); //何回変更するのかのカウント
	int oddchangeCount = changeCount(a, n, 1); //何回変更するのかのカウント

