int changeCount(int *a, int n, int oddPositive){
/*sum[i]はa[0]〜a[i]までの和*/
	//int *sum;
	//sum = (int*)malloc(n * sizeof(int));
	int temp_1=0;
	int temp_2=0;
	int changeCount = 0; //何回変更するのかのカウント

	int i;
	for(i=0; i < n; i++){
		temp_2 = temp_1 + a[i];

		if(i%2 == 1){
			/*iが奇数の時*/
			if(oddPositive == 1){
			//合計が正でなければいけないとき
				if(temp_2 <= 0){
				//正でないなら
					changeCount += -temp_2 + 1;
					temp_2 = 1;
				}
			}else{		
			//合計が負でなければいけないとき
				if(temp_2 >= 0){
				//負でないなら
					changeCount += temp_2 + 1;
					temp_2 = -1;
				}
			}
		}else{
			/*iが偶数の時*/
			if(oddPositive == 0){
			//合計が正でなければいけないとき
				if(temp_2 <= 0){
				//正でないなら
					changeCount += -temp_2 + 1;
					temp_2 = 1;
				}
			}else{
			//負でなければいけないとき
				if(temp_2 >= 0){
				//負でないなら
					changeCount += temp_2 + 1;
					temp_2 = -1;
				}
			}
		}
		temp_1 = temp_2;
	}
	return changeCount;
}

