int counting(const int *alist,const int n)
{
    int sum = alist[0];
    int count = 0;

    for (int i = 1; i < n; i++) {
        int a = alist[i];
        int a_dash;
        if ((sum > 0) && (sum + a >= 0)) {
            a_dash = -1 - sum;
            count += a - a_dash;
        } else if ((sum < 0) && (sum + a <= 0)) {
            a_dash = 1 - sum;
            count += a_dash - a;
        } else {
            a_dash = a;
        }
        sum += a_dash;
    }
    return count;
}

