    static class TaskC {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int[] a = in.nextIntArray(n);

            int tmp1 = 0;
            int sum1 = 0;
            for (int i = 0; i < n; i++) {
                sum1 += a[i];
                if (i % 2 == 0) {
                    if (sum1 >= 0) {
                        tmp1 += sum1 + 1;
                        sum1 = -1;
                    }
                } else {
                    if (sum1 <= 0) {
                        tmp1 += -sum1 + 1;
                        sum1 = 1;
                    }
                }
            }

            int tmp2 = 0;
            int sum2 = 0;
            for (int i = 0; i < n; i++) {
                sum2 += a[i];
                if (i % 2 == 1) {
                    if (sum2 >= 0) {
                        tmp2 += sum2 + 1;
                        sum2 = -1;
                    }
                } else {
                    if (sum2 <= 0) {
                        tmp2 += -sum2 + 1;
                        sum2 = 1;
                    }
                }
            }

            out.println(Math.min(tmp1, tmp2));
        }

    }

