		for(int i=0; i<n; i++){
			sum += a[i];

			if(sum == 0) break;
			else if(i == 0){
				if(0 < sum) flag = true;
				else if(sum < 0) flag = false;
			}
			else if(0 < sum && flag == false) flag = true;
			else if(sum < 0 && flag == true) flag = false;
			else break;

			if(i == n-1){
				System.out.println("0");
				System.exit(0);
			}
		}

		sum = 0;
		for(int i=0; i<n; i++){
			sum += a[i];

			if(i == 0){
				if(0 < sum) flag = true;
				else if(sum < 0) flag = false;
			}else if(flag == false){
				if(sum < 0){
					result += 0-sum+1;
					sum = 1;
				}else if(sum == 0){
					result += 1;
					sum = 1;
				}
				flag = true;
			}else if(flag == true){
				if(0 < sum){
					result += sum+1;
					sum = -1;
				}else if(sum == 0){
					result += 1;
					sum = -1;
				}
				flag = false;
			}

		}

		System.out.println(result);
	}
}

