public class Main {
	int N;
	long[] a;

	public long calc(long[] a){
		long ans = 0;
		long now = 0;

		for(int i = 0;i < N-1;i++){
			now += a[i];
			if(now < 0 && now+a[i+1] <= 0){
				long add = Math.abs(now+a[i+1])+1;
				a[i+1] += add;
				ans += add;

			}else if(now > 0 && now+a[i+1] >= 0){
				long add = now+a[i+1]+1;
				a[i+1] -= add;
				ans += add;
			}
		}

		return ans;
	}

	public void solve() {
		N = nextInt();
		a = new long[N];
		for(int i = 0;i < N;i++){
			a[i] = nextInt();
		}

		if(a[0] == 0){
			a[0] = 1;
			long ans = calc(a);
			a[0] = -1;
			ans = Math.min(ans, calc(a));
			out.println(ans);
			return;
		}else{
			long ans = 0;
			if(a[0] > 0){
				ans = calc(a);
				long tmp = a[0] + 1;
				a[0] = -1;
				out.println(Math.min(ans,calc(a) + tmp));
			}else{
				ans = calc(a);
				long tmp = -a[0] + 1;
				a[0] = 1;
				out.println(Math.min(ans, calc(a) + tmp));
			}
		}
	}

