			sum += a[i];
			if (i % 2 == mode) {
				if (sum <= 0) {
					cnt += 1 - sum;
					sum = 1;
				}
			} else {
				if (sum >= 0) {
					cnt += 1 + sum;
					sum = -1;
				}
			}
		}

		return cnt;
	}

	public void solve() {
		N = nextInt();
		a = new int[N];
		for (int i = 0; i < N; i++) {
