				long t=-sum[i-1]-1;
				if(a[i]>t){
					res+=a[i]-t;
					a[i]=t;
				}
			}else {
				long t=-sum[i-1]+1;
				if(a[i]<t){
					res+=t-a[i];
					a[i]=t;
				}
			}
