public class Main{
	public static void main(String[] args)  {
		Scanner scanner = new Scanner(System.in);
		int n = scanner.nextInt();
		int[] num = new int[n];
		for(int i = 0; i < n; i++){
			num[i] = scanner.nextInt();
		}
		int countP = exe(n, num, 1);
		int countM = exe(n, num, -1);
		System.out.println(countP > countM ? countM: countP);

	}
	private static int exe(int n, int[] num, int sig){
		int count = 0;
		int[] ans = new int[n];
		ans[0] = sig * num[0];
		for(int i = 0; i < num.length - 1; i++){
			int sa = sa(ans, num[i + 1]);
			ans[i + 1] = num[i + 1] + sa;
			if(plusCheck(ans)){
				count++;
				ans[ans.length - 1] = addOne(ans[ans.length - 1]);
			}
			count += Math.abs(sa);
		}
		return count;
	}
	private static boolean plusCheck(int[] num){
		int total = 0;
		for(int n: num){
			total += n;
		}
		return total == 0;
	}
	private static int addOne(int num){
		int sig = (int)Math.signum(num);
		return sig * (Math.abs(num) + 1);
	}
	private static int sa(int[] left, int right){
		int total = 0;
		for(int num : left){
			total += num;
		}
//		int sa = total - right;
		int sigTotal = (int)Math.signum(total);
		int sigWa    = (int)Math.signum(total + right);
		if(sigTotal != sigWa){
			return 0;
		}
		return (-sigTotal - total) - right;
	}

}

public class Main {
	public static void main(String[] args) {
		int N = NI();
		int a[] = new int[N];
		for (int i = 0; i < N; i++) {
			a[i] = NI();
		}
		long ans = 0;
		if (a[0] == 0) {
			a[0] = 1;
			ans = solve(a);
			a[0] = -1;
			ans = Math.min(ans, solve(a));
			ans++;
		} else {
			ans = solve(a);
		}
		System.out.println(ans);
	}
	private static long solve(int[] a) {
		long ans = 0;
		long sum = a[0];
		for (int i = 1; i < a.length; i++) {
			if (sum > 0) {
				if (sum + a[i] >= 0) {
					ans += sum + a[i] + 1;
					sum = -1;
				} else {
					sum += a[i];
				}
			} else {
				if (sum + a[i] <= 0) {
					ans += -(sum+a[i]) + 1;
					sum = 1;
				} else {
					sum += a[i];
				}
			}
		}
		return ans;
	}
	static int NI(){
		try {
			int c=System.in.read(),r=0;
			for(;c!='-'&&(c<'0'||'9'<c);)c=System.in.read();
			if(c=='-') return -NI();
			for(;'0'<=c&&c<='9';c=System.in.read())
				r = r * 10 + c - '0';
			return r;
		} catch (Exception e) {
			return -1;
		}
	}
	static String next() {
		try {
			StringBuilder res = new StringBuilder("");
			int c = System.in.read();
			while (Character.isWhitespace(c))
				c = System.in.read();
			do {
				res.append((char) c);
			} while (!Character.isWhitespace(c = System.in.read()));
			return res.toString();
		} catch (Exception e) {
			return null;
		}
	}
}

