		int[] a = na(n);
		long min = Long.MAX_VALUE;
		for(int x = -1;x <= 1;x+=2){
			long s = 0;
			int sg = x;
			long cost = 0;
			for(int i = 0;i < n;i++, sg=-sg){
				s += a[i];
				if(Long.signum(s) == sg){
				}else if(sg == 1){
					cost += 1-s;
					s = 1;
				}else{
