			if(a[1] < 0){
				a[0] = 1;
			}else{
				a[0] = -1;
			}
			ans++;
		}
		for(int i = 0;i < N;i++){
			now += a[i];
			if(i + 1 < N && now < 0 && now+a[i+1] <= 0){
				long add = Math.abs(now+a[i+1])+1;
				a[i+1] += add;
				ans += add;

			}else if(i + 1 < N && now > 0 && now+a[i+1] >= 0){
				long add = now+a[i+1]+1;
				a[i+1] -= add;
				ans += add;
			}
		}

		out.println(ans);
	}

