				if( i%2==0 && a[i]-c>=0 ){
					count1 += a[i] - c + 1;
					a[i] -= a[i] - c + 1;
				}         
		}     
		for( int i=1; i<=N; i++ ){
			for( int j=i-1; j>=0; j-- ){
				d += b[j];
            }              
				if( i%2==0 && b[i]-d<=0 ){
					count2 += d - b[i] + 1;
					b[i] += d - b[i] + 1;
				}
				if( i%2!=0 && b[i]-d>=0 ){
					count2 += b[i] - d + 1;
					b[i] -= b[i] - d + 1;
				}           
		}      
		System.out.println(Math.min(count1,count2));
	}
}

