			sum[i] = (i > 0 ? sum[i - 1] : 0) + a[i];
		}

		long d = 0;
		long cnt = 0;
		for (int i = 1; i < n; ++i) {
			if ((sum[i] + d) * (sum[i - 1] + d) < 0) {
				continue;
