public class Main {
	class Solver {
		long solve(int[] a) {
			return Math.min(helper(a, 1), helper(a, -1));
		}

		private long helper(int[] a, int sign) {
			long ans = 0;
			long sum = 0;
			for (int i = 0; i < a.length; i++) {
				long next = sum + a[i];
				if (i % 2 == 0 && next * sign >= 0 || i % 2 == 1 && next * sign <= 0) {
					next = i % 2 == 0 ? -sign : sign;
					ans += Math.abs(next - (sum + a[i]));
				}
				sum = next;
			}
			return ans;
		}
	}

