        int Repeat;
        Scanner sc;
        Printer pr;
        public Problem(bool isGCJ, Scanner scanner, Printer printer)
        {
            sc = scanner;
            pr = printer;
            IsGCJ = isGCJ;
            if (isGCJ) Repeat = sc.nextInt();
            else Read();
        }
        public Problem(bool isGCJ) : this(isGCJ, new Scanner(), new Printer()) { }
        public Problem(bool isGCJ, Scanner scanner) : this(isGCJ, scanner, new Printer()) { }
        public Problem(bool isGCJ, Printer printer) : this(isGCJ, new Scanner(), printer) { }
        public void Solve()
        {
            if (IsGCJ) for (var i = 0; i < Repeat; i++) { Read(); pr.Write("Case #" + (i + 1) + ": "); SolveOne(); }
            else SolveOne();
        }
        public void Dispose()
        {
            sc.Dispose();
            pr.Dispose();
        }
        public int Size { get { return 1; } }
        public const long Mod = 1000000007;

        // 使用する変数をここに書く
        // string S;
        // int a;
        /// <summary>
        /// 読み込み処理をここに書く
        /// </summary>
        void Read()
        {

        }
        /// <summary>
        /// メイン処理をここに書く
        /// </summary>
        void SolveOne()
        {
            int n = sc.nextInt();
            long[] a = sc.nextLong(n);
            long ans = long.MaxValue;

            long now, tmp;
            now = 0;
            tmp = 0;
            for (int i = 0; i < n; i++)
            {
                now += a[i];
                if (i % 2 == 0) //p
                {
                    if (now <= 0)
                    {
                        tmp += 1 - now;
                        now = 1;
                    }
                }
                else //m
                {
                    if (now >= 0)
                    {
                        tmp += now + 1;
                        now = -1;
                    }
                }
            }
            ans = Math.Min(ans, tmp);
            now = 0;
            tmp = 0;
            for (int i = 0; i < n; i++)
            {
                now += a[i];
                if (i % 2 != 0) //p
                {
                    if (now <= 0)
                    {
                        tmp += 1 - now;
                        now = 1;
                    }
                }
                else //m
                {
                    if (now >= 0)
                    {
                        tmp += now + 1;
                        now = -1;
                    }
                }
            }
            ans = Math.Min(ans, tmp);
            Console.WriteLine(ans);
        }
    }
