    private static long CalcScore(int n, int[] aArr, long culmative) {
        long nHands = 0;

        for (int i = 1; i < n; i++) {
            var isPrevPlus = culmative > 0;
            culmative += aArr[i];
            if (culmative > 0 == isPrevPlus || culmative == 0) {
                var thisNHands = (isPrevPlus ? -1 : 1) - culmative;
                nHands += Math.Abs(thisNHands);
                culmative += thisNHands;
            }
        }
        return nHands;
    }
}

