        long culmative = aArr[0];
        long score = 0;
        if (culmative == 0) {
            score = Math.Min(NewMethod(n, aArr, 1), NewMethod(n, aArr, -1));
            score++;
        } else {
            score = NewMethod(n, aArr, aArr[0]);
