using static System.Console;
using System.Linq;
namespace AtCoder.ARC072
{
    class Sequence
    {
        static long SolveGreedy(int[] array)
        {
            if (array[0] == 0) array[0] = 1;
            var min = SolveGreedyRec(array, 1, array[0], array[0]);

            var temp = SolveGreedyRec(array, 1, -Sign(array[0]), -Sign(array[0]), Abs(array[0] + Sign(array[0])));
            return min > temp ? temp : min;
        }
        static long SolveGreedyRec(int[] array, int index, long prev, long sum, long res = 0)
        {
            if (index == array.Length) return res;
            long next = array[index];
            if (next == 0)
            {
                next = -Sign(prev);
            }
            if (next + sum == 0) next -= Sign(sum);
            if (Sign(next + sum) == Sign(sum))
            {
                next = -Sign(sum) * (Abs(sum) + 1);
            }
            return SolveGreedyRec(array, index + 1, next, sum + next, res + Abs(next - array[index]));
        }
        static long Abs(long n)
        {
            return n > 0 ? n : -n;
        }
        static long Sign(long n)
        {
            return n > 0 ? 1 : -1;
        }
        static int Sign(int n)
        {
            return n > 0 ? 1 : -1;
        }
        public static void Main()
        {
            var n = int.Parse( ReadLine().Trim());
            WriteLine(SolveGreedy(ReadLine().Trim().Split(' ').Select(s => int.Parse(s)).ToArray()));
        }
    }
}

