    private static long CalcScore(int n, int[] aArr, bool isFirstPlus) {
        long nHands = 0;
        long culmative = 0;
        if (aArr[0] > 0 != isFirstPlus || aArr[0] == 0) {
            var thisNHands = (isFirstPlus ? 1 : -1) - aArr[0];
            nHands += Math.Abs(thisNHands);
            culmative = aArr[0] + thisNHands;
        } else {
            culmative = aArr[0];
        }

        for (int i = 1; i < n; i++) {
            var isPrevPlus = culmative > 0;
            culmative += aArr[i];
            if (culmative > 0 == isPrevPlus || culmative == 0) {
                var thisNHands = (isPrevPlus ? -1 : 1) - culmative;
                nHands += Math.Abs(thisNHands);
                culmative += thisNHands;
            }
        }
        return nHands;
    }
}

