                    {
                        operations += 1;
                        sum += 1;
                        sign = 1;
                    }
                    else
                    {
                        int sum2 = 0;
                        for (int j = 0; j < n; ++j)
                        {
                            sum2 += a[j];
                            if (sum2 != 0)
                            {
                                if (j % 2 == 0)
                                {
                                    operations += 1;
                                    sum += 1;
                                    sign = 1;
                                }
                                else
                                {
                                    operations += 1;
                                    sum -= 1;
                                    sign = -1;
                                }
                                break;
                            }
                        }
                    }
                }
                else if (sum * sign==0)
                {
                    sign = sum / Math.Abs(sum);
                }
                else if (sum * sign < 0)
                {
                    sign *= -1;
                }
                else
                {
                    operations += Math.Abs(-sum - sign);
                    sum += (-sum - sign);
                    sign *= -1;
                }
            }

            //出力
            io.WriteLine(operations.ToString());

    }
}

