class Magatro
{
    private int N;
    private int[] A;
    private void Scan()
    {
        var cin = new Scanner(Console.OpenStandardInput());
        N = cin.NextInt();
        A = cin.IntArray();
    }

    public void Solve()
    {
        Scan();

        int plusCnt;
        int minusCnt;

        int plusV;
        int minV;
        if (A[0] > 0)
        {
            plusCnt = 0;
            minusCnt = A[0] + 1;
            plusV = A[0];
            minV = -1;
        }
        else if (A[0] < 0)
        {
            plusCnt = -A[0] + 1;
            minusCnt = 0;
            plusV = 1;
            minV = A[0];
        }
        else
        {
            plusCnt = 1;
            minusCnt = 1;
            plusV = 1;
            minV = -1;
        }


        for(int i = 1; i < N; i++)
        {
            int nexPV;
            int nexPC;
            //plus
            if (minV + A[i] > 0)
            {
                nexPV = A[i] + minV;
                nexPC = minusCnt;
            }
            else
            {
                nexPV = 1;
                nexPC =minusCnt+ 1 - (minV + A[i]);
            }

            int nexMV;
            int nexMC;
            //minus
            if (plusV + A[i] < 0)
            {
                nexMV = A[i] + plusV;
                nexMC = plusCnt;
            }
            else
            {
                nexMV = -1;
                nexMC = plusCnt+1 + (plusV + A[i]);
            }

            minV = nexMV; 
            minusCnt = nexMC;
            plusV = nexPV;
            plusCnt = nexPC;

        }

        Console.WriteLine(Math.Min(plusCnt, minusCnt));
    }
}

