    {
        int sum = 0;
        for (int i = 0; i < N; i++)
        {
            sum += A[i];
            if (i == 0) continue;
            if ((sum - A[i]) > 0 && sum >= 0)
            {
                while (sum >= 0)
                {
                    sum--;
                    cnt++;
                }
            }
            else if((sum - A[i]) < 0 && sum <= 0)
            {
                while (sum <= 0)
                {
                    sum++;
                    cnt++;
                }
            }
            //WriteLine(sum);
        }
        ans = Math.Min(cnt, ans);
    }

