func solve() {
	n := nextInt()
	a := make([]int64, n)
	for i := 0; i < n; i++ {
		a[i] = nextInt64()
	}
	out(min64(calc(a, 0), calc(a, 1)))
}

func calc(a []int64, n int) int64 {
	x := int64(0)
	ttl := int64(0)
	for i := 0; i < len(a); i++ {
		ttl += a[i]
		if i&1 == n && ttl <= 0 {
			x += 1 - ttl
			ttl = 1
		} else if i&1 != n && ttl >= 0 {
			x += ttl + 1
			ttl = -1
		}
	}
	return x
}

