const size = 1000000
var reader = bufio.NewReaderSize(os.Stdin,size)
func NextLine() string {
  var line,buffer []byte
  var isPrefix bool = true
  var err error
  for ;isPrefix; {
    line,isPrefix,err = reader.ReadLine()
    if err != nil { panic(err) }
    buffer = append(buffer,line...)
  }
  return string(buffer)
}
func NextIntArray() []int {
  var s []string = strings.Split(NextLine()," ")
  var n int = len(s)
  var a []int = make([]int,n)
  for i:=0;i<n;i++ {
    a[i],_ = strconv.Atoi(s[i])
  }
  return a
}
func NextInt() int {
  var n int
  n,_ = strconv.Atoi(NextLine())
  return n
}

func main() {
  var n int = NextInt()
  var a []int = NextIntArray()
  var b []int = make([]int,n)
  for i:=0;i<n;i++ { b[i] = a[i] }
  var ma,mb,s,t int64
  ma = 0
  mb = 0
  s = 0
  for i:=0;i<n;i++ {
    t = s + int64(a[i])
    if i%2 == 0 && t <= 0 {
      ma += 1-t
      s = 1
    } else if i%2 == 1 && t >= 0 {
      ma += t+1
      s = -1
    } else {
      s = t
    }
  }
  s = 0
  for i:=0;i<n;i++ {
    t = s + int64(b[i])
    if i%2 == 1 && t <= 0 {
      mb += 1-t
      s = 1
    } else if i%2 == 0 && t >= 0 {
      mb += t+1
      s = -1
    } else {
      s = t
    }
  }
  fmt.Println(min(ma,mb))
}
func min(n int64,m int64) int64 {
  if n < m {
    return n
  } else {
    return m
  }
}

void main() {
	auto n = ri;
	auto a = readAs!(int[]);
	ulong res = ulong.max;

	// 0: (odd, even) -> (+, -)
	// 1: (odd, even) -> (-, +)
	foreach(k; 0..2) {
		ulong cnt;
		long tmp;
		foreach(i, v; a) {
			tmp += v;
			if((i+1 + k) % 2 == 0) {
				if(tmp <= 0) {
					cnt += -tmp+1;
					tmp = 1;
				}
			} else {
				if(tmp >= 0) {
					cnt += tmp+1;
					tmp = -1;
				}
			}
		}
		res = min(res, cnt);
	}
	res.writeln;
}

