void main(){
    auto n = readLong();
    auto a = readLongs();

    long solve(long s, long i) {
        if(i == n) {
            return 0;
        }
        if(s > 0) {
            if(s + a[i] >= 0) {
                return s + a[i] + 1 + solve(-1, i+1);
            } else {
                return solve(s + a[i], i+1);
            }
        } else {
            if(s + a[i] <= 0) {
                return -(s + a[i]) + 1 + solve(1, i+1);
            } else {
                return solve(s + a[i], i+1);
            }
        }
    }
    if(a[0] == 0) {
        writeln(1 + min(solve(1, 1), solve(-1, 1)));
    } else {
        if(a[0] > 0) {
            writeln(min(solve(a[0], 1), a[0] + 1 + solve(-1, 1)));
        } else {
            writeln(min(solve(a[0], 1), -a[0] + 1 + solve(1, 1)));
        }
    }
}

