	long res;
	long tmp;
	foreach(i, v; a) {
		tmp += v;
		if(i % 2 == 0) {
			if(tmp <= 0) {
				res += -tmp + 1;
				tmp = 1;
			}
		} else {
			if(tmp >= 0) {
				res += tmp + 1;
				tmp = -1;
			}
		}
	}

	long res2;
	tmp = 0;

	// -, +, -, ...
	foreach(i, v; a) {
		tmp += v;
		if(i % 2 == 0) {
			if(tmp >= 0) {
				res2 += tmp + 1;
				tmp = -1;
			}
		} else {
			if(tmp <= 0) {
				res2 += -tmp + 1;
				tmp = 1;
			}
		}
	}

	debug writefln("%d %d", res, res2);
	min(res, res2).writeln;
}

