    ans = 0
    sum = a[0]
    for i in range(1, n):
        now = a[i]
        next_sum = sum + now
        if sum > 0:
            if next_sum > 0:
                ans += (next_sum + 1)
                next_sum = -1
                sum = next_sum
                continue
            elif next_sum < 0:
                sum = next_sum
