            elif next_sum == 0:
                next_sum = -1
                sum = next_sum
                ans += 1
                continue
        elif sum < 0:
            if next_sum > 0:
                sum = next_sum
                continue
            elif next_sum < 0:
                ans += (abs(next_sum) + 1)
                next_sum = 1
                sum = next_sum
                continue
            elif next_sum == 0:
                next_sum = 1
                sum = next_sum
                ans += 1
                continue
        elif sum == 0:
            sum = next_sum
            continue

    return ans


