def sign(x):
    if x < 0:
        return -1
    elif x > 0:
        return 1
    else:
        return 0


def compute(n, ys):
    xs = ys[:]
    if xs[0] == 0:
        return min(compute(n, [1] + xs[1:]), compute(n, [-1] + xs[1:])) + 1
    ss = [None for _ in range(n)]
    ss[0] = xs[0]
    res = 0
    for i in range(n - 1):
        ss[i + 1] = ss[i] + xs[i + 1]
        dx = 0
        if ss[i + 1] == 0:
            dx = -sign(ss[i])
        elif sign(ss[i]) == sign(ss[i + 1]):
            dx = -sign(ss[i]) * (abs(ss[i + 1]) + 1)
        xs[i + 1] += dx
        ss[i + 1] += dx
        res += abs(dx)
    return res


def main():
    n = int(input())
    ys = [int(y) for y in input().split()]
    print(compute(n, ys))


