import numpy as np


def dp(i,n):
    if i == 0:
        if a[0] == 0:
            if n == 1:
                return 1,1
            elif np.sign(a[1]) != 0:
                return -1 * np.sign(a[1]), 1
            else:
                return 1,1
        else:
            return a[0],0
    else:
        sg,count = dp(i-1,n)
        if np.sign(sg) == -1 * np.sign(sg+a[i]):
            return sg+a[i], count
        elif np.sign(sg) == 1:
            delta = abs(-1 - (sg + a[i]))
            return -1,count+delta
        else:
            delta = abs(1 - (sg + a[i]))
            return 1,count+delta


