fn counter(a: &mut Vec<i64>, judge: &Fn(usize) -> bool) -> i64 {
    let mut sum = 0;
    let mut counter = 0;
    for i in 0..a.len() {
        if judge(i) {
            if sum + a[i] == 0 {
                a[i] += 1;
                counter += 1;
            } else if sum + a[i] < 0 {
                counter += (sum + a[i]).abs() + 1;
                a[i] += (sum + a[i]).abs() + 1;
            }
        } else {
            if sum + a[i] == 0 {
                a[i] -= 1;
                counter += 1;
            } else if sum + a[i] > 0 {
                counter += (sum + a[i] + 1).abs();
                a[i] -= sum + a[i] + 1;
            }
        }
        sum += a[i];
    }
    counter
}

