fn main(){
    let _: usize = get_one();
    let xs: Vec<i64> = get_vec();

    let ans1 = solve(&xs);
    let ans2 = solve(&(xs.iter().map(|&x| -x).collect()));

    println!("{}", min(ans1, ans2));
}

fn solve(xs: &Vec<i64>) -> i64 {
    let mut acc = 0;
    let mut ans = 0;

    for i in 0..xs.len() {
        acc += xs[i];
        if acc * (1 - 2*(i%2) as i64) <= 0 {
            ans += (1 - 2*(i%2) as i64 - acc).abs();
            acc = 1 - 2*(i%2) as i64;
        }
    }

    ans
}

