fn get_line() -> String {
    let mut s = String::new();
    match stdin().read_line(&mut s){
        Ok(_) => {s.trim().to_string()}
        Err(_) => String::new()
    }
}

#[allow(dead_code)]
fn get_vec<T: std::str::FromStr>() -> Vec<T> {
    let line = get_line();
    line.split_whitespace().filter_map(|x| x.parse().ok()).collect()
}

#[allow(dead_code)]
fn get_one<T: FromStr + Copy>() -> T {
    let v = get_vec();
    v[0]
}

#[allow(dead_code)]
fn get_pair<T: FromStr + Copy>() -> (T, T) {
    let v = get_vec();
    (v[0], v[1])
}

#[allow(dead_code)]
fn get_triple<T: FromStr + Copy>() -> (T, T, T) {
    let v = get_vec();
    (v[0], v[1], v[2])
}

#[allow(dead_code)]
fn get_chars() -> Vec<char> {
    get_line().chars().collect()
}

fn read() -> String {
    let mut buf = String::new();
    std::io::stdin().read_line(&mut buf).ok();
    buf.trim().to_string()
}

fn main() {
    let n: usize = read().parse().unwrap();
    let a: Vec<i64> = read()
        .split_whitespace()
        .map(|x| x.parse().unwrap())
        .collect();

    let mut sum = (0, 0);
    let mut cnt = (0, 0);
    use std::cmp::{max, min};
    for i in 0..n {
        sum.0 += a[i];
        sum.1 += a[i];
        let f = if i % 2 == 0 { (1, -1) } else { (-1, 1) };

        cnt.0 += max(0, 1 - sum.0 * f.0);
        sum.0 = max(1, sum.0 * f.0) * f.0;
        cnt.1 += max(0, 1 - sum.1 * f.1);
        sum.1 = max(1, sum.1 * f.1) * f.1;
    }
    println!("{}", min(cnt.0, cnt.1));
}

