    let mut m_sum = 0;
    let mut p_ans = 0;
    let mut m_ans = 0;
    for i in 0..a.len() {
        p_sum += a[i];
        m_sum += a[i];
        if i % 2 == 0 {
            if p_sum >= 0 {
                p_ans += p_sum + 1;
                p_sum = -1;
            }
            if m_sum <= 0 {
                m_ans += m_sum.abs() + 1;
                m_sum = 1;
            }
        } else {
            if p_sum <= 0 {
                p_ans += p_sum.abs() + 1;
                p_sum = 1;
            }
            if m_sum >= 0 {
                m_ans += m_sum + 1;
                m_sum = -1;
            }
        }
    }
    println!("{}", std::cmp::min(p_ans, m_ans));
}

