fn solve(a: &Vec<i64>, even_plus: bool) -> i64 {
    let mut total = 0;
    let mut res = 0;
    for (i, &x) in a.iter().enumerate() {
        total += x;
        if (i % 2 == 0 && even_plus && total <= 0) || (i % 2 != 0 && !even_plus && total <= 0) {
            res += 1 - total;
            total = 1;
        } else if (i % 2 == 0 && !even_plus && total >= 0) || (i % 2 != 0 && even_plus && total >= 0) {
            res += total + 1;
            total = -1;
        }
    }
    res
}

