fn solve<R: BufRead, W: Write>(mut input: R, mut output: W) {
    let mut s = String::new();
    input.read_line(&mut s).unwrap();
    let _ = s.trim().parse::<usize>().unwrap();
    s.clear();
    input.read_line(&mut s).unwrap();
    let a = s.split_whitespace()
        .map(|s| s.parse::<i64>().unwrap())
        .collect::<Vec<_>>();
    let result = [true, false]
        .iter()
        .map(|&initial| {
            let mut flag = initial;
            let mut total = 0;
            let mut cost = 0usize;
            for &i in &a[0..] {
                total += i;
                if total == 0 || (total > 0) != flag {
                    cost += (total - if flag { 1 } else { -1 }).abs() as usize;
                    total = if flag { 1 } else { -1 };
                }
                flag ^= true;
            }
            cost
        })
        .min()
        .unwrap();
    writeln!(output, "{}", result).unwrap();
}

