const MOD: u64 = 1_000_000_007;

fn modpow(a: u64, b: u64) -> u64 {
    let mut a = a;
    let mut b = b;
    let mut res = 1;
    while b != 0 {
        if b & 1 != 0 {
            res = res * a % MOD;
        }
        a = a * a % MOD;
        b /= 2;
    }
    res
}

fn is_prime(n: u32) -> bool {
    if n <= 1 {
        false
    } else if n == 2 || n == 3 || n == 5 {
        true
    } else if n % 2 == 0 || n % 3 == 0 || n % 5 == 0 {
        false
    } else {
        for i in 2..n {
            if i * i > n {
                break;
            }
            if n % i == 0 {
                return false;
            }
        }
        true
    }
}

fn is_prime_table(n: usize) -> Vec<bool> {
    let mut is_prime = vec![true; n + 1];
    is_prime[0] = false;
    is_prime[1] = false;
    for i in 2..n+1 {
        unsafe {
            if *is_prime.get_unchecked(i) {
                let mut j = i * i;
                while j <= n {
                    *is_prime.get_unchecked_mut(j) = false;
                    j += i;
                }
            }
        }
    }
    is_prime
}

fn prime_table(n: usize) -> Vec<u64> {
    let is_prime = is_prime_table(n);
    is_prime.iter().enumerate()
        .filter(|&(_, &isp)| isp).map(|(i, _)| i as u64)
        .collect()
}


