fn s(x: i64) -> i64 {
    if x == 0 {
        0
    } else {
        x / x.abs()
    }
}

fn func(a: &Vec<i64>, sign: i64) -> u64 {
    let mut sign = sign;
    let mut ans = 0;
    let mut acc = 0;
    for &x in a.iter() {
        if s(acc + x) == sign {
            acc += x;
        } else {
            ans += (acc + x - sign).abs() as u64;
            acc = sign;
        }
        sign *= -1;
    }
    ans
}

