    let mut sum = 0;
    let mut counter = 0;
    for i in 0..a.len() {
        if judge(i) {
            if sum + a[i] < 0 {
                a[i] += (sum + a[i]).abs() + 1;
                counter += (sum + a[i]).abs() + 1;
            }
        } else {
            if sum + a[i] > 0 {
                a[i] -= sum + a[i] - 1;
                counter += (sum + a[i] - 1).abs();
            }
        }
        sum += a[i];
    }
    counter
}

