fn s(x: i64) -> i64 {
    if x == 0 {
        0
    } else {
        x / x.abs()
    }
}

fn func(a: &Vec<i64>, sign: i64) -> u64 {
    let mut sign = sign;
    let mut ans = 0;
    let mut acc = 0;
    for &x in a.iter() {
        if s(acc + x) == sign {
            acc += x;
        } else {
            ans += (acc + x - sign).abs() as u64;
            acc = sign;
        }
        sign *= -1;
    }
    ans
}

fn solve() {
    let cin = stdin();
    let cin = cin.lock();
    let mut sc = Scanner::new(cin);

    loop {
        let n = sc.read();
        let a: Vec<i64> = sc.vec(n);
        let ans = func(&a, 1);
        let ans = min(ans, func(&a, -1));
        println!("{}", ans);
    }
}

