fn exec() {
    let mut sc = Scanner::new();
    let n: usize = sc.ne();
    let a: Vec<i64> = (0..n).map(|_| sc.ne()).collect();
    let f = |s: i64| -> i64 {
        let mut sum = s;
        let mut ans = 0;
        for i in 1..n {
            if sum > 0 {
                if sum + a[i] >= 0 {
                    ans += sum + a[i] + 1;
                    sum = -1;
                } else {
                    sum = a[i] + sum;
                }
            } else {
                if sum + a[i] <= 0 {
                    ans += -(sum + a[i]) + 1;
                    sum = 1;
                } else {
                    sum = sum + a[i];
                }
            }
        }
        ans
    };
    let r = a[0];
    let mut ans = std::cmp::min(f(r), f(if r > 0 { -1 } else { 1 }) + r.abs() + 1);
    if a[0] == 0 {
        ans = std::cmp::min(f(1) + 1, f(-1) + 1);
    }
    println!("{}", ans);
}

